-- =============================================================================
-- Studuel — Migration 427 : QUESTIONS EN PLUS — 6e
--
-- ⚠️ FICHIER GÉNÉRÉ — ne pas éditer à la main.
--    Regénérer : node scripts/seed-complements.mjs --num 427 --complements anglais-6e-q04,arts-plastiques-6e-q05,emc-6e-q06,francais-6e-q09,histoire-geo-6e-q26,maths-6e-q33,musique-6e-q34,physique-chimie-6e-q37,svt-6e-q38,technologie-6e-q39
--
-- Quatre questions de plus par quiz (8 → 12) : huit suffisaient pour se tester une fois, pas pour réviser sur plusieurs semaines.
--
-- Cette migration apporte : 504 questions ajoutées à des quiz existants
-- 0 cours relus (réécrits seulement si leur texte a changé)
-- et 0 questions existantes corrigées sur place (identifiant gardé).
-- AUCUN chapitre créé ni supprimé. Les chapitres sont désignés par leur clé
-- naturelle (matière, niveau, titre) : un chapitre absent est simplement sauté.
--
-- Idempotent : UUID dérivés du contenu, ON CONFLICT DO NOTHING, UPDATE gardés
-- par IS DISTINCT FROM. Rejouable sans risque.
-- À exécuter dans : Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

-- 2. Questions ------------------------------------------------------------
-- Rangées APRÈS celles du quiz : position = dernière position + rang.
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, qz.id, v.question, v.kind, v.options, v.correct_index, v.explanation,
       COALESCE((SELECT max(x.position) FROM public.quiz_questions x WHERE x.quiz_id = qz.id), 0) + v.rang
  FROM (VALUES
    ('9b5316e3-b53d-5c60-a1c0-766610edd25c'::uuid, 'anglais', '6e', 'Les pronoms personnels', 'Quel pronom complète « I know ___ » (en parlant de Sarah) ?', 'mcq', '["she","hers","her","his"]'::jsonb, 2, 'Après le verbe, on emploie le pronom complément : she devient her.', 1),
    ('fb45d0e4-24f8-5af2-960b-5b8fecfaa305'::uuid, 'anglais', '6e', 'Les pronoms personnels', 'Quel pronom complète « Give the book to ___ » (à nous) ?', 'mcq', '["we","us","our","ours"]'::jsonb, 1, 'Le pronom complément de we est us.', 2),
    ('68e669c1-9976-5ae0-9594-fe90938c6a98'::uuid, 'anglais', '6e', 'Les pronoms personnels', 'Comment dit-on la distance : « C’est à 3 km » ?', 'mcq', '["He is 3 km.","There has 3 km.","This is 3 km.","It’s 3 km."]'::jsonb, 3, 'It sert aussi pour la distance, comme pour l’heure et le temps qu’il fait.', 3),
    ('cc226ec6-7c8b-564f-b9dd-068702ed8e94'::uuid, 'anglais', '6e', 'Les pronoms personnels', 'Quelle phrase est correcte ?', 'mcq', '["Is cold today.","It is cold today.","Cold is today.","Are cold today."]'::jsonb, 1, 'En anglais, le sujet ne peut jamais être omis : on met it, même s’il ne désigne personne.', 4),
    ('6653007a-c0ac-5a21-8141-3921b1e3445f'::uuid, 'anglais', '6e', 'La phrase interrogative', 'Comment demande-t-on la distance ?', 'mcq', '["How much is it?","How long is it?","How far is it?","How many is it?"]'::jsonb, 2, 'How far sert à demander la distance ; how long, la durée ou la longueur.', 1),
    ('23a6819c-d1a9-5384-bf17-655793621090'::uuid, 'anglais', '6e', 'La phrase interrogative', 'Comment dit-on « Quand pars-tu ? » ?', 'mcq', '["When do you leave?","When you leave?","When does you leave?","Do when you leave?"]'::jsonb, 0, 'Le mot interrogatif se met devant, mais il ne remplace pas l’auxiliaire : when + do + sujet + verbe.', 2),
    ('76e43e4f-e2c9-593b-a982-80bdba7a1a74'::uuid, 'anglais', '6e', 'La phrase interrogative', 'Comment répond-on brièvement à « Does she play tennis? » ?', 'mcq', '["Yes, she plays.","Yes, she does.","Yes, she is.","Yes, she do."]'::jsonb, 1, 'On reprend l’auxiliaire de la question : does.', 3),
    ('a8170c31-39ac-5249-a8bb-c03a0e72808e'::uuid, 'anglais', '6e', 'La phrase interrogative', 'Comment dit-on « Que fait-elle en ce moment ? » ?', 'mcq', '["What she is doing?","What does she doing?","What she does doing?","What is she doing?"]'::jsonb, 3, 'Ordre : mot interrogatif, auxiliaire, sujet, verbe (what is she doing).', 4),
    ('e597a358-5b81-5c25-b245-7d129a7f96ab'::uuid, 'anglais', '6e', 'La phrase négative', 'Comment dit-on « Personne ne connaît la réponse » ?', 'mcq', '["Nobody knows the answer.","Nobody doesn’t know the answer.","Nobody don’t know the answer.","Nobody not knows the answer."]'::jsonb, 0, 'Nobody est déjà négatif : on n’ajoute pas de seconde négation.', 1),
    ('8df9d348-483b-5511-af21-a251c6d4c554'::uuid, 'anglais', '6e', 'La phrase négative', 'Comment dit-on « Il n’a pas dansé » ?', 'mcq', '["He didn’t danced.","He didn’t dance.","He not danced.","He doesn’t dance."]'::jsonb, 1, 'Au prétérit, on emploie didn’t suivi de la base verbale.', 2),
    ('b96b92f0-5972-516c-8671-7ea97e0e5a5b'::uuid, 'anglais', '6e', 'La phrase négative', 'Quelle est la contraction de « they are not » ?', 'mcq', '["they isn’t","they don’t","they aren’t","they amn’t"]'::jsonb, 2, 'Avec be, not se place après l’auxiliaire : they aren’t.', 3),
    ('2773e66a-092b-5953-a7a6-579eb86afc95'::uuid, 'anglais', '6e', 'La phrase négative', 'Quelle phrase est correcte ?', 'mcq', '["She doesn’t plays the piano.","She don’t play the piano.","She not play the piano.","She doesn’t play the piano."]'::jsonb, 3, 'Après doesn’t, le verbe revient à la base verbale, sans -s.', 4),
    ('91e907ee-c6de-5ad1-9f97-e7117452a405'::uuid, 'anglais', '6e', 'L’impératif', 'Comment dit-on à toute la classe « Ne courez pas ! » ?', 'mcq', '["Don’t running!","Don’t run!","Not run!","Don’t to run!"]'::jsonb, 1, 'Impératif négatif : don’t + base verbale, sans to ni -ing.', 1),
    ('70c1354b-af90-56f1-a30d-b8cb7f704051'::uuid, 'anglais', '6e', 'L’impératif', 'Que signifie « Let’s not argue » ?', 'mcq', '["Ne nous disputons pas","Ils ne se disputent pas","Laissez-moi me disputer","Tu ne dois pas te disputer"]'::jsonb, 0, 'Let’s + base verbale propose une action à faire ensemble ; avec not, on propose de ne pas la faire.', 2),
    ('a2e9c3bc-d1e4-5472-96c6-8240687a915c'::uuid, 'anglais', '6e', 'L’impératif', 'Que signifie « Forget it! » ?', 'mcq', '["N’oublie pas !","Oublie-moi !","Laisse tomber !","Souviens-toi !"]'::jsonb, 2, 'Don’t forget veut dire « n’oublie pas », Forget it veut dire « laisse tomber » : même verbe, sens opposés.', 3),
    ('5e896601-fa10-5c78-80b7-f43178692086'::uuid, 'anglais', '6e', 'L’impératif', 'Que demande la consigne « Fill in the blanks » ?', 'mcq', '["Relier les mots","Lire le texte","Répondre aux questions","Compléter les blancs"]'::jsonb, 3, 'Les consignes d’exercices sont à l’impératif : fill in the blanks = complète les blancs.', 4),
    ('b345ed15-d436-5f18-97a8-6767ea02668e'::uuid, 'anglais', '6e', 'Le comparatif et le superlatif', 'Quel est le superlatif de « happy » ?', 'mcq', '["the most happy","the happiest","the happyest","the happier"]'::jsonb, 1, 'Adjectif court en consonne + y : le y devient i, puis on ajoute -est.', 1),
    ('dd99de84-ea72-5e37-b699-4a811bb510c4'::uuid, 'anglais', '6e', 'Le comparatif et le superlatif', 'Quel est le comparatif de « nice » ?', 'mcq', '["nicer","niceer","more nice","nicier"]'::jsonb, 0, 'Un adjectif court en -e prend seulement -r.', 2),
    ('daa604ef-f302-591b-a4c8-2e30eac68594'::uuid, 'anglais', '6e', 'Le comparatif et le superlatif', 'Quel est le superlatif de « bad » ?', 'mcq', '["the baddest","the most bad","the worst","the worse"]'::jsonb, 2, 'Bad est irrégulier : bad, worse, the worst.', 3),
    ('29045600-31bd-5ea4-8f30-8fe255cbff5b'::uuid, 'anglais', '6e', 'Le comparatif et le superlatif', 'Que signifie « not as tall as » ?', 'mcq', '["plus grand que","aussi grand que","le plus grand","pas aussi grand que"]'::jsonb, 3, 'not as … as exprime une égalité niée : « pas aussi … que ».', 4),
    ('23bff9b2-8e0e-5e0b-91d5-2cb84b632d65'::uuid, 'anglais', '6e', 'Les noms et le pluriel', 'Quel est le pluriel de « a leaf » ?', 'mcq', '["leafs","leafes","leaves","leaf"]'::jsonb, 2, 'Beaucoup de noms en -f ou -fe font leur pluriel en -ves : leaf, leaves.', 1),
    ('eb70d50f-7527-56be-873f-e82545930b64'::uuid, 'anglais', '6e', 'Les noms et le pluriel', 'Quel est le pluriel de « a mouse » ?', 'mcq', '["mouses","mice","mouse","mices"]'::jsonb, 1, 'Mouse est un pluriel irrégulier : mice.', 2),
    ('a15087b0-aedb-534d-a926-3fb752e4a0b0'::uuid, 'anglais', '6e', 'Les noms et le pluriel', 'Quel est le pluriel de « a woman » ?', 'mcq', '["womans","womens","woman","women"]'::jsonb, 3, 'Woman est irrégulier : women.', 3),
    ('f3877b0e-d236-57f8-a0af-de57869e86b7'::uuid, 'anglais', '6e', 'Les noms et le pluriel', 'Quelle phrase est correcte ?', 'mcq', '["I have some homework.","I have a homework.","I have homeworks.","I have two homeworks."]'::jsonb, 0, 'Homework est indénombrable : ni pluriel, ni a. On dit some homework.', 4),
    ('0461850a-0b77-59e7-83a7-a6d0a9099879'::uuid, 'anglais', '6e', 'Les articles : a, an, the', 'Quel article place-t-on devant « European » ?', 'mcq', '["an","the obligatoirement","a","aucun"]'::jsonb, 2, 'European commence par le son « you », un son de consonne : a European.', 1),
    ('7505ffb4-92cb-5944-9d2f-74e4576990ff'::uuid, 'anglais', '6e', 'Les articles : a, an, the', 'Complète : « I have a dog. ___ dog is black. »', 'mcq', '["A","The","An","Aucun article"]'::jsonb, 1, 'D’abord on présente avec a, ensuite on désigne le même chien avec the.', 2),
    ('87c43a4b-50a5-5f1a-b05f-96754874587e'::uuid, 'anglais', '6e', 'Les articles : a, an, the', 'Comment dit-on « Je joue au tennis » ?', 'mcq', '["I play tennis.","I play the tennis.","I play a tennis.","I play at tennis."]'::jsonb, 0, 'Devant un sport, on ne met aucun article, contrairement au français.', 3),
    ('d3e7a1e7-f2a9-5d38-8394-6376aa1cfa7b'::uuid, 'anglais', '6e', 'Les articles : a, an, the', 'Comment dit-on « Je vis aux Pays-Bas » ?', 'mcq', '["I live in Netherlands.","I live in a Netherlands.","I live in Netherlands the.","I live in the Netherlands."]'::jsonb, 3, 'Le nom de ce pays est au pluriel : il prend the, comme the United States.', 4),
    ('561420aa-1ddf-500e-9e76-8cb42c5a2319'::uuid, 'anglais', '6e', 'Les démonstratifs : this, that, these, those', 'Comment dit-on « Ces oiseaux-là sont grands » ?', 'mcq', '["These birds are big.","That birds are big.","Those birds are big.","This birds are big."]'::jsonb, 2, 'Pluriel et éloigné : those.', 1),
    ('51a3d95c-040e-5a40-9fb5-0d7ccce4792e'::uuid, 'anglais', '6e', 'Les démonstratifs : this, that, these, those', 'Que signifie « these days » ?', 'mcq', '["ces jours-ci","ce jour-là","ce matin","ces jours-là"]'::jsonb, 0, 'These désigne ce qui est proche, y compris dans le temps : these days = ces jours-ci.', 2),
    ('03298df8-1aa5-562c-b30d-071558715267'::uuid, 'anglais', '6e', 'Les démonstratifs : this, that, these, those', 'Comment dit-on « Voici ma sœur » en la présentant ?', 'mcq', '["These is my sister.","This are my sister.","Those is my sister.","This is my sister."]'::jsonb, 3, 'Pour présenter quelqu’un, on emploie this is, au singulier.', 3),
    ('a1768e32-d0f7-5d41-912c-e00e86092a43'::uuid, 'anglais', '6e', 'Les démonstratifs : this, that, these, those', 'Quel mot se prononce avec un son long ?', 'mcq', '["this","these","that","those"]'::jsonb, 1, 'These se prononce /ðiːz/, avec un son long, alors que this est court.', 4),
    ('5814483d-6abb-5442-ab71-fb57361766af'::uuid, 'anglais', '6e', 'Exprimer la possession', 'Comment dit-on « leur maison » ?', 'mcq', '["their house","there house","theirs house","they’re house"]'::jsonb, 0, 'Their est l’adjectif possessif de they ; there veut dire « là ».', 1),
    ('3d680855-076d-5f3c-8d77-11b4353095b3'::uuid, 'anglais', '6e', 'Exprimer la possession', 'Que signifie « Those keys are ours » ?', 'mcq', '["Ces clés sont à eux","Ces clés sont à nous","Ces clés sont à elle","Ces clés sont à moi"]'::jsonb, 1, 'Ours est le pronom possessif de we : il remplace « our keys ».', 2),
    ('cff7d18b-21c2-5455-a046-017cbe7588c7'::uuid, 'anglais', '6e', 'Exprimer la possession', 'Comment dit-on « mes amis » ?', 'mcq', '["my friend","mys friends","my friends","mine friends"]'::jsonb, 2, 'L’adjectif possessif ne s’accorde jamais avec le nom : my ne prend pas de s.', 3),
    ('da13b83f-72db-55be-a493-0831f8cedbf1'::uuid, 'anglais', '6e', 'Exprimer la possession', 'Quelle phrase est correcte ?', 'mcq', '["This book is your.","This book is you.","This book is yours’s.","This book is yours."]'::jsonb, 3, 'Le pronom possessif s’emploie sans nom derrière : yours.', 4),
    ('94893ed1-3e96-5945-9059-71606f9c1c7f'::uuid, 'anglais', '6e', 'Exprimer une quantité', 'Quelle phrase est correcte ?', 'mcq', '["How much apples do you want?","How many apples do you want?","How many water do you want?","How much apple do you want?"]'::jsonb, 1, 'Apples est un dénombrable pluriel : how many.', 1),
    ('4a859043-d03b-52fa-91ca-b824b1117c90'::uuid, 'anglais', '6e', 'Exprimer une quantité', 'Comment dit-on « Il y a beaucoup d’eau » ?', 'mcq', '["There are a lot of water.","There is many water.","There is a lot of water.","There is a lot water."]'::jsonb, 2, 'A lot of s’emploie avec les indénombrables ; water est singulier : there is.', 2),
    ('72908305-f425-51e0-bc07-84e9f4302db7'::uuid, 'anglais', '6e', 'Exprimer une quantité', 'Comment dit-on « Il reste un peu de lait » ?', 'mcq', '["There is a few milk.","There is little milk.","There are a little milk.","There is a little milk."]'::jsonb, 3, 'Milk est indénombrable : a little (un peu). Little seul veut dire « peu ».', 3),
    ('958af04b-f457-57ea-a492-3b7deb6d6201'::uuid, 'anglais', '6e', 'Exprimer une quantité', 'Comment dit-on « Il a peu d’amis, il est seul » ?', 'mcq', '["He has few friends.","He has a few friends.","He has a little friends.","He has little friends."]'::jsonb, 0, 'Few, avec un dénombrable, est négatif : « peu ». A few serait « quelques ».', 4),
    ('7ef285ad-f74f-5be2-8b22-85c098755b8e'::uuid, 'anglais', '6e', 'Les adjectifs qualificatifs', 'Comment dit-on « une grande voiture rouge » ?', 'mcq', '["a red big car","a big red car","a car big red","a big car red"]'::jsonb, 1, 'L’adjectif se place devant le nom, taille avant couleur.', 1),
    ('a13894c9-a322-525e-8feb-28c4403f1007'::uuid, 'anglais', '6e', 'Les adjectifs qualificatifs', 'Quelle phrase est correcte ?', 'mcq', '["He is a spanish student.","He is a student spanish.","He is a Spaniards student.","He is a Spanish student."]'::jsonb, 3, 'Les adjectifs de nationalité prennent une majuscule et se placent devant le nom.', 2),
    ('a4e4a3bf-aff2-53c7-a4aa-9e9f03e25e98'::uuid, 'anglais', '6e', 'Les adjectifs qualificatifs', 'Comment dit-on « Ce film est effrayant » ?', 'mcq', '["The film is frightening.","The film is frightened.","The film is frighten.","The film frightens is."]'::jsonb, 0, 'Le -ing décrit ce qui provoque le sentiment ; -ed décrit celui qui le ressent.', 3),
    ('1882e641-3f3a-55d8-adf8-59680e182681'::uuid, 'anglais', '6e', 'Les adjectifs qualificatifs', 'Dans « a beautiful little old round red Italian wooden table », quel adjectif exprime l’opinion ?', 'mcq', '["little","round","beautiful","Italian"]'::jsonb, 2, 'L’opinion vient en premier dans l’ordre des adjectifs : beautiful.', 4),
    ('b9e684b2-1352-5c01-ad37-63bca91c8f83'::uuid, 'anglais', '6e', 'L’auxiliaire BE', 'Comment dit-on « Tu as raison » ?', 'mcq', '["You have right.","You are right.","You do right.","You have reason."]'::jsonb, 1, 'Là où le français dit « avoir », l’anglais dit be : you are right.', 1),
    ('50292e07-e8b1-5d08-b723-f9960dc4c0ac'::uuid, 'anglais', '6e', 'L’auxiliaire BE', 'Quelle est la contraction de « we are » ?', 'mcq', '["we’s","wer’e","we’re","we’m"]'::jsonb, 2, 'we are devient we’re.', 2),
    ('bc9081df-effc-54fd-b9d2-06a3f49dfd9d'::uuid, 'anglais', '6e', 'L’auxiliaire BE', 'Comment dit-on « Ils n’étaient pas là » ?', 'mcq', '["They wasn’t here.","They aren’t here.","They didn’t be here.","They weren’t here."]'::jsonb, 3, 'Au prétérit, be fait sa négation seul : they weren’t.', 3),
    ('59a559cb-1c78-54ef-8434-ccfb25cf2d85'::uuid, 'anglais', '6e', 'L’auxiliaire BE', 'Comment dit-on « Il y a trois chats » ?', 'mcq', '["There are three cats.","There is three cats.","It has three cats.","There have three cats."]'::jsonb, 0, 'There are s’emploie avec un pluriel.', 4),
    ('359a7f4d-c9a4-50ac-89fc-c50e76feb1ea'::uuid, 'anglais', '6e', 'HAVE GOT : la possession', 'Comment répond-on brièvement à « Has he got a car? » ?', 'mcq', '["Yes, he has.","Yes, he does.","Yes, he is.","Yes, he got."]'::jsonb, 0, 'Have got se construit sans DO : on reprend has.', 1),
    ('cdaddc36-9bfc-5ec2-baae-f92a71e9c45d'::uuid, 'anglais', '6e', 'HAVE GOT : la possession', 'Dans « He’s tired », que représente « ’s » ?', 'mcq', '["has","is","does","was"]'::jsonb, 1, 'Tired n’est pas précédé de got : ’s est is. Dans « he’s got a car », c’est has.', 2),
    ('b94ba3c1-99fa-54bb-aff3-707e27d0b2b7'::uuid, 'anglais', '6e', 'HAVE GOT : la possession', 'Comment dit-on « Ils n’ont pas de chat » avec have got ?', 'mcq', '["They hasn’t got a cat.","They don’t got a cat.","They haven’t got a cat.","They not have got a cat."]'::jsonb, 2, 'Avec they, on emploie haven’t got, sans DO.', 3),
    ('d12de236-1d68-5b0c-86ad-a021f793fcb1'::uuid, 'anglais', '6e', 'HAVE GOT : la possession', 'Quelle phrase mélange les deux formes et est incorrecte ?', 'mcq', '["Have you got a dog?","Do you have a dog?","I haven’t got a dog.","Do you have got a dog?"]'::jsonb, 3, 'Have got se construit sans DO, have seul avec DO : il ne faut pas les mélanger.', 4),
    ('a2d7f49d-785a-56c5-9911-c34c5798f749'::uuid, 'anglais', '6e', 'L’auxiliaire DO', 'Dans « Did she go? », quelle forme prend « go » ?', 'mcq', '["went","goes","go","going"]'::jsonb, 2, 'Après did, le verbe reste à la base verbale.', 1),
    ('02b58877-4a95-5a41-afe4-55d94824cad2'::uuid, 'anglais', '6e', 'L’auxiliaire DO', 'Quelle phrase est correcte ?', 'mcq', '["They doesn’t like maths.","They don’t like maths.","They not like maths.","They don’t likes maths."]'::jsonb, 1, 'They est au pluriel : don’t, puis la base verbale.', 2),
    ('72da53a7-5ad1-531f-8246-2c240cc4dbd2'::uuid, 'anglais', '6e', 'L’auxiliaire DO', 'Combien de fois le -s de la 3e personne se met-il dans une phrase ?', 'mcq', '["Une seule fois","Deux fois","Jamais","Sur chaque mot"]'::jsonb, 0, 'Il se met sur l’auxiliaire ou sur le verbe, jamais sur les deux.', 3),
    ('057e3a54-1ff5-538b-8ae6-5ec02d950878'::uuid, 'anglais', '6e', 'L’auxiliaire DO', 'Comment dit-on « As-tu fait tes devoirs ? » ?', 'mcq', '["Do you did your homework?","Did you did your homework?","Are you do your homework?","Did you do your homework?"]'::jsonb, 3, 'Le premier did est l’auxiliaire, le second do est le verbe « faire », à la base verbale.', 4),
    ('d138fc12-786c-5a43-953d-11eda48768a2'::uuid, 'anglais', '6e', 'CAN : capacité et permission', 'Comment demande-t-on la permission de sortir ?', 'mcq', '["Do I can go out?","I can go out?","Can I go out?","Can I to go out?"]'::jsonb, 2, 'La question avec can se fait par inversion, sans DO ni to.', 1),
    ('fbe555a0-9939-55a0-ab08-59e99d38e1a9'::uuid, 'anglais', '6e', 'CAN : capacité et permission', 'Comment dit-on « Je ne savais pas nager à cinq ans » ?', 'mcq', '["I didn’t can swim when I was five.","I couldn’t swim when I was five.","I can’t swimmed when I was five.","I not could swim when I was five."]'::jsonb, 1, 'Le passé de can est could ; sa négation est couldn’t.', 2),
    ('05486464-9d18-5561-83ee-9ea63c4b2f50'::uuid, 'anglais', '6e', 'CAN : capacité et permission', 'Quelle phrase est incorrecte ?', 'mcq', '["Can she swim?","She can’t swim.","She cannot swim.","She doesn’t can swim."]'::jsonb, 3, 'Can est un modal : pas de DO, la négation se fait avec not.', 3),
    ('8166f7bf-bc1e-555e-bdc3-dc38c970ba6f'::uuid, 'anglais', '6e', 'CAN : capacité et permission', 'Dans « Could you help me, please? », could est…', 'mcq', '["plus poli que can","obligatoirement au passé","une négation","un futur"]'::jsonb, 0, 'Could sert aussi de forme polie au présent.', 4),
    ('9ef2685d-3348-5f02-8aa1-61e5416aab79'::uuid, 'anglais', '6e', 'MUST : l’obligation', 'Comment dit-on « Tu devrais dormir plus » ?', 'mcq', '["You must to sleep more.","You should sleeps more.","You should sleep more.","You should to sleep more."]'::jsonb, 2, 'Should donne un conseil, suivi de la base verbale, sans to ni -s.', 1),
    ('72d64dcd-bb9d-5c7a-bd6a-7950cea5f0f4'::uuid, 'anglais', '6e', 'MUST : l’obligation', 'Dans « I have to wear a uniform at school », d’où vient l’obligation ?', 'mcq', '["D’une règle extérieure","De celui qui parle","D’un simple conseil","D’une envie personnelle"]'::jsonb, 0, 'Have to exprime une obligation venue de l’extérieur : règle, horaire, loi.', 2),
    ('cac07640-0dd3-555c-a2f1-dc6cc36e0a03'::uuid, 'anglais', '6e', 'MUST : l’obligation', 'Comment dit-on « Nous avons dû attendre » ?', 'mcq', '["We must waited.","We had to wait.","We had to waited.","We did must wait."]'::jsonb, 1, 'Must n’a pas de passé : on emploie had to, suivi de la base verbale.', 3),
    ('bf4c0512-b271-5328-8d07-ace25d01a964'::uuid, 'anglais', '6e', 'MUST : l’obligation', 'Comment dit-on « Je n’ai pas à travailler demain » ?', 'mcq', '["I mustn’t work tomorrow.","I don’t must work tomorrow.","I haven’t to work tomorrow.","I don’t have to work tomorrow."]'::jsonb, 3, 'Don’t have to signifie « ne pas être obligé » ; mustn’t signifierait « c’est interdit ».', 4),
    ('87883799-3d93-5941-bbcd-1f8ed2859196'::uuid, 'anglais', '6e', 'Le présent simple', 'Quelle est la forme correcte : « elle regarde » ?', 'mcq', '["she watches","she watchs","she watchies","she watch"]'::jsonb, 0, 'Un verbe en -ch prend -es à la 3e personne du singulier.', 1),
    ('ba1ece02-c6c9-5588-ba33-46315ef144b4'::uuid, 'anglais', '6e', 'Le présent simple', 'Comment dit-on « Il est toujours en retard » ?', 'mcq', '["He always is late.","He is always late.","Always he is late.","He is late always."]'::jsonb, 1, 'Always se place avant le verbe, mais après be.', 2),
    ('01422bea-af5a-5183-baf5-dedd4a54ff46'::uuid, 'anglais', '6e', 'Le présent simple', 'Comment dit-on « L’eau bout à 100 degrés » ?', 'mcq', '["Water boil at 100 degrees.","Water is boiling at 100 degrees.","Water boiled at 100 degrees.","Water boils at 100 degrees."]'::jsonb, 3, 'Une vérité générale se dit au présent simple, avec -s à la 3e personne.', 3),
    ('a51ad7ce-d6a0-5568-9b72-a3e45163062e'::uuid, 'anglais', '6e', 'Le présent simple', 'Quel repère de temps accompagne le présent simple ?', 'mcq', '["now","yesterday","every day","at the moment"]'::jsonb, 2, 'Every day marque une habitude, donc le présent simple.', 4),
    ('120b62ff-76b5-5318-bcab-31e0937ae27b'::uuid, 'anglais', '6e', 'Le présent en BE + -ING', 'Quelle est la forme en -ing de « lie » ?', 'mcq', '["lieing","lying","liing","lyeing"]'::jsonb, 1, 'Les verbes en -ie changent en -ying.', 1),
    ('0058873c-80f9-5f9e-b96f-93c7a70dc499'::uuid, 'anglais', '6e', 'Le présent en BE + -ING', 'Quelle phrase est correcte ?', 'mcq', '["She is understanding the lesson.","She does understanding the lesson.","She understanding the lesson.","She understands the lesson."]'::jsonb, 3, 'Understand est un verbe d’état : il ne s’emploie pas en -ing.', 2),
    ('813bce86-2872-574e-95bb-5be102edee33'::uuid, 'anglais', '6e', 'Le présent en BE + -ING', 'Quelle phrase exprime un rendez-vous déjà organisé ?', 'mcq', '["We are meeting Tom at 6.","We meet Tom every day.","We met Tom at 6.","We meeting Tom at 6."]'::jsonb, 0, 'Le présent en BE + -ING peut dire un projet proche déjà organisé.', 3),
    ('24fa5dac-0036-540c-8fa9-dda6a32207d9'::uuid, 'anglais', '6e', 'Le présent en BE + -ING', 'Comment demande-t-on « Est-ce qu’elle travaille en ce moment ? » ?', 'mcq', '["Does she working?","Do she working?","Is she working?","Is working she?"]'::jsonb, 2, 'La question se fait sans DO : c’est be qui passe devant le sujet.', 4),
    ('5b9775b7-7811-5045-8fa6-276be28de119'::uuid, 'anglais', '6e', 'Le prétérit simple', 'Quel est le prétérit de « like » ?', 'mcq', '["likeed","liked","likd","likied"]'::jsonb, 1, 'Un verbe qui finit par -e prend seulement -d.', 1),
    ('618fe624-919d-5020-832c-b0c8e2084fb5'::uuid, 'anglais', '6e', 'Le prétérit simple', 'Quel est le prétérit de « eat » ?', 'mcq', '["eated","eat","ate","eaten"]'::jsonb, 2, 'Eat est irrégulier : ate. Eaten est le participe passé.', 2),
    ('92db4c34-98f8-51ea-893d-795b6f1d4458'::uuid, 'anglais', '6e', 'Le prétérit simple', 'Comment se prononce le -ed de « wanted » ?', 'mcq', '["/t/","/d/","On ne le prononce pas","/ɪd/"]'::jsonb, 3, 'Après un t ou un d, le -ed se prononce /ɪd/ : wanted, needed.', 3),
    ('36a29e23-7dd2-55eb-bbae-2fd75c62c47a'::uuid, 'anglais', '6e', 'Le prétérit simple', 'Que dit « When I was young, I played football » ?', 'mcq', '["Une habitude passée","Une action en cours","Un projet futur","Une vérité générale"]'::jsonb, 0, 'Le prétérit sert aussi à dire une habitude passée.', 4),
    ('26b3ec3b-4428-52c2-a9e4-866b907fbf30'::uuid, 'anglais', '6e', 'Les verbes irréguliers', 'Quel est le prétérit de « buy » ?', 'mcq', '["buyed","bought","boughten","buyt"]'::jsonb, 1, 'Buy fait partie de la famille dont les deux dernières formes sont identiques : buy, bought, bought.', 1),
    ('b0637aa3-dd2c-520e-a585-e83b906df3c7'::uuid, 'anglais', '6e', 'Les verbes irréguliers', 'Quel est le participe passé de « write » ?', 'mcq', '["wrote","writed","written","writen"]'::jsonb, 2, 'Write, wrote, written : le prétérit et le participe sont différents.', 2),
    ('35962a3c-ec62-51f7-a040-4a30ed6ab6b0'::uuid, 'anglais', '6e', 'Les verbes irréguliers', 'Quel est le participe passé de « know » ?', 'mcq', '["knew","knowed","knowen","known"]'::jsonb, 3, 'Know, knew, known.', 3),
    ('e3be87ec-f9fa-5761-8bca-80986defc345'::uuid, 'anglais', '6e', 'Les verbes irréguliers', 'Quel verbe suit le schéma « sing — sang — sung » ?', 'mcq', '["swim","teach","cut","let"]'::jsonb, 0, 'Swim, swam, swum suit le schéma i, a, u, comme sing et begin.', 4),
    ('7d8d1e7b-87a7-578b-b340-d39730a002a1'::uuid, 'anglais', '6e', 'Exprimer le futur', 'Quelle forme convient à une promesse ?', 'mcq', '["be going to","le présent simple","le présent en BE + -ING","will"]'::jsonb, 3, 'Will exprime une décision sur le moment, une prédiction ou une promesse.', 1),
    ('1acdadf4-44de-5c2d-84ff-a2af8686d6fd'::uuid, 'anglais', '6e', 'Exprimer le futur', 'Comment dit-on « Il ne viendra pas » ?', 'mcq', '["He won’t comes.","He won’t come.","He doesn’t will come.","He not will come."]'::jsonb, 1, 'Won’t est la négation de will, suivi de la base verbale.', 2),
    ('268a3b80-f870-5635-a9cd-173741d40474'::uuid, 'anglais', '6e', 'Exprimer le futur', 'Quel repère de temps appelle le futur ?', 'mcq', '["tomorrow","yesterday","last week","two days ago"]'::jsonb, 0, 'Tomorrow, next week, soon regardent vers l’avenir.', 3),
    ('f2c43d01-10e6-52e7-91ca-8d310d7000ba'::uuid, 'anglais', '6e', 'Exprimer le futur', 'Comment dit-on « Vas-tu venir ? » avec going to ?', 'mcq', '["Do you going to come?","Going you to come?","Are you going to come?","Will you going to come?"]'::jsonb, 2, 'Avec be going to, c’est be qui passe devant le sujet.', 4),
    ('31e4e663-4e4d-5665-8c8c-7fa14a32c4ef'::uuid, 'arts-plastiques', '6e', 'La couleur', 'Comment obtient-on une couleur tertiaire ?', 'mcq', '["Deux primaires mélangées","Du noir ajouté à une primaire","Une primaire et une secondaire voisine","Deux secondaires opposées"]'::jsonb, 2, 'Une couleur tertiaire naît du mélange d’une primaire et d’une secondaire voisine sur le cercle chromatique.', 1),
    ('0c52b83b-de37-5549-9efd-9105434444c8'::uuid, 'arts-plastiques', '6e', 'La couleur', 'Quelle est la complémentaire du jaune ?', 'mcq', '["Le vert","Le violet","L’orange","Le bleu"]'::jsonb, 1, 'Jaune et violet se font face sur le cercle chromatique : ce sont des couleurs complémentaires.', 2),
    ('51100987-4d98-588b-85b7-3abb11bf9ec7'::uuid, 'arts-plastiques', '6e', 'La couleur', 'Que se passe-t-il quand on place deux couleurs complémentaires côte à côte ?', 'mcq', '["Elles se renforcent","Elles donnent un gris","Elles disparaissent","Elles deviennent tertiaires"]'::jsonb, 0, 'Côte à côte, elles se renforcent et paraissent plus vives ; mélangées, elles s’éteignent en gris.', 3),
    ('5eb6a54b-2856-57fa-ad48-1272b179f9a0'::uuid, 'arts-plastiques', '6e', 'La couleur', 'Une couleur peut être à la fois vive et sombre.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Valeur (clair ou sombre) et saturation (intensité) sont indépendantes : un rouge profond est vif et sombre.', 4),
    ('2d079cfc-a8dd-5a68-bdcd-e4a34da1acca'::uuid, 'arts-plastiques', '6e', 'La représentation de l’espace', 'Combien de points de fuite faut-il pour une vue frontale ?', 'mcq', '["Deux","Aucun","Trois","Un"]'::jsonb, 3, 'Une vue frontale n’a qu’un point de fuite ; la vue d’angle en demande deux.', 1),
    ('2b28225a-3c87-5bb4-86ce-af9fc8242127'::uuid, 'arts-plastiques', '6e', 'La représentation de l’espace', 'Dans le procédé de la taille relative, un objet qui paraît plus petit est…', 'mcq', '["Plus proche","Plus lointain","Plus sombre","Au premier plan"]'::jsonb, 1, 'Plus un objet est petit dans l’image, plus on comprend qu’il est loin.', 2),
    ('b99c5dfb-d915-5a7e-b3a5-6cea38cbc46f'::uuid, 'arts-plastiques', '6e', 'La représentation de l’espace', 'Quel artiste utilise la perspective atmosphérique dans les arrière-plans de ses tableaux ?', 'mcq', '["Pablo Picasso","Jackson Pollock","Max Ernst","Léonard de Vinci"]'::jsonb, 3, 'Léonard de Vinci pâlit et bleuit les lointains pour créer de la profondeur.', 3),
    ('a18c1e40-01a4-59c5-9119-2a8455fc56be'::uuid, 'arts-plastiques', '6e', 'La représentation de l’espace', 'Sur quelle ligne se situe le point de fuite ?', 'mcq', '["La ligne d’horizon","Le bord du cadre","La ligne du sol","La diagonale"]'::jsonb, 0, 'Le point de fuite se place sur la ligne d’horizon, à hauteur des yeux du spectateur.', 4),
    ('19c750ff-a2ae-5bc1-a42c-f1c1bb8d8d0e'::uuid, 'arts-plastiques', '6e', 'Matières, outils et gestes', 'Parmi ces matériaux, lequel est une matière rapportée ?', 'mcq', '["La gouache","Le fusain","L’aquarelle","Un morceau de tissu"]'::jsonb, 3, 'Les matières rapportées (papiers, tissus, objets récupérés) sont ajoutées à l’œuvre.', 1),
    ('b30e033c-f7f9-5da3-b6bc-3558a9b68f65'::uuid, 'arts-plastiques', '6e', 'Matières, outils et gestes', 'Quel artiste est associé au dripping ?', 'mcq', '["Max Ernst","Jackson Pollock","Claude Monet","Auguste Rodin"]'::jsonb, 1, 'Jackson Pollock laisse couler et goutter la peinture sur la toile.', 2),
    ('40cb3d95-3aee-5c49-a9a1-0b010d7c7b1b'::uuid, 'arts-plastiques', '6e', 'Matières, outils et gestes', 'Le hasard en art est de la négligence.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le hasard maîtrisé est une décision : l’artiste provoque l’accident puis choisit de le garder.', 3),
    ('96e09dff-94a3-522c-9d59-f7cfca812597'::uuid, 'arts-plastiques', '6e', 'Matières, outils et gestes', 'Quelle famille regroupe le crayon, le fusain et l’encre ?', 'mcq', '["Les traçants","Les peintures","Les supports","Les matières rapportées"]'::jsonb, 0, 'Crayon, fusain et encre laissent un trait : ce sont des traçants.', 4),
    ('93901079-2cd3-5cc5-9767-4d80595b9ede'::uuid, 'emc', '6e', 'La règle et la loi', 'Quel type de texte se place juste sous la Constitution ?', 'mcq', '["Les règlements","Les décrets","Les lois","Les règles de classe"]'::jsonb, 2, 'La hiérarchie des normes va de la Constitution aux lois, puis aux décrets et aux règlements.', 1),
    ('61d39e88-7c97-5d13-8805-6a88e67ce422'::uuid, 'emc', '6e', 'La règle et la loi', 'Dans quel document officiel la loi est-elle publiée ?', 'mcq', '["Le Journal officiel","Le Code de la route","La Constitution","Le règlement intérieur"]'::jsonb, 0, 'La loi est publiée au Journal officiel, pour que tous puissent la connaître.', 2),
    ('239e849e-e84d-5fae-bd80-8a0e13258fe1'::uuid, 'emc', '6e', 'La règle et la loi', 'Qui promulgue la loi une fois qu’elle est votée ?', 'mcq', '["Le Sénat","Le maire","Le Premier ministre","Le président de la République"]'::jsonb, 3, 'Après le vote des deux chambres et l’éventuel contrôle du Conseil constitutionnel, le président promulgue la loi.', 3),
    ('49c950d0-b299-5fec-aa39-c96edf87edf1'::uuid, 'emc', '6e', 'La règle et la loi', 'Une sanction est avant tout une vengeance.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La sanction doit être proportionnée, prévue à l’avance et expliquée ; elle vise aussi à réparer.', 4),
    ('69fc2155-1431-549e-80e9-272c5b64dafa'::uuid, 'emc', '6e', 'S’engager : le délégué, les associations, les secours', 'Que permet le conseil de la vie collégienne (CVC) ?', 'mcq', '["De noter les professeurs","De proposer des projets sur la vie de l’établissement","De choisir les programmes","De remplacer le conseil de classe"]'::jsonb, 1, 'Au CVC, les élèves élus proposent des projets qui améliorent la vie du collège.', 1),
    ('5e674e05-c0cc-5580-878f-f46dc30a71b3'::uuid, 'emc', '6e', 'S’engager : le délégué, les associations, les secours', 'Quel numéro d’urgence fonctionne dans toute l’Europe ?', 'mcq', '["Le 15","Le 18","Le 112","Le 17"]'::jsonb, 2, 'Le 112 est le numéro d’urgence européen, joignable depuis n’importe quel téléphone.', 2),
    ('4737e187-bf2c-5110-8747-8c4ccf7da6c9'::uuid, 'emc', '6e', 'S’engager : le délégué, les associations, les secours', 'Que doit faire le délégué après un conseil de classe ?', 'mcq', '["Garder les résultats pour lui","Donner son avis personnel","Punir les élèves","Rendre compte à ses camarades"]'::jsonb, 3, 'Le délégué représente la classe : il porte sa parole puis lui rend des comptes, sans dévoiler ce qui est confidentiel.', 3),
    ('4a838c30-df5c-5441-83d1-95471986f48f'::uuid, 'emc', '6e', 'S’engager : le délégué, les associations, les secours', 'Ne pas porter secours à quelqu’un en danger, quand on peut le faire, est un délit.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est la non-assistance à personne en danger. Appeler les secours, c’est déjà porter secours.', 4),
    ('50137d90-32df-50e0-8d34-45581868c507'::uuid, 'emc', '6e', 'Les symboles de la République française', 'En quelle année naît le drapeau tricolore ?', 'mcq', '["1715","1848","1790","1958"]'::jsonb, 2, 'En 1790, le drapeau tricolore réunit le bleu et le rouge de Paris et le blanc du roi.', 1),
    ('7ccc47f3-0c06-5c7a-8370-f44bbccd1c3b'::uuid, 'emc', '6e', 'Les symboles de la République française', 'En quelle année la Marseillaise devient-elle hymne national ?', 'mcq', '["1792","1879","1804","1958"]'::jsonb, 1, 'Écrite en 1792 par Rouget de Lisle, elle ne devient hymne national qu’en 1879.', 2),
    ('728f5fc6-dcea-5ce6-a5c9-0d58ac34c16e'::uuid, 'emc', '6e', 'Les symboles de la République française', 'Quels événements le 14 Juillet commémore-t-il ?', 'mcq', '["La mort du roi et la fin de la guerre","La proclamation de la République","L’abolition de l’esclavage","La prise de la Bastille et la Fête de la Fédération"]'::jsonb, 3, 'Le 14 Juillet rappelle la prise de la Bastille (1789) et la Fête de la Fédération (1790), qui célébrait l’unité de la Nation.', 3),
    ('a572ddec-15b1-5fdc-b488-54791b6868ed'::uuid, 'emc', '6e', 'Les symboles de la République française', 'Qui portait le bonnet phrygien dans la Rome antique ?', 'mcq', '["Les esclaves affranchis","Les empereurs","Les soldats","Les marchands"]'::jsonb, 0, 'Le bonnet phrygien était porté par les esclaves affranchis : il symbolise donc la liberté.', 4),
    ('8db456d0-b80e-5a35-b6b5-8af0f5a27b6d'::uuid, 'emc', '6e', 'La devise : liberté, égalité, fraternité', 'Un élève dyslexique reçoit du temps en plus lors d’un contrôle. Que représente ce temps ?', 'mcq', '["Un privilège injuste","Une mesure d’équité","Une punition","Une récompense"]'::jsonb, 1, 'Ce n’est pas un privilège : c’est ce qui rétablit une égalité réelle entre élèves.', 1),
    ('f1acb93b-214e-5a8a-8d41-9eb3b010e8ee'::uuid, 'emc', '6e', 'La devise : liberté, égalité, fraternité', 'Que produirait une égalité absolue ?', 'mcq', '["Plus de solidarité","Davantage de liberté","La suppression des choix","Des écarts plus grands"]'::jsonb, 2, 'Une égalité absolue supprimerait les choix ; une liberté totale, elle, creuserait les écarts.', 2),
    ('a780bae7-28ce-5850-9692-0cc0cbafec2b'::uuid, 'emc', '6e', 'La devise : liberté, égalité, fraternité', 'Que produirait une liberté totale, sans égalité ni fraternité ?', 'mcq', '["Un creusement des écarts","Plus d’égalité","Davantage de lois","Une école gratuite"]'::jsonb, 0, 'Sans limite, les plus forts l’emportent : la liberté totale creuse les écarts.', 3),
    ('210e1547-5681-5ff8-a1f7-27a363416320'::uuid, 'emc', '6e', 'La devise : liberté, égalité, fraternité', 'Quelle valeur de la devise ne s’impose pas par la loi et se pratique surtout ?', 'mcq', '["La liberté","L’égalité","La justice","La fraternité"]'::jsonb, 3, 'La fraternité se pratique : entraide, solidarité. Elle touche pourtant le droit avec le délit de non-assistance.', 4),
    ('e96f21c9-a6fe-5a02-bce1-6b52ccbb08fd'::uuid, 'emc', '6e', 'La laïcité à l’école', 'Que fait l’État laïque pour les cultes depuis 1905 ?', 'mcq', '["Il en finance un seul","Il n’en finance aucun","Il les interdit","Il choisit leurs responsables"]'::jsonb, 1, 'La loi de 1905 met fin au financement public des cultes et garantit à chacun le libre exercice de sa religion.', 1),
    ('7d42a769-d6e9-596c-a6ae-feffa88af4ff'::uuid, 'emc', '6e', 'La laïcité à l’école', 'Que doit s’interdire un élève dans une école publique ?', 'mcq', '["Croire en une religion","Parler des religions en cours","Changer de croyance","Porter un signe religieux ostensible"]'::jsonb, 3, 'La loi de 2004 interdit les signes religieux ostensibles ; croire reste entièrement libre.', 2),
    ('9b397c4a-bbbf-511a-b150-b7d437d60017'::uuid, 'emc', '6e', 'La laïcité à l’école', 'Que sont la connaissance et la pratique d’une religion, du point de vue de la laïcité ?', 'mcq', '["Toutes deux interdites","Toutes deux obligatoires","Un savoir pour l’une, un choix privé pour l’autre","Un choix privé pour la connaissance seulement"]'::jsonb, 2, 'Connaître les religions est un savoir prévu par les programmes ; les pratiquer est un choix privé.', 3),
    ('c5aa60f5-e532-5836-a008-d34b3608da31'::uuid, 'emc', '6e', 'La laïcité à l’école', 'La laïcité garantit aussi la liberté de ne croire en aucune religion.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La liberté de conscience permet de croire, de ne pas croire, ou de changer d’avis.', 4),
    ('b49248cc-c9ea-5a65-9669-3e4897e8d4ee'::uuid, 'emc', '6e', 'Le respect d’autrui, et les différences', 'Laquelle de ces phrases est un stéréotype ?', 'mcq', '["Léa a raté son contrôle","Les filles ne savent pas jouer au foot","Tom a changé d’école","Ce garçon est en retard"]'::jsonb, 1, 'Un stéréotype est une idée toute faite sur tout un groupe, sans preuve.', 1),
    ('1c37438c-8255-5bfb-9f6f-3b073a52c107'::uuid, 'emc', '6e', 'Le respect d’autrui, et les différences', 'Que peut-on faire de ses préjugés ?', 'mcq', '["Les ignorer","Les partager","Les défendre","Les vérifier avant d’agir"]'::jsonb, 3, 'On ne choisit pas d’avoir des préjugés, mais on peut choisir de les vérifier avant d’agir.', 2),
    ('5ec566bd-c192-5e5a-965a-2e9d7f6d1991'::uuid, 'emc', '6e', 'Le respect d’autrui, et les différences', 'Lequel de ces gestes est un geste de respect ?', 'mcq', '["Écouter sans couper la parole","Donner un surnom qui fait rire","Rire d’une différence","Éviter un camarade"]'::jsonb, 0, 'Le respect se voit dans des gestes : écouter, ne pas se moquer, s’excuser quand on a blessé.', 3),
    ('916b1764-d6b0-5845-bae5-a931400e882e'::uuid, 'emc', '6e', 'Le respect d’autrui, et les différences', 'La dignité d’une personne dépend de ses notes ou de son argent.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La dignité ne se mérite pas et ne se perd pas : elle ne dépend ni des notes, ni de l’argent.', 4),
    ('ee424ca6-aced-5820-95a6-caa3785c743a'::uuid, 'emc', '6e', 'Le harcèlement : reconnaître et agir', 'Mise à l’écart et rumeurs : de quelle forme de harcèlement s’agit-il ?', 'mcq', '["Physique","Sociale","Matérielle","Verbale"]'::jsonb, 1, 'La forme sociale du harcèlement passe par l’exclusion du groupe et les rumeurs.', 1),
    ('d2dfd234-9482-525b-bd6b-2c0bd79fdbb7'::uuid, 'emc', '6e', 'Le harcèlement : reconnaître et agir', 'Quel numéro appeler pour signaler un enfant en danger ?', 'mcq', '["Le 3018","Le 112","Le 119","Le 15"]'::jsonb, 2, 'Le 119 est le numéro de l’enfance en danger ; le 3018 est celui du harcèlement et du cyberharcèlement.', 2),
    ('356ac85e-30fb-50b3-a9b6-7cf1661072e9'::uuid, 'emc', '6e', 'Le harcèlement : reconnaître et agir', 'Que faire face aux provocations d’un harceleur en ligne ?', 'mcq', '["Répondre plus fort","Publier ses messages","Le menacer en retour","Ne pas répondre et bloquer"]'::jsonb, 3, 'Répondre alimente le harcèlement : on ne répond pas, on bloque, on garde les preuves et on en parle à un adulte.', 3),
    ('6c14ada2-735d-5517-9327-21b99bde334e'::uuid, 'emc', '6e', 'Le harcèlement : reconnaître et agir', 'Une dispute entre deux élèves à égalité est du harcèlement.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le harcèlement suppose répétition, intention de nuire et déséquilibre de force : ces trois critères comptent ensemble.', 4),
    ('c3857f77-8898-5810-b73e-400023e8b2e4'::uuid, 'emc', '6e', 'L’égalité entre les filles et les garçons', 'Que peut provoquer le stéréotype « les maths, c’est pour les garçons » ?', 'mcq', '["Un meilleur niveau en maths","Une loi nouvelle","Une baisse des salaires","Des choix d’études orientés"]'::jsonb, 3, 'Ces idées sans fondement orientent des choix d’études dès 15 ans.', 1),
    ('124c84af-84cc-5af8-8a90-5b09285adce4'::uuid, 'emc', '6e', 'L’égalité entre les filles et les garçons', 'À travail comparable, que constate-t-on aujourd’hui sur les salaires ?', 'mcq', '["Les femmes gagnent plus","Les femmes gagnent encore moins","Les salaires sont égaux","Les hommes gagnent moins"]'::jsonb, 1, 'Malgré la loi de 1972, l’égalité salariale n’est toujours pas atteinte.', 2),
    ('6d3d6163-c0f7-5c40-a5ee-b28de848484e'::uuid, 'emc', '6e', 'L’égalité entre les filles et les garçons', 'Quand le consentement peut-il être retiré ?', 'mcq', '["Jamais après avoir dit oui","Seulement pour les adultes","À tout moment","Seulement par écrit"]'::jsonb, 2, 'Le consentement est libre, clair, et peut être retiré à tout moment.', 3),
    ('5dde43b2-94a0-5dd8-9415-fd4ebe271c7d'::uuid, 'emc', '6e', 'L’égalité entre les filles et les garçons', 'Une blague sexiste est une simple maladresse.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Blagues rabaissantes et remarques sur le corps sont des atteintes, pas des maladresses.', 4),
    ('618d7ff9-5b3d-55b9-b59e-251b3759fb52'::uuid, 'francais', '6e', 'Créer une autre manière de s’exprimer grâce à la poésie', 'Quel schéma correspond à des rimes embrassées ?', 'mcq', '["AABB","ABAB","ABBA","ABCD"]'::jsonb, 2, 'Les rimes embrassées suivent le schéma ABBA : une rime en enveloppe une autre.', 1),
    ('4c338a83-ad02-50e4-aedd-14321fdcc828'::uuid, 'francais', '6e', 'Créer une autre manière de s’exprimer grâce à la poésie', 'Combien de syllabes compte un décasyllabe ?', 'mcq', '["Dix","Huit","Douze","Onze"]'::jsonb, 0, 'Le préfixe déca- indique dix. L’octosyllabe en compte huit, l’alexandrin douze.', 2),
    ('8136086e-0d88-5fb5-bb7d-52a7a61dff6a'::uuid, 'francais', '6e', 'Créer une autre manière de s’exprimer grâce à la poésie', 'Quelle phrase contient une métaphore ?', 'mcq', '["Elle court comme le vent.","Elle est une flèche.","Elle court tel le vent.","Elle est semblable au vent."]'::jsonb, 1, 'La métaphore rapproche deux éléments sans outil de comparaison (comme, tel, semblable à).', 3),
    ('b10e220e-9061-58e6-8ac3-8200751e9452'::uuid, 'francais', '6e', 'Créer une autre manière de s’exprimer grâce à la poésie', 'Qu’est-ce qu’une assonance ?', 'mcq', '["La répétition d’un son consonne","Une comparaison sans outil","Un vers de dix syllabes","La répétition d’un son voyelle"]'::jsonb, 3, 'L’assonance répète un son voyelle, alors que l’allitération répète un son consonne.', 4),
    ('8d34a34c-7ff6-5480-8f67-e67724e08429'::uuid, 'francais', '6e', 'La poésie pour chanter et enchanter le monde', 'Comment appelle-t-on l’adresse directe comme dans « Ô temps ! suspends ton vol » ?', 'mcq', '["Une allitération","Une apostrophe","Un refrain","Un calligramme"]'::jsonb, 1, 'L’apostrophe, avec l’exclamation, est une marque du lyrisme : le poète s’adresse à quelqu’un ou à quelque chose.', 1),
    ('99a6f9f0-c3b2-5562-ae8c-ce0cf6d0f5a7'::uuid, 'francais', '6e', 'La poésie pour chanter et enchanter le monde', 'Que faut-il faire pour bien dire un poème à voix haute ?', 'mcq', '["Respecter les pauses et varier le volume","Le lire le plus vite possible","Le lire sans intonation","Ignorer la ponctuation"]'::jsonb, 0, 'Un poème s’entend autant qu’il se lit : pauses, images détachées et volume qui varie.', 2),
    ('2a5538d3-9a65-52a3-97b5-22010f95739f'::uuid, 'francais', '6e', 'La poésie pour chanter et enchanter le monde', 'Qu’est-ce qui produit le rythme d’un poème ?', 'mcq', '["Le nom de l’auteur","La date d’écriture","La longueur des vers et les pauses","Le titre du recueil"]'::jsonb, 2, 'Le rythme vient de la longueur des vers et des pauses.', 3),
    ('2ce30b57-656f-5e88-8351-13cb66dc82ae'::uuid, 'francais', '6e', 'La poésie pour chanter et enchanter le monde', 'Quel champ lexical trouve-t-on souvent dans la poésie lyrique ?', 'mcq', '["Celui du commerce","Celui de la mécanique","Celui du sentiment","Celui du droit"]'::jsonb, 2, 'La poésie lyrique exprime des sentiments : joie, amour, tristesse, émerveillement.', 4),
    ('979e8a28-db5a-5a3b-8cc5-dde2746feed9'::uuid, 'francais', '6e', 'Jeux d’ani-mots : Jacques Roubaud, Les Animaux de tout le monde', 'Qu’est-ce qu’un lipogramme ?', 'mcq', '["Un texte écrit sans employer la lettre e","Un poème fait de mots-valises","Un texte écrit uniquement en vers libres","Un poème sans aucune rime"]'::jsonb, 0, 'Le lipogramme est une contrainte de l’Oulipo : n’employer aucun e.', 1),
    ('207b9c43-a93d-5a31-b2e4-e8a930b93710'::uuid, 'francais', '6e', 'Jeux d’ani-mots : Jacques Roubaud, Les Animaux de tout le monde', 'En quoi consiste la méthode S + 7 ?', 'mcq', '["Écrire sept vers par strophe","Remplacer chaque nom par le septième qui le suit dans le dictionnaire","Répéter sept fois le même mot","Écrire un poème de sept syllabes par vers"]'::jsonb, 1, 'La méthode S + 7 remplace chaque nom par le septième qui le suit dans le dictionnaire.', 2),
    ('7abd3674-fddb-5f18-ac67-25ccf58c803c'::uuid, 'francais', '6e', 'Jeux d’ani-mots : Jacques Roubaud, Les Animaux de tout le monde', 'Que signifie Oulipo ?', 'mcq', '["Ouvroir de linguistique populaire","Œuvres uniques de la littérature pour enfants","Ouvroir de littérature potentielle","Organisation de la littérature poétique"]'::jsonb, 2, 'Oulipo = OUvroir de LIttérature POtentielle : un groupe d’écrivains qui s’imposent des contraintes.', 3),
    ('ccd43056-1a4e-5906-95eb-b0c30c1e52ad'::uuid, 'francais', '6e', 'Jeux d’ani-mots : Jacques Roubaud, Les Animaux de tout le monde', 'D’où vient l’humour des poèmes de Roubaud ?', 'mcq', '["De la violence des sujets","De la longueur des vers","De l’absence de rimes","Du décalage entre la forme sérieuse et le sujet drôle"]'::jsonb, 3, 'L’humour naît du décalage entre le sérieux de la forme poétique et la drôlerie du sujet.', 4),
    ('75ce5741-dac7-559f-8a8f-d99a820b7d37'::uuid, 'francais', '6e', 'Créer, recréer le monde : récits des origines dans les différentes religions monothéistes', 'Quelles religions partagent le récit de la Genèse, avec des variantes ?', 'mcq', '["Le judaïsme, le christianisme et l’islam","L’hindouisme, le bouddhisme et le shintoïsme","Les religions grecque, romaine et égyptienne","Le judaïsme, l’islam et l’hindouisme"]'::jsonb, 0, 'Ce sont les trois monothéismes : judaïsme, christianisme et islam.', 1),
    ('b37b07b3-7ac2-5432-b2eb-870b08a3930c'::uuid, 'francais', '6e', 'Créer, recréer le monde : récits des origines dans les différentes religions monothéistes', 'Comment la création progresse-t-elle dans la Genèse ?', 'mcq', '["Des animaux vers la lumière","Du plus général au plus particulier","Du plus particulier au plus général","De l’humain vers le ciel"]'::jsonb, 1, 'La création va du plus général (la lumière, le ciel) au plus particulier (les animaux, l’humain).', 2),
    ('949ca80e-3235-52ac-adcd-ee7529a4b604'::uuid, 'francais', '6e', 'Créer, recréer le monde : récits des origines dans les différentes religions monothéistes', 'Que signifie « parole créatrice » dans ce récit ?', 'mcq', '["Dieu écrit un livre","Dieu chante un poème","Dire suffit à faire exister","Dieu répète une prière"]'::jsonb, 2, 'Ici, dire suffit à faire exister : « Dieu dit… et cela fut ainsi ».', 3),
    ('5980a966-5f49-546c-a202-0747f694c3d1'::uuid, 'francais', '6e', 'Créer, recréer le monde : récits des origines dans les différentes religions monothéistes', 'Que sont « au commencement », « puis », « le septième jour » ?', 'mcq', '["Des rimes","Des personnifications","Des didascalies","Des connecteurs de temps"]'::jsonb, 3, 'Les connecteurs de temps organisent le récit dans la durée.', 4),
    ('6d6cd20b-a9fc-57ba-8018-e79e3f290c4b'::uuid, 'francais', '6e', 'Création et recréation du monde dans les différentes religions polythéistes', 'Quel est le domaine du dieu grec Hadès ?', 'mcq', '["Le ciel","La guerre","Les Enfers","La sagesse"]'::jsonb, 2, 'Hadès règne sur les Enfers ; Zeus sur le ciel, Arès sur la guerre, Athéna sur la sagesse.', 1),
    ('e0f56b8c-9eea-57bf-b810-6de09f07ba0d'::uuid, 'francais', '6e', 'Création et recréation du monde dans les différentes religions polythéistes', 'Quel mot vient du nom du dieu Pan ?', 'mcq', '["narcissique","panique","dédale","titanesque"]'::jsonb, 1, 'Le dieu Pan a donné « panique » ; Narcisse a donné « narcissique ».', 2),
    ('d36a861f-10a3-52cd-ac67-222c42e79d7a'::uuid, 'francais', '6e', 'Création et recréation du monde dans les différentes religions polythéistes', 'Comment se situe L’Épopée de Gilgamesh, qui contient un déluge, par rapport à la Bible ?', 'mcq', '["C’est un récit grec","Elle a été écrite par Hésiode","Elle est plus récente","Elle est bien plus ancienne"]'::jsonb, 3, 'Le motif du déluge existait chez les Mésopotamiens bien avant la Bible.', 3),
    ('55783276-ed7c-5ad1-ae58-7b7a027cc773'::uuid, 'francais', '6e', 'Création et recréation du monde dans les différentes religions polythéistes', 'Qui a écrit La Théogonie, récit de la naissance des dieux grecs ?', 'mcq', '["Hésiode","Homère","Ovide","Platon"]'::jsonb, 0, 'Hésiode raconte dans La Théogonie la succession du Chaos, de Gaïa, d’Ouranos, de Cronos puis de Zeus.', 4),
    ('62515770-0908-5083-8dff-8a46d2242fc3'::uuid, 'francais', '6e', 'Un conte étiologique : « Comment le chameau eut sa bosse », Histoires comme ça, de Rudyard Kipling', 'Que signifie le mot grec aitia, à l’origine de « étiologique » ?', 'mcq', '["Le conte","L’animal","La cause","La fin"]'::jsonb, 2, 'Étiologique vient de aitia, la cause : le conte explique la cause d’une chose.', 1),
    ('1ff463ce-280f-5ef6-92e2-371617c6ac0b'::uuid, 'francais', '6e', 'Un conte étiologique : « Comment le chameau eut sa bosse », Histoires comme ça, de Rudyard Kipling', 'Qui punit le chameau paresseux ?', 'mcq', '["Le Djinn du désert","Le lion","Le roi","Le chef des hommes"]'::jsonb, 0, 'Le Djinn du désert transforme le « Bof ! » du chameau en bosse.', 2),
    ('9ddc68ae-9afb-559d-9486-43c83641ef82'::uuid, 'francais', '6e', 'Un conte étiologique : « Comment le chameau eut sa bosse », Histoires comme ça, de Rudyard Kipling', 'Quelle est la deuxième étape de la structure d’un conte étiologique ?', 'mcq', '["La situation finale","La morale","Un dialogue","Un événement : une faute, une ruse ou une punition"]'::jsonb, 3, 'Structure : situation initiale, événement, puis situation finale qui explique l’état actuel.', 3),
    ('8eba9b80-dfa5-521b-aeba-ee5f1c648c31'::uuid, 'francais', '6e', 'Un conte étiologique : « Comment le chameau eut sa bosse », Histoires comme ça, de Rudyard Kipling', 'À quoi sert la bosse dans le conte ?', 'mcq', '["À voir de très loin","À travailler trois jours sans manger","À courir plus vite dans le sable","À effrayer les autres animaux"]'::jsonb, 1, 'La bosse permet au chameau de travailler trois jours sans manger.', 4),
    ('11598afb-cd68-5ce7-ba96-f38717b4b345'::uuid, 'francais', '6e', 'Le Médecin malgré lui, Molière', 'En combien d’actes est écrit Le Médecin malgré lui ?', 'mcq', '["Trois","Cinq","Un","Quatre"]'::jsonb, 0, 'C’est une comédie en trois actes.', 1),
    ('6612ae0b-bb49-5e16-8862-de6883db3a61'::uuid, 'francais', '6e', 'Le Médecin malgré lui, Molière', 'Comment Martine se venge-t-elle de Sganarelle ?', 'mcq', '["Elle le quitte","Elle le fait passer pour un médecin","Elle appelle un vrai médecin","Elle le dénonce au roi"]'::jsonb, 1, 'Martine, battue par son mari, le fait passer pour un médecin génial qu’on ne fait avouer que sous les coups.', 2),
    ('d1b91278-d540-5380-8e62-923b2fc49ba4'::uuid, 'francais', '6e', 'Le Médecin malgré lui, Molière', 'Qu’est-ce qu’un monologue ?', 'mcq', '["Une longue réplique dite à plusieurs","Une indication de mise en scène","Un personnage seul en scène qui parle","Ce qu’un personnage dit sans être entendu"]'::jsonb, 2, 'Le monologue est prononcé par un personnage seul en scène ; l’aparté n’est pas entendu des autres personnages.', 3),
    ('4ec9231a-312a-5ba7-ae70-69b2bb466d33'::uuid, 'francais', '6e', 'Le Médecin malgré lui, Molière', 'Que débite Sganarelle pour impressionner ses malades ?', 'mcq', '["De l’italien","Des vers","Du grec ancien","Du faux latin"]'::jsonb, 3, 'Son faux latin est un comique de mots : personne n’ose le contredire.', 4),
    ('c5eef20c-447e-5270-8069-1011e2c3495c'::uuid, 'francais', '6e', 'Les Fourberies de Scapin, Molière', 'Qui sont Octave et Léandre ?', 'mcq', '["Les deux pères","Les jeunes gens amoureux","Des valets","Des médecins"]'::jsonb, 1, 'Octave et Léandre sont les jeunes amoureux que Scapin aide contre leurs pères, Argante et Géronte.', 1),
    ('e28c0a8c-803b-58d5-ad09-dc8346c736ba'::uuid, 'francais', '6e', 'Les Fourberies de Scapin, Molière', 'Dans quel acte se trouve la scène du sac ?', 'mcq', '["Acte III","Acte I","Acte II","Acte V"]'::jsonb, 0, 'La scène du sac, la plus célèbre, se déroule à l’acte III.', 2),
    ('e1f65b87-80b5-542a-ad3a-42725f24d20c'::uuid, 'francais', '6e', 'Les Fourberies de Scapin, Molière', 'Qu’est-ce qui est le moteur de la pièce ?', 'mcq', '["Un duel","Un voyage","Chaque mensonge en appelle un autre","Un héritage"]'::jsonb, 2, 'Scapin invente un mensonge après l’autre : c’est la mécanique de la pièce.', 3),
    ('9791d8a1-bf65-5fce-bfa5-a6cec9ea28a5'::uuid, 'francais', '6e', 'Les Fourberies de Scapin, Molière', 'Comment s’appelle le valet rusé de la commedia dell’arte ?', 'mcq', '["Le chœur","Le coryphée","Le bouffon","Le zanni"]'::jsonb, 3, 'Le zanni est l’ancêtre italien du valet rusé comme Scapin.', 4),
    ('8222cf4e-bbe1-5c4d-a2aa-309765f4ca21'::uuid, 'francais', '6e', 'Le théâtre, un art de l’illusion ?', 'Comment finit une comédie ?', 'mcq', '["Elle finit mal","Elle finit bien","Elle ne finit pas","Elle finit par un deuil"]'::jsonb, 1, 'La comédie met en scène des personnages ordinaires et finit bien ; la tragédie finit mal.', 1),
    ('54752d19-4ee3-5ec3-b87b-81d1b850716e'::uuid, 'francais', '6e', 'Le théâtre, un art de l’illusion ?', 'Comment appelle-t-on l’espace de jeu des acteurs ?', 'mcq', '["Le plateau","Les coulisses","Le parterre","La régie"]'::jsonb, 0, 'Le plateau est l’espace de jeu ; les coulisses sont l’espace caché.', 2),
    ('4a872c37-d8c2-5201-a636-3956ccc9ec21'::uuid, 'francais', '6e', 'Le théâtre, un art de l’illusion ?', 'Quel outil de l’illusion apporte le personnage ?', 'mcq', '["Le décor","La musique","Le costume et le maquillage","La lumière"]'::jsonb, 2, 'Le costume et le maquillage font le personnage, alors que le décor fait le lieu.', 3),
    ('fe73e043-790d-5f71-a89d-a3b42935556b'::uuid, 'francais', '6e', 'Le théâtre, un art de l’illusion ?', 'Quel est le rôle de la lumière au théâtre ?', 'mcq', '["Elle remplace les acteurs","Elle cache le texte","Elle annonce l’entracte","Elle isole, colore et rythme"]'::jsonb, 3, 'La lumière isole un personnage, colore l’atmosphère et rythme le spectacle.', 4),
    ('44d061cb-0497-5a12-80ba-3bb9d85c00d3'::uuid, 'francais', '6e', 'Le Petit Chaperon Rouge de Joël Pommerat', 'En quelle année Pommerat a-t-il écrit Le Petit Chaperon Rouge ?', 'mcq', '["1666","1990","1902","2004"]'::jsonb, 3, 'C’est une pièce contemporaine de 2004, alors que le conte de Perrault date du XVIIe siècle.', 1),
    ('e0e64f6a-debb-52f0-ad2e-996158621377'::uuid, 'francais', '6e', 'Le Petit Chaperon Rouge de Joël Pommerat', 'Quel mot désigne le fait d’imiter en exagérant pour faire rire ?', 'mcq', '["Parodier","Adapter","Réécrire","Traduire"]'::jsonb, 0, 'Parodier fait rire ; Pommerat réécrit et adapte, il ne parodie pas.', 2),
    ('1dea7b1b-bc33-50ab-82cb-e3f3b359d400'::uuid, 'francais', '6e', 'Le Petit Chaperon Rouge de Joël Pommerat', 'Sous quelle forme apparaît souvent le loup dans la pièce ?', 'mcq', '["Un chien","Un costume réaliste","Une ombre, une voix, une silhouette","Un dessin animé"]'::jsonb, 2, 'Le loup est souvent une ombre ou une voix : la peur naît de ce qu’on ne voit pas.', 3),
    ('0d92fa1b-78a7-57dc-8e4a-9d58b65811ea'::uuid, 'francais', '6e', 'Le Petit Chaperon Rouge de Joël Pommerat', 'Quel thème traverse la pièce ?', 'mcq', '["La guerre","L’enfance qui grandit","La richesse","La vieillesse"]'::jsonb, 1, 'Quitter la maison, désobéir, affronter la peur, revenir changé : le conte parle de l’enfance qui grandit.', 4),
    ('855f400c-46fa-510e-bef1-f942bfa849fe'::uuid, 'histoire-geo', '6e', 'Habiter les littoraux', 'Comment s’appelle la concentration croissante des hommes et des activités sur les côtes ?', 'mcq', '["La métropolisation","La littoralisation","La périurbanisation","La sédentarisation"]'::jsonb, 1, 'La littoralisation est ce mouvement qui attire de plus en plus d’habitants et d’activités vers le rivage.', 1),
    ('3ae40529-16bc-5781-97f2-5a5a7c93895c'::uuid, 'histoire-geo', '6e', 'Habiter les littoraux', 'Laquelle de ces destinations est un littoral touristique ?', 'mcq', '["Rotterdam","Singapour","Le Havre","Cancún"]'::jsonb, 3, 'Cancún, comme la Côte d’Azur, les Baléares ou Bali, vit du tourisme ; Rotterdam, Singapour et Le Havre sont d’abord des ports.', 2),
    ('dea004ce-d22d-59f6-8274-a9d94d158e84'::uuid, 'histoire-geo', '6e', 'Habiter les littoraux', 'Quel organisme français achète et protège des espaces naturels du rivage ?', 'mcq', '["L’Office des ports","Le Conseil des marées","Le Conservatoire du littoral","La Zone industrialo-portuaire"]'::jsonb, 2, 'Le Conservatoire du littoral, avec la loi Littoral, limite la bétonisation des côtes françaises.', 3),
    ('b038004a-eb1c-516c-b319-e9a1a290677f'::uuid, 'histoire-geo', '6e', 'Habiter les littoraux', 'Que désigne la « submersion » d’un littoral ?', 'mcq', '["L’envahissement de la côte par la mer lors de tempêtes ou de cyclones","Le recul lent d’une falaise","Le dépôt de sable sur une plage","La pollution par une marée noire"]'::jsonb, 0, 'La submersion est une inondation marine brutale, provoquée par les tempêtes et les cyclones ; elle menace de plus en plus de côtes.', 4),
    ('4519f9a9-94d8-57c0-b61a-5a6863d13072'::uuid, 'histoire-geo', '6e', 'Habiter un espace à fortes contraintes naturelles', 'Lequel de ces espaces est marqué par la sécheresse ?', 'mcq', '["Le Groenland","L’Himalaya","L’Atacama","Le bassin du Congo"]'::jsonb, 2, 'L’Atacama, comme le Sahara et l’Australie centrale, est un désert : l’eau y commande tout.', 1),
    ('55fe457b-8c11-5d7b-8c41-5557301777c8'::uuid, 'histoire-geo', '6e', 'Habiter un espace à fortes contraintes naturelles', 'Quel ordre de grandeur définit un espace de faible densité ?', 'mcq', '["Moins de 300 hab./km²","Moins de 30 hab./km²","Moins de 3 hab./km²","Moins de 3 000 hab./km²"]'::jsonb, 1, 'On parle de faible densité en dessous d’environ 30 habitants par km².', 2),
    ('17db33ea-eacb-580b-87d8-a060d6c50810'::uuid, 'histoire-geo', '6e', 'Habiter un espace à fortes contraintes naturelles', 'À quoi servent les cultures en terrasses en montagne ?', 'mcq', '["À rapprocher les villages","À protéger du froid","À éviter le nomadisme","À retenir la terre et l’eau sur les pentes"]'::jsonb, 3, 'Les terrasses transforment une pente en marches plates : la terre et l’eau ne dévalent plus.', 3),
    ('ff7f79c7-8454-5de1-be8d-72f7aad9460c'::uuid, 'histoire-geo', '6e', 'Habiter un espace à fortes contraintes naturelles', 'Pourquoi construit-on des maisons sur pilotis ou sur pieux ?', 'mcq', '["Pour se protéger du gel du sol et des inondations","Pour rester au frais en été","Pour cultiver sous la maison","Pour économiser du bois"]'::jsonb, 0, 'Sur sol gelé ou inondable, surélever la maison est la réponse humaine à la contrainte.', 4),
    ('82dfa95b-4ee9-502a-be1f-ac6ae0e211b0'::uuid, 'histoire-geo', '6e', 'Habiter un espace de grande biodiversité', 'Quelle île abrite environ 80 % d’espèces endémiques ?', 'mcq', '["Le Brésil","Madagascar","L’Australie","Bornéo"]'::jsonb, 1, 'Madagascar est un haut lieu de biodiversité : 80 % de ses espèces ne vivent nulle part ailleurs.', 1),
    ('9b76851b-35b8-5df6-ac71-911caf5ecb0d'::uuid, 'histoire-geo', '6e', 'Habiter un espace de grande biodiversité', 'Combien d’espèces de poissons la Grande Barrière de corail abrite-t-elle ?', 'mcq', '["150","15 000","1 500","500"]'::jsonb, 2, 'Environ 1 500 espèces de poissons vivent dans la Grande Barrière de corail, en Australie.', 2),
    ('4a3a7c11-ef3a-5587-b33d-27e512cfee6f'::uuid, 'histoire-geo', '6e', 'Habiter un espace de grande biodiversité', 'Quel métal polluant les fleuves à cause de l’orpaillage ?', 'mcq', '["Le mercure","Le plomb","Le fer","Le cuivre"]'::jsonb, 0, 'Les orpailleurs utilisent du mercure, qui empoisonne les fleuves et ceux qui y pêchent.', 3),
    ('426d639c-ab56-55b5-9412-e88d19ec3b2a'::uuid, 'histoire-geo', '6e', 'Habiter un espace de grande biodiversité', 'Quelle solution cherche-t-on entre protéger un milieu et le développer ?', 'mcq', '["La mise sous cloche totale","L’exploitation intensive","Le tourisme de masse","Le développement durable"]'::jsonb, 3, 'Le développement durable permet aux habitants de vivre correctement sans détruire ce dont ils dépendent.', 4),
    ('066f9303-27e7-5524-aa40-8383dd90bc6b'::uuid, 'histoire-geo', '6e', 'Habiter le monde rural', 'Lequel de ces espaces est une campagne agricole productive ?', 'mcq', '["La Beauce","La Côte d’Azur","La Défense","Le Marais"]'::jsonb, 0, 'La Beauce est une région de grandes cultures mécanisées : peu d’actifs, forte production.', 1),
    ('8ab3d0f2-b1a0-54f3-8a8d-262b077c5283'::uuid, 'histoire-geo', '6e', 'Habiter le monde rural', 'Que désigne-t-on par « zones blanches » ?', 'mcq', '["Des régions enneigées","Des zones sans médecin","Des zones sans bonne connexion internet","Des zones sans école"]'::jsonb, 2, 'Les zones blanches sont mal couvertes par internet : une inégalité de plus dans les campagnes peu denses.', 2),
    ('9f1f57b7-9601-5f80-87d8-f95261efeaf9'::uuid, 'histoire-geo', '6e', 'Habiter le monde rural', 'Quel effet le télétravail a-t-il sur certaines campagnes ?', 'mcq', '["Il accélère l’exode rural","Il renforce leur attractivité","Il supprime l’agriculture","Il ferme les écoles"]'::jsonb, 1, 'On peut vivre à la campagne tout en travaillant à distance : certaines campagnes regagnent des habitants.', 3),
    ('5a6cd542-02e2-55aa-95ae-be20cb9a694e'::uuid, 'histoire-geo', '6e', 'Habiter le monde rural', 'Quelles énergies les espaces ruraux produisent-ils de plus en plus ?', 'mcq', '["Le charbon et le pétrole","Le gaz de schiste et l’uranium","Les hydrocarbures de mer","Le solaire, l’éolien et la méthanisation"]'::jsonb, 3, 'Éoliennes, panneaux solaires et méthaniseurs font des campagnes des espaces producteurs d’énergie.', 4),
    ('55794458-28f2-5c5c-a014-91a198b6ff44'::uuid, 'histoire-geo', '6e', 'Les métropoles et leurs habitants', 'Que signifie « métropole » en grec ?', 'mcq', '["La ville-reine","La grande route","La ville-port","La ville-mère"]'::jsonb, 3, 'Le mot vient du grec : la « ville-mère », celle qui commande et rayonne.', 1),
    ('8de34aff-9686-5c8a-a871-f8425442f255'::uuid, 'histoire-geo', '6e', 'Les métropoles et leurs habitants', 'Quel est un quartier d’affaires (CBD) de la métropole parisienne ?', 'mcq', '["La Défense","Montmartre","Le Marais","Le Louvre"]'::jsonb, 0, 'La Défense, comme Manhattan à New York, aligne des tours de bureaux.', 2),
    ('28e69765-a154-58f8-9408-2bc3a84f2d4e'::uuid, 'histoire-geo', '6e', 'Les métropoles et leurs habitants', 'Quelle est la part approximative de citadins dans la population mondiale aujourd’hui ?', 'mcq', '["Environ 30 %","Environ 45 %","Près de 60 %","Près de 90 %"]'::jsonb, 2, 'Depuis 2007, plus de la moitié de l’humanité vit en ville ; on approche aujourd’hui 60 %.', 3),
    ('484f158d-0741-5776-b8f3-6fd442033f2b'::uuid, 'histoire-geo', '6e', 'Les métropoles et leurs habitants', 'Laquelle de ces villes est une ville mondiale ?', 'mcq', '["Nîmes","Londres","Cancún","Bali"]'::jsonb, 1, 'New York, Londres, Tokyo, Paris et Shanghai commandent l’économie mondiale.', 4),
    ('3d6c8ad2-c333-5989-bb14-e249f3f3a081'::uuid, 'histoire-geo', '6e', 'Les défis des métropoles', 'Combien d’habitants Lagos comptait-elle environ en 1950 ?', 'mcq', '["300 000","3 millions","15 millions","30 000"]'::jsonb, 0, 'Lagos est passée de 300 000 habitants en 1950 à plus de 15 millions aujourd’hui.', 1),
    ('68875059-202d-5047-b18e-a10aeb0d37c3'::uuid, 'histoire-geo', '6e', 'Les défis des métropoles', 'Que manque-t-il souvent dans un bidonville ?', 'mcq', '["Des téléphones","Des routes goudronnées","L’eau courante et les égouts","Des commerces"]'::jsonb, 2, 'L’habitat auto-construit est souvent sans titre de propriété, sans eau courante, sans électricité ni égouts.', 2),
    ('13f2cde5-6131-5271-bac4-61f965bd81a3'::uuid, 'histoire-geo', '6e', 'Les défis des métropoles', 'Quel risque menace particulièrement Tokyo ?', 'mcq', '["Les cyclones","Les inondations marines","Les avalanches","Les séismes"]'::jsonb, 3, 'Plus la densité est forte, plus les personnes exposées sont nombreuses : Tokyo est exposée aux séismes.', 3),
    ('5efeeaf7-8b13-5d0c-a266-762704693214'::uuid, 'histoire-geo', '6e', 'Les défis des métropoles', 'Quelle conséquence a la pollution de l’air dans les grandes villes ?', 'mcq', '["Elle réchauffe les campagnes","Des millions de décès prématurés par an","Elle fait baisser les températures","Elle supprime les déchets"]'::jsonb, 1, 'La pollution de l’air provoque des millions de décès prématurés chaque année dans le monde.', 4),
    ('ac2f301e-da7b-5ea1-8c82-7f132e8573cc'::uuid, 'histoire-geo', '6e', 'Habiter la ville de demain', 'Que signifie « bâtiment à énergie positive » ?', 'mcq', '["Il consomme un peu moins qu’avant","Il produit plus d’énergie qu’il n’en consomme","Il ne consomme aucune énergie","Il est chauffé au charbon"]'::jsonb, 1, 'Un bâtiment à énergie positive produit plus qu’il ne consomme, par exemple grâce à des panneaux solaires.', 1),
    ('fe71e299-f12b-5813-9b1e-dd0c0893eb5c'::uuid, 'histoire-geo', '6e', 'Habiter la ville de demain', 'Dans quelle ville se trouve l’écoquartier Vauban ?', 'mcq', '["Stockholm","Londres","Lyon","Fribourg"]'::jsonb, 3, 'Vauban est à Fribourg, en Allemagne ; Hammarby est à Stockholm, BedZED à Londres, Confluence à Lyon.', 2),
    ('65a2f9c1-c12e-59f6-8c6d-82bcf339d587'::uuid, 'histoire-geo', '6e', 'Habiter la ville de demain', 'Que veut dire « économie circulaire » ?', 'mcq', '["Trier, réparer, réutiliser, composter","Bâtir des routes en cercle","Faire circuler plus d’argent","Relier les banlieues par une rocade"]'::jsonb, 0, 'L’économie circulaire limite les déchets en réutilisant tout ce qui peut l’être.', 3),
    ('71136557-7b49-57a8-88c0-53f2348b8160'::uuid, 'histoire-geo', '6e', 'Habiter la ville de demain', 'Comment les projets urbains réussis associent-ils les habitants ?', 'mcq', '["En les déplaçant","En les tenant à l’écart","Par la concertation et les budgets participatifs","En leur imposant les plans"]'::jsonb, 2, 'Une ville se fait avec ceux qui y vivent : concertation, budgets participatifs, jardins partagés.', 4),
    ('a716ff54-f474-5a31-a683-01ae98ca0761'::uuid, 'histoire-geo', '6e', 'Les conquêtes et la gestion de l’Empire romain', 'Contre quelle cité Rome mène-t-elle les guerres puniques (264-146 av. J.-C.) ?', 'mcq', '["Athènes","Carthage","Troie","Babylone"]'::jsonb, 1, 'Les guerres puniques opposent Rome à Carthage ; la victoire de Rome lui ouvre la Méditerranée.', 1),
    ('fc1bc6a2-9614-5989-9c5b-b15330464bc7'::uuid, 'histoire-geo', '6e', 'Les conquêtes et la gestion de l’Empire romain', 'Où se trouve le mur d’Hadrien, fortification du limes ?', 'mcq', '["En Gaule","En Germanie","En Égypte","En Bretagne"]'::jsonb, 3, 'Le mur d’Hadrien protège la province de Bretagne, au nord de l’Empire.', 2),
    ('285cd845-fa86-5465-b3d1-36c683e1ae7f'::uuid, 'histoire-geo', '6e', 'Les conquêtes et la gestion de l’Empire romain', 'Quel titre fait de l’empereur le chef de la religion ?', 'mcq', '["Imperator","Pontifex maximus","Consul","Censeur"]'::jsonb, 1, 'Imperator désigne le chef des armées ; Pontifex maximus, le grand pontife, chef de la religion.', 3),
    ('8367bebc-5e96-501a-9d0e-e5c763856981'::uuid, 'histoire-geo', '6e', 'Les conquêtes et la gestion de l’Empire romain', 'À quoi servent les bornes milliaires ?', 'mcq', '["À marquer les tombeaux","À poster des soldats","À jalonner les routes en indiquant les distances","À relayer les messages"]'::jsonb, 2, 'Les routes romaines, longues de plus de 80 000 km, étaient jalonnées de bornes milliaires.', 4),
    ('45e2686c-5fa2-5891-8407-74bcd137167f'::uuid, 'histoire-geo', '6e', 'Paix romaine et romanisation dans l’Empire romain', 'Quelle ville actuelle s’appelait Lugdunum ?', 'mcq', '["Nîmes","Arles","Lyon","Paris"]'::jsonb, 2, 'Lugdunum est Lyon ; Nemausus est Nîmes et Arelate est Arles.', 1),
    ('4eeae3ab-5a81-5ae1-8fb6-be08ee0e0605'::uuid, 'histoire-geo', '6e', 'Paix romaine et romanisation dans l’Empire romain', 'Quels cultes venus d’Orient se diffusent dans l’Empire ?', 'mcq', '["Zeus et Apollon","Baal et Moloch","Odin et Thor","Isis et Mithra"]'::jsonb, 3, 'Isis (Égypte) et Mithra (Perse) attirent de nombreux fidèles dans l’Empire.', 2),
    ('189c002b-69b6-5867-b181-48a344e06fb2'::uuid, 'histoire-geo', '6e', 'Paix romaine et romanisation dans l’Empire romain', 'Comment appelle-t-on l’association des dieux locaux aux dieux romains ?', 'mcq', '["Le monothéisme","Le syncrétisme","Le polythéisme","L’éphébie"]'::jsonb, 1, 'Le syncrétisme mêle les divinités : Rome assimile les dieux gaulois aux siens plutôt que de les interdire.', 3),
    ('9a3086fd-376a-5f8f-aa91-8546ad8412cd'::uuid, 'histoire-geo', '6e', 'Paix romaine et romanisation dans l’Empire romain', 'Quel héritage romain structure encore nos codes de lois ?', 'mcq', '["Le droit romain","Le droit gaulois","Le droit grec","Le code de Hammurabi"]'::jsonb, 0, 'Le droit romain, diffusé dans tout l’Empire, structure encore notre droit.', 4),
    ('d7429876-63c1-5a54-bda5-8f6dcbd3eb8a'::uuid, 'histoire-geo', '6e', 'Les débuts du christianisme', 'Qu’est-ce que l’eucharistie chez les premiers chrétiens ?', 'mcq', '["Un pèlerinage","Un chant","Un baptême","Un repas partagé"]'::jsonb, 3, 'Les premières communautés partagent un repas, l’eucharistie, et pratiquent l’entraide.', 1),
    ('db7ebaa2-4dbc-5a22-80bc-e695682efc41'::uuid, 'histoire-geo', '6e', 'Les débuts du christianisme', 'Qu’est-ce que le christianisme hérite du judaïsme ?', 'mcq', '["Le culte de l’empereur","Le polythéisme","Le monothéisme et la Bible","Les sacrifices d’animaux"]'::jsonb, 2, 'Les chrétiens gardent la Bible et le Dieu unique, mais ajoutent la foi en Jésus-Christ.', 2),
    ('f3d8a4aa-f4a0-510d-8740-69471a042530'::uuid, 'histoire-geo', '6e', 'Les débuts du christianisme', 'Que sont les Évangiles pour l’historien ?', 'mcq', '["Des rapports officiels romains","Des textes de foi écrits des décennies après","Des témoignages directs de Tacite","Des lois de l’Empire"]'::jsonb, 1, 'Les Évangiles disent ce que les chrétiens croyaient ; Tacite atteste seulement que le mouvement existait.', 3),
    ('23eb14e9-fd18-5a3e-a896-b1c20542bc32'::uuid, 'histoire-geo', '6e', 'Les débuts du christianisme', 'Où se réunissent les premières communautés chrétiennes ?', 'mcq', '["Dans de grandes basiliques","Dans les temples romains","Dans les thermes","Dans des maisons"]'::jsonb, 3, 'Les premières communautés sont urbaines et modestes ; les basiliques viendront plus tard.', 4),
    ('249b1a95-13fe-5eef-978b-cb81c3686b3e'::uuid, 'histoire-geo', '6e', 'Les chrétiens et le christianisme dans l’Empire romain', 'Quel empereur mène la persécution la plus violente, de 303 à 311 ?', 'mcq', '["Néron","Dèce","Dioclétien","Constantin"]'::jsonb, 2, 'La persécution de Dioclétien est la plus violente ; Dèce avait persécuté au IIIe siècle.', 1),
    ('f7b7afcc-8b48-50f8-9093-2306219a2100'::uuid, 'histoire-geo', '6e', 'Les chrétiens et le christianisme dans l’Empire romain', 'Quel symbole discret les chrétiens utilisent-ils ?', 'mcq', '["La colombe rouge","L’aigle","Le laurier","Le poisson"]'::jsonb, 3, 'Le poisson, en grec ichthus, sert de symbole discret de reconnaissance.', 2),
    ('b4ed8346-5372-53b8-be87-c8394ae5c73a'::uuid, 'histoire-geo', '6e', 'Les chrétiens et le christianisme dans l’Empire romain', 'Quelles traces témoignent des premiers chrétiens ?', 'mcq', '["Les pyramides","Les catacombes et les sarcophages sculptés","Les aqueducs","Les arcs de triomphe"]'::jsonb, 1, 'Catacombes, premières basiliques et sarcophages sculptés sont les traces des premiers chrétiens.', 3),
    ('a564dcc6-8abb-5919-b303-2445b6f88eff'::uuid, 'histoire-geo', '6e', 'Les chrétiens et le christianisme dans l’Empire romain', 'Que désignait d’abord le mot « Église » (ekklesia) ?', 'mcq', '["La communauté des fidèles","Le bâtiment du culte","Le chef de la communauté","L’assemblée des évêques"]'::jsonb, 0, 'Ekklesia veut dire assemblée : l’Église est d’abord la communauté, pas le bâtiment.', 4),
    ('9cdc6109-9fd1-5c32-af05-c98aab5c04a6'::uuid, 'histoire-geo', '6e', 'La Chine des Han', 'Que fait Qin Shi Huangdi après avoir unifié la Chine ?', 'mcq', '["Il multiplie les monnaies","Il unifie l’écriture, les poids et mesures et la monnaie","Il supprime l’armée","Il abolit l’empire"]'::jsonb, 1, 'Unifier l’écriture, les mesures et la monnaie permet de gouverner un immense territoire.', 1),
    ('dae6cb5b-6147-5f65-a2f7-62a30e63a2ff'::uuid, 'histoire-geo', '6e', 'La Chine des Han', 'Combien de statues compte l’armée de terre cuite de Qin Shi Huangdi ?', 'mcq', '["Environ 80","Environ 800","Environ 80 000","Plus de 8 000"]'::jsonb, 3, 'Plus de 8 000 statues ont été enterrées avec le premier empereur.', 2),
    ('23916b0d-03b4-5d64-af9c-35afb1776435'::uuid, 'histoire-geo', '6e', 'La Chine des Han', 'Qu’est-ce que le « mandat céleste » ?', 'mcq', '["Le droit de gouverner donné par le Ciel, qui peut se perdre","Un titre transmis à vie par le sang","Un impôt versé au temple","Un concours pour devenir fonctionnaire"]'::jsonb, 0, 'Une catastrophe ou une révolte peut être lue comme le retrait du mandat : le pouvoir est absolu mais jamais garanti.', 3),
    ('dd6cab2d-c64d-5191-81b4-6513465e98e9'::uuid, 'histoire-geo', '6e', 'La Chine des Han', 'Laquelle de ces inventions vient de la Chine des Han ?', 'mcq', '["Le verre soufflé","L’aqueduc","La brouette","L’alphabet"]'::jsonb, 2, 'La Chine invente la brouette, le sismographe, le gouvernail d’étambot, la boussole et le papier.', 4),
    ('8e4fb043-6482-590f-88ef-b90684d63de8'::uuid, 'histoire-geo', '6e', 'Les débuts de l’humanité', 'Quelle innovation apparaît avec Homo habilis, vers 2,5 millions d’années ?', 'mcq', '["Le feu","L’arc","Les outils taillés","La poterie"]'::jsonb, 2, 'Homo habilis taille les premiers outils ; la maîtrise du feu vient avec Homo erectus.', 1),
    ('2b4f50c4-c180-55a4-bad5-88cd144f3241'::uuid, 'histoire-geo', '6e', 'Les débuts de l’humanité', 'Quelle grotte ornée est la plus ancienne ?', 'mcq', '["Lascaux","Chauvet","Toutes deux datent du Néolithique","Elles ont le même âge"]'::jsonb, 1, 'Chauvet date d’environ 36 000 ans, Lascaux d’environ 18 000 ans.', 2),
    ('f2047e96-df6a-5fe0-bae4-7e2e27ac37dd'::uuid, 'histoire-geo', '6e', 'Les débuts de l’humanité', 'Comment s’appelle la science qui met au jour les traces des sociétés passées ?', 'mcq', '["La stratigraphie","La géologie","La généalogie","L’archéologie"]'::jsonb, 3, 'L’archéologie fouille outils, ossements, foyers et peintures, que le carbone 14 permet de dater.', 3),
    ('553b749c-c116-5d79-93ab-fa9bcec0abea'::uuid, 'histoire-geo', '6e', 'Les débuts de l’humanité', 'Quelle part du temps humain le Paléolithique occupe-t-il ?', 'mcq', '["Environ 50 %","Plus de 99 %","Environ 75 %","Moins de 10 %"]'::jsonb, 1, 'Le Paléolithique couvre presque toute l’histoire humaine : plus de 99 % du temps.', 4),
    ('2fb7debd-b06b-5c52-a0e6-c35ae6086e74'::uuid, 'histoire-geo', '6e', 'Les migrations et le mode de vie des premiers êtres humains', 'Comment les premiers humains ont-ils atteint l’Australie ?', 'mcq', '["En naviguant pour franchir des bras de mer","À pied par un passage émergé","En traversant l’Atlantique","Par le détroit de Béring"]'::jsonb, 0, 'Même aux plus bas niveaux de la mer, il restait des bras de mer à franchir : il a fallu naviguer.', 1),
    ('fb4abe70-1a2b-5e27-88bb-836f58483f99'::uuid, 'histoire-geo', '6e', 'Les migrations et le mode de vie des premiers êtres humains', 'Pourquoi pouvait-on franchir le détroit de Béring à pied ?', 'mcq', '["Un pont naturel le reliait","Un pont avait été construit","Il était gelé toute l’année","Le niveau des mers avait baissé pendant la glaciation"]'::jsonb, 3, 'L’eau piégée dans les glaces avait fait baisser le niveau des mers : le détroit était à sec.', 2),
    ('e47b47d7-649f-52c0-91cc-394f677c1455'::uuid, 'histoire-geo', '6e', 'Les migrations et le mode de vie des premiers êtres humains', 'Vers quelle date l’Amérique est-elle atteinte ?', 'mcq', '["Vers 100 000 ans","Vers 20 000 à 15 000 ans","Vers 5 000 ans","Vers 60 000 ans"]'::jsonb, 1, 'L’Amérique est le dernier grand continent peuplé, il y a environ 20 000 à 15 000 ans.', 3),
    ('e0f76ff3-e246-5528-84f4-875090e3150c'::uuid, 'histoire-geo', '6e', 'Les migrations et le mode de vie des premiers êtres humains', 'Quelle adaptation technique permet de vivre dans les milieux tropicaux ?', 'mcq', '["Des vêtements de fourrure","Des lampes à graisse","Des habitats légers","Des igloos de glace"]'::jsonb, 2, 'Chaque milieu appelle sa solution : habitats légers sous les tropiques, vêtements cousus dans le froid.', 4),
    ('15b152ed-75c1-5cd7-b8de-1abea33771a2'::uuid, 'histoire-geo', '6e', 'La révolution néolithique', 'Quelles plantes sont cultivées dans les premiers champs du Néolithique ?', 'mcq', '["Maïs et pomme de terre","Blé, orge et lentilles","Riz et soja","Vigne et olivier"]'::jsonb, 1, 'Dans le Croissant fertile, on sème blé, orge et lentilles.', 1),
    ('784ba38b-c90b-5fd4-8c60-27236d6f7cb8'::uuid, 'histoire-geo', '6e', 'La révolution néolithique', 'Quel animal figure parmi les premiers domestiqués ?', 'mcq', '["Le lion","Le renard","Le cheval","Le mouton"]'::jsonb, 3, 'Chèvre, mouton, bœuf et porc sont les premiers animaux domestiqués.', 2),
    ('d7e6278b-a784-5ab7-aa7d-0029a92defd0'::uuid, 'histoire-geo', '6e', 'La révolution néolithique', 'Pourquoi le grenier est-il aussi la naissance de l’inégalité ?', 'mcq', '["Ce qui se stocke peut s’accumuler","Il attire les voyageurs","Le grain se vend très cher","Il oblige à chasser davantage"]'::jsonb, 0, 'Tant qu’on ne stocke rien, il n’y a rien à posséder ; avec les surplus apparaissent richesse et inégalité.', 3),
    ('2734b427-dfe0-5848-8278-452a34354b3d'::uuid, 'histoire-geo', '6e', 'La révolution néolithique', 'Quel site témoigne des chantiers collectifs néolithiques ?', 'mcq', '["Gizeh","Lascaux","Carnac","Delphes"]'::jsonb, 2, 'Les alignements de Carnac et Stonehenge montrent des sociétés capables d’organiser de grands chantiers.', 4),
    ('dc42c020-aace-5d91-88b7-84f2f98d90a2'::uuid, 'histoire-geo', '6e', 'Les premiers États', 'Quel pays actuel correspond à la Mésopotamie ?', 'mcq', '["L’Égypte","La Turquie","L’Iran","L’Irak"]'::jsonb, 3, 'La Mésopotamie, entre le Tigre et l’Euphrate, correspond à l’Irak actuel.', 1),
    ('2ff2a02e-d349-5d8e-9599-2955cd414923'::uuid, 'histoire-geo', '6e', 'Les premiers États', 'Quel est le rôle des scribes dans l’État ?', 'mcq', '["Ils écrivent, tiennent les comptes et rédigent lois et contrats","Ils commandent l’armée","Ils cultivent les champs","Ils dirigent les temples"]'::jsonb, 0, 'Le scribe est un fonctionnaire longuement formé : sans lui, l’État ne pourrait ni prélever l’impôt ni conserver ses lois.', 2),
    ('fdba183d-0907-59c2-a352-42dafebc4b71'::uuid, 'histoire-geo', '6e', 'Les premiers États', 'Quelles sont trois cités-États de Mésopotamie ?', 'mcq', '["Athènes, Sparte, Corinthe","Rome, Carthage, Tyr","Ur, Uruk, Lagash","Thèbes, Memphis, Gizeh"]'::jsonb, 2, 'Ur, Uruk et Lagash ont chacune leur roi, leur dieu et leur ziggurat.', 3),
    ('d7f8255d-a309-5378-8033-73a4871d5edb'::uuid, 'histoire-geo', '6e', 'Les premiers États', 'Pourquoi l’irrigation appelle-t-elle un pouvoir central ?', 'mcq', '["Elle amuse les paysans","Elle demande d’organiser le travail de milliers de personnes","Elle sert à cacher les récoltes","Elle favorise le commerce maritime"]'::jsonb, 1, 'Creuser des canaux exige une organisation collective : le besoin d’organisation appelle l’État.', 4),
    ('372908f5-1a11-503a-aed1-3b65589f8e00'::uuid, 'histoire-geo', '6e', 'Une diversité d’États dans le Croissant fertile', 'Qui fonde l’empire d’Akkad, et vers quelle date ?', 'mcq', '["Hammurabi, vers 2300 av. J.-C.","Hammurabi, vers 1750 av. J.-C.","Sargon, vers 1750 av. J.-C.","Sargon, vers 2300 av. J.-C."]'::jsonb, 3, 'Sargon fonde l’empire d’Akkad vers 2300 av. J.-C. ; Hammurabi règne à Babylone vers 1750.', 1),
    ('e5de580a-03d5-505d-8ff0-327269b8362b'::uuid, 'histoire-geo', '6e', 'Une diversité d’États dans le Croissant fertile', 'Dans quelle ville Hammurabi fait-il graver son code ?', 'mcq', '["Ur","Babylone","Uruk","Mari"]'::jsonb, 1, 'Hammurabi est roi de Babylone : sa stèle porte près de 300 articles de loi.', 2),
    ('2e3db24e-0819-551e-962d-67835a48cc5a'::uuid, 'histoire-geo', '6e', 'Une diversité d’États dans le Croissant fertile', 'Que va-t-on chercher en Anatolie pour le commerce ?', 'mcq', '["Du bois","Des perles","Des métaux","Du blé"]'::jsonb, 2, 'Le bois vient du Liban, les métaux d’Anatolie : le commerce circule loin.', 3),
    ('6e88fcbe-f80c-5279-9fe6-2a4cb97abb7b'::uuid, 'histoire-geo', '6e', 'Une diversité d’États dans le Croissant fertile', 'Que subsiste-t-il de ces empires éphémères ?', 'mcq', '["Leurs inventions : écriture, droit, administration","Leurs frontières","Leurs rois","Leurs armées"]'::jsonb, 0, 'Aucun empire ne dure, mais l’écriture, le droit et l’administration se transmettent.', 4),
    ('91227a25-6b74-50e2-94e6-bf7df158f666'::uuid, 'histoire-geo', '6e', 'Les premières écritures', 'Avec quel outil écrit-on sur l’argile fraîche ?', 'mcq', '["Un burin","Un stylet en os","Un calame","Un pinceau"]'::jsonb, 2, 'Le calame imprime dans l’argile des signes en forme de coins : le cunéiforme.', 1),
    ('d0a9e12d-8126-5b99-8f99-7a4949232319'::uuid, 'histoire-geo', '6e', 'Les premières écritures', 'Quel peuple ajoute les voyelles à l’alphabet phénicien ?', 'mcq', '["Les Phéniciens","Les Égyptiens","Les Romains","Les Grecs"]'::jsonb, 3, 'Les Phéniciens notent les consonnes ; les Grecs y ajoutent les voyelles.', 2),
    ('406e0e46-2a07-54dd-a1f3-6c5b09bf6420'::uuid, 'histoire-geo', '6e', 'Les premières écritures', 'Quelle pierre a permis à Champollion de déchiffrer les hiéroglyphes ?', 'mcq', '["La pierre de Hammurabi","La pierre de Rosette","La pierre de Carnac","La pierre de Lascaux"]'::jsonb, 1, 'La pierre de Rosette portait le même texte en plusieurs écritures : Champollion la déchiffre en 1822.', 3),
    ('e014399e-7e22-52ad-a004-4e54d4fee605'::uuid, 'histoire-geo', '6e', 'Les premières écritures', 'Que note l’alphabet phénicien ?', 'mcq', '["Les consonnes","Les voyelles","Des mots entiers","Des idées"]'::jsonb, 0, 'L’alphabet phénicien, d’une vingtaine de signes, ne note que les consonnes.', 4),
    ('8cd44eac-61cb-50c2-ba07-24b4b1b4d766'::uuid, 'histoire-geo', '6e', 'L’inégale répartition de la population mondiale', 'Quelle part de la planète les terres émergées couvrent-elles ?', 'mcq', '["10 %","30 %","50 %","70 %"]'::jsonb, 1, 'Les terres émergées couvrent environ 30 % de la planète, et l’écoumène n’en est qu’une fraction.', 1),
    ('151342cf-c88b-5eb2-b9cd-d69982fad5ff'::uuid, 'histoire-geo', '6e', 'L’inégale répartition de la population mondiale', 'Quelle part de l’humanité les trois grands foyers rassemblent-ils ?', 'mcq', '["Un dixième","Un quart","Un tiers","Plus de la moitié"]'::jsonb, 3, 'Asie du Sud, Asie de l’Est et Europe rassemblent plus de la moitié de l’humanité.', 2),
    ('68b2061f-1b70-52ff-ab3c-6fc59c2ed4a9'::uuid, 'histoire-geo', '6e', 'L’inégale répartition de la population mondiale', 'Depuis combien de temps la vallée du Nil est-elle peuplée ?', 'mcq', '["500 ans","1 000 ans","5 000 ans","50 000 ans"]'::jsonb, 2, 'Sa densité s’explique autant par cette longue histoire que par le fleuve.', 3),
    ('b7e3f2eb-1a71-506b-a5bc-be7c1c49ad99'::uuid, 'histoire-geo', '6e', 'L’inégale répartition de la population mondiale', 'Lequel de ces espaces est un désert humain froid ?', 'mcq', '["Le Sahara","Le Groenland","L’Amazonie","Java"]'::jsonb, 1, 'Sibérie, Groenland et Antarctique sont des déserts froids ; le Sahara est chaud, l’Amazonie est une forêt dense.', 4),
    ('26472954-39f1-5f58-8bf4-dd91b211d8d7'::uuid, 'histoire-geo', '6e', 'Les dynamiques de la population mondiale', 'Combien d’humains compte la Terre en 1950 ?', 'mcq', '["1 milliard","5 milliards","2,5 milliards","4 milliards"]'::jsonb, 2, 'On passe de 1 milliard vers 1800 à 2,5 milliards en 1950, puis 8 milliards aujourd’hui.', 1),
    ('1eb7defd-475e-53e5-96bb-f8a3a7b4f4ae'::uuid, 'histoire-geo', '6e', 'Les dynamiques de la population mondiale', 'Que se passe-t-il pendant la phase de transition démographique ?', 'mcq', '["La mortalité chute alors que la natalité reste forte","La natalité chute alors que la mortalité reste forte","Natalité et mortalité restent stables","Natalité et mortalité augmentent"]'::jsonb, 0, 'La mortalité baisse avant la natalité : c’est ce décalage qui fait exploser la population.', 2),
    ('a51344a9-9280-5114-9562-2b003161c605'::uuid, 'histoire-geo', '6e', 'Les dynamiques de la population mondiale', 'Quel enjeu se pose aux pays dont la population vieillit ?', 'mcq', '["La scolarisation de masse","La construction de bidonvilles","L’exode vers les villes","Le financement des retraites et de la santé"]'::jsonb, 3, 'Retraites, santé et main-d’œuvre sont les enjeux de l’Europe, du Japon et de plus en plus de la Chine.', 3),
    ('f6914166-d474-5cc9-9efc-00a72a11e56d'::uuid, 'histoire-geo', '6e', 'Les dynamiques de la population mondiale', 'Pour combien d’habitants compte-t-on les taux de natalité et de mortalité ?', 'mcq', '["100","1 000","10 000","1 million"]'::jsonb, 1, 'Ces taux s’expriment pour 1 000 habitants.', 4),
    ('0eec1bca-f7eb-51ce-bb39-9be8d2b7fe6f'::uuid, 'histoire-geo', '6e', 'Les différentes formes d’occupation spatiale dans le monde', 'Où trouve-t-on un habitat dispersé en France ?', 'mcq', '["Dans les Alpes","Dans la Beauce","À La Défense","Dans le bocage de l’Ouest"]'::jsonb, 3, 'Le bocage de l’Ouest français est parsemé de fermes isolées.', 1),
    ('faad23c8-c04d-511c-84b4-6cd6dae602b1'::uuid, 'histoire-geo', '6e', 'Les différentes formes d’occupation spatiale dans le monde', 'Que désigne le mot « déprise » ?', 'mcq', '["La ville qui s’étale sur les campagnes","La concentration des fonctions rares","Des espaces qui se vident, où les friches gagnent","La construction de routes"]'::jsonb, 2, 'La déprise touche les espaces qui perdent des habitants et des activités.', 2),
    ('439e5501-4ab9-5d51-9db3-db7f52931188'::uuid, 'histoire-geo', '6e', 'Les différentes formes d’occupation spatiale dans le monde', 'Comment s’expliquent les formes d’habitat ?', 'mcq', '["Par le hasard","Par l’histoire, l’agriculture pratiquée et le relief","Par la religion","Par le climat seul"]'::jsonb, 1, 'Habitat groupé, dispersé ou linéaire : il dépend de l’histoire, de l’agriculture et du relief.', 3),
    ('75b93a3a-be8d-5845-b85b-e1b9a40824cb'::uuid, 'histoire-geo', '6e', 'Les différentes formes d’occupation spatiale dans le monde', 'Que la ville doit-elle aux campagnes ?', 'mcq', '["Sa nourriture","Ses hôpitaux","Ses universités","Ses aéroports"]'::jsonb, 0, 'La ville dépend des campagnes pour se nourrir ; les campagnes dépendent d’elle pour les services.', 4),
    ('b5d3da2c-8c1e-54b4-8e71-571d493892eb'::uuid, 'histoire-geo', '6e', 'Le monde des cités grecques', 'Que désigne l’acropole ?', 'mcq', '["Le port","La place publique","La ville haute, où se trouvent les temples","Le tribunal"]'::jsonb, 2, 'L’acropole est la « ville haute » ; l’agora est la place publique où l’on débat.', 1),
    ('f489a9ca-3d1a-5c8f-b534-22d9359ab480'::uuid, 'histoire-geo', '6e', 'Le monde des cités grecques', 'Quel sanctuaire est commun à toutes les cités grecques ?', 'mcq', '["Athènes","Sparte","Marseille","Delphes"]'::jsonb, 3, 'Delphes, comme les Jeux olympiques, unit les Grecs malgré leurs rivalités.', 2),
    ('7a0f7614-13a9-5a14-9fc6-6352305deae1'::uuid, 'histoire-geo', '6e', 'Le monde des cités grecques', 'Qui les Grecs appellent-ils « Barbares » ?', 'mcq', '["Les esclaves","Ceux qui ne parlent pas grec","Les seuls Romains","Les citoyens pauvres"]'::jsonb, 1, 'Les Hellènes nomment Barbares ceux qui ne parlent pas leur langue.', 3),
    ('90d0899f-8ed1-5231-9da2-15423cfd2d64'::uuid, 'histoire-geo', '6e', 'Le monde des cités grecques', 'Quels liens une colonie garde-t-elle avec sa cité mère ?', 'mcq', '["Aucun lien","Des liens militaires uniquement","Elle reste gouvernée par la cité mère","Des liens religieux et commerciaux"]'::jsonb, 3, 'La colonie est indépendante, mais garde avec sa cité mère des liens religieux et commerciaux.', 4),
    ('ff052c3e-3539-587e-bee3-a1369ca4c98c'::uuid, 'histoire-geo', '6e', 'La religion des Grecs', 'Quel dieu grec règne sur la mer ?', 'mcq', '["Arès","Poséidon","Hermès","Héphaïstos"]'::jsonb, 1, 'Poséidon est le dieu de la mer ; Arès est celui de la guerre, Hermès le messager.', 1),
    ('be7a7152-dc81-5abb-99e1-f62d2ce3afc2'::uuid, 'histoire-geo', '6e', 'La religion des Grecs', 'Quel dieu est le messager des dieux ?', 'mcq', '["Apollon","Déméter","Hermès","Dionysos"]'::jsonb, 2, 'Hermès est le messager ; Apollon est le dieu des arts et de la lumière.', 2),
    ('cff2d0ac-8d16-567c-9043-a951a54a55cf'::uuid, 'histoire-geo', '6e', 'La religion des Grecs', 'Quel monument de l’acropole d’Athènes est le modèle du temple grec ?', 'mcq', '["Le Parthénon","Le Panthéon","Le Colisée","Le pont du Gard"]'::jsonb, 0, 'Le Parthénon abrite la statue d’Athéna, protectrice de la cité.', 3),
    ('1d73c3bc-7f2d-5e1f-a461-d487493459b5'::uuid, 'histoire-geo', '6e', 'La religion des Grecs', 'Qu’est-ce qui distingue les dieux grecs des mortels ?', 'mcq', '["Leur vertu","Leur sagesse","Leur invisibilité","Leur immortalité et leur puissance"]'::jsonb, 3, 'Ils sont immortels et puissants, mais pas vertueux : un dieu grec peut être injuste.', 4),
    ('a2900184-1a83-5a3e-b244-f01c402b7185'::uuid, 'histoire-geo', '6e', 'La naissance de la démocratie athénienne', 'Qui supprime l’esclavage pour dettes vers 594 av. J.-C. ?', 'mcq', '["Clisthène","Solon","Périclès","Homère"]'::jsonb, 1, 'Solon supprime l’esclavage pour dettes ; Clisthène réorganise la cité en 508.', 1),
    ('90eed358-9c42-5450-bae0-f4c7534f61cb'::uuid, 'histoire-geo', '6e', 'La naissance de la démocratie athénienne', 'Qu’est-ce que le misthos ?', 'mcq', '["Un impôt","Une amende","Un tribunal","Une indemnité qui permet aux plus pauvres de siéger"]'::jsonb, 3, 'Créé par Périclès, le misthos permet aux citoyens pauvres de participer sans perdre leur salaire.', 2),
    ('427c40ee-8952-5ace-a465-fa5ad13ef07e'::uuid, 'histoire-geo', '6e', 'La naissance de la démocratie athénienne', 'Où se réunit l’Ecclésia ?', 'mcq', '["À l’agora","Sur l’acropole","Sur la Pnyx","Au Parthénon"]'::jsonb, 2, 'L’assemblée des citoyens se réunit environ quarante fois par an sur la colline de la Pnyx.', 3),
    ('266141b0-6c63-5dbe-b431-de7ecd756675'::uuid, 'histoire-geo', '6e', 'La naissance de la démocratie athénienne', 'Sur quoi écrit-on le nom d’un citoyen à bannir par ostracisme ?', 'mcq', '["Un tesson de poterie","Un papyrus","Une tablette d’argile","Une stèle de pierre"]'::jsonb, 0, 'Le tesson, ostrakon en grec, a donné le mot ostracisme.', 4),
    ('fc6f48c4-2cd0-5454-bae1-d74a29a423a3'::uuid, 'histoire-geo', '6e', 'L’organisation de la société athénienne', 'Où les esclaves travaillent-ils dans des conditions terribles, à Athènes ?', 'mcq', '["À Marathon","Dans les mines d’argent du Laurion","À Delphes","À Olympie"]'::jsonb, 1, 'Dans les mines du Laurion, on ne revenait guère.', 1),
    ('c752aa3b-03a0-50eb-8b67-2434372994f6'::uuid, 'histoire-geo', '6e', 'L’organisation de la société athénienne', 'Que Périclès exige-t-il en 451 av. J.-C. pour être citoyen ?', 'mcq', '["Une grande fortune","Un service militaire","Un impôt","Une mère fille de citoyen"]'::jsonb, 3, 'Il faut désormais être né d’un père citoyen et d’une mère fille de citoyen.', 2),
    ('d4be8740-6b03-5c79-8e4b-e1d941ad38e4'::uuid, 'histoire-geo', '6e', 'L’organisation de la société athénienne', 'À quel âge un jeune Athénien est-il inscrit dans son dème ?', 'mcq', '["12 ans","16 ans","18 ans","21 ans"]'::jsonb, 2, 'À 18 ans il s’inscrit, puis fait l’éphébie et prête le serment de défendre la cité.', 3),
    ('5f3a5225-5008-5e98-88c7-c97bbf940165'::uuid, 'histoire-geo', '6e', 'L’organisation de la société athénienne', 'Quel est le statut juridique d’un esclave à Athènes ?', 'mcq', '["Un citoyen sans droits","Un bien","Un métèque","Un étranger libre"]'::jsonb, 1, 'Les esclaves, près de la moitié de la population, sont juridiquement des biens.', 4),
    ('6fbeb4fa-b1d0-5345-bc05-45b59202ff92'::uuid, 'histoire-geo', '6e', 'Les origines de Rome, du mythe à l’histoire', 'De quel dieu Romulus et Rémus sont-ils les fils selon la légende ?', 'mcq', '["Jupiter","Apollon","Mars","Zeus"]'::jsonb, 2, 'Les jumeaux sont fils de Mars, dieu de la guerre.', 1),
    ('6e0aeca6-15ad-56fe-9150-368985dbef94'::uuid, 'histoire-geo', '6e', 'Les origines de Rome, du mythe à l’histoire', 'Qui est l’auteur de l’Énéide ?', 'mcq', '["Tite-Live","Homère","Tacite","Virgile"]'::jsonb, 3, 'Virgile écrit l’Énéide au Ier siècle av. J.-C. pour donner à Rome un ancêtre troyen, Énée.', 2),
    ('2f561e60-bb09-54d3-8b0d-ce4239ffbaa3'::uuid, 'histoire-geo', '6e', 'Les origines de Rome, du mythe à l’histoire', 'Combien de rois la tradition compte-t-elle à Rome ?', 'mcq', '["Trois","Sept","Douze","Dix"]'::jsonb, 1, 'La tradition compte sept rois entre 753 et 509 av. J.-C.', 3),
    ('4bad55f4-a2ab-53f2-a263-2ced852ae577'::uuid, 'histoire-geo', '6e', 'Les origines de Rome, du mythe à l’histoire', 'Que devient Rémus dans la légende ?', 'mcq', '["Il devient le premier consul","Il fonde Carthage","Romulus le tue après une dispute","Il retourne à Troie"]'::jsonb, 2, 'Après une dispute sur la fondation, Romulus tue Rémus et devient seul maître de la ville.', 4),
    ('186807ae-88fb-5c9a-a6fc-f891f8fc6213'::uuid, 'histoire-geo', '6e', 'La fondation de Rome selon l’archéologie', 'Que désigne la dendrochronologie ?', 'mcq', '["La datation par les monnaies","La datation par les cernes des arbres","La datation par les couches du sol","L’étude des poteries"]'::jsonb, 1, 'Les cernes des arbres donnent une datation absolue, comme le carbone 14 et les monnaies.', 1),
    ('f396688b-ad00-5471-aa15-dc0a960d37c9'::uuid, 'histoire-geo', '6e', 'La fondation de Rome selon l’archéologie', 'Que devient le Forum au fil du temps ?', 'mcq', '["Un port fluvial","Un camp militaire","Une forêt sacrée","Un marécage devenu espace public"]'::jsonb, 3, 'Une nécropole puis un dallage : le marécage devient l’espace public de la ville.', 2),
    ('9e70a0d3-ffeb-5a94-9c00-e246e5223043'::uuid, 'histoire-geo', '6e', 'La fondation de Rome selon l’archéologie', 'Laquelle de ces méthodes est une datation relative ?', 'mcq', '["Le carbone 14","Les monnaies","La comparaison des styles de poterie","La dendrochronologie"]'::jsonb, 2, 'Comparer les styles de poterie ou lire les couches donne un avant et un après, pas une date précise.', 3),
    ('83533162-ad8c-580d-855c-e63d2e30a307'::uuid, 'histoire-geo', '6e', 'La fondation de Rome selon l’archéologie', 'Que fournissent surtout les fouilles, par rapport aux textes ?', 'mcq', '["Des noms et des intentions","Des récits de fondation","Des discours","Des dates, des objets et des réalités matérielles"]'::jsonb, 3, 'Les textes donnent noms, intentions et récits ; les fouilles donnent des dates et des objets.', 4),
    ('2038b4e6-a1d2-5495-87c2-20277ed6dcc5'::uuid, 'histoire-geo', '6e', 'Citoyenneté et République romaine', 'Que signifie res publica ?', 'mcq', '["Le roi de la ville","Le pouvoir des riches","La chose publique","Le sénat et le peuple"]'::jsonb, 2, 'Res publica, « la chose publique » : le pouvoir n’appartient plus à un homme, mais à la communauté.', 1),
    ('008af7e2-3358-57f3-aabc-39a13950d502'::uuid, 'histoire-geo', '6e', 'Citoyenneté et République romaine', 'Qui sont les patriciens ?', 'mcq', '["Les esclaves affranchis","Les tribuns de la plèbe","Les étrangers installés à Rome","Les grandes familles"]'::jsonb, 3, 'Les patriciens, grandes familles, sont longtemps seuls à accéder aux magistratures.', 2),
    ('58ebcb04-7a18-5564-918b-4c8b0f7af8e0'::uuid, 'histoire-geo', '6e', 'Citoyenneté et République romaine', 'Pourquoi les magistrats sont-ils élus par deux au moins et pour un an ?', 'mcq', '["Pour partager les frais","Pour empêcher la confiscation du pouvoir","Pour gagner du temps","Par tradition religieuse"]'::jsonb, 1, 'Brièveté et collégialité empêchent qu’un seul homme garde le pouvoir.', 3),
    ('ef9f2cc3-1b36-5ed3-b0f4-39fadec97417'::uuid, 'histoire-geo', '6e', 'Citoyenneté et République romaine', 'Que signifie « veto » ?', 'mcq', '["Je m’oppose","Je vote","Je commande","J’obéis"]'::jsonb, 0, 'Les tribuns de la plèbe peuvent dire « je m’oppose » aux décisions des magistrats.', 4),
    ('61389ac1-8a42-5b7b-8de4-e44c40f28a82'::uuid, 'histoire-geo', '6e', 'La Bible, récits et bases du judaïsme', 'Comment les chrétiens appellent-ils la Bible hébraïque ?', 'mcq', '["Nouveau Testament","Évangile","Coran","Ancien Testament"]'::jsonb, 3, 'Les chrétiens y ajoutent le Nouveau Testament, qui rassemble les Évangiles et d’autres textes.', 1),
    ('35e5c494-cec1-59e3-8ea5-05f75878a828'::uuid, 'histoire-geo', '6e', 'La Bible, récits et bases du judaïsme', 'Pourquoi juifs, chrétiens et musulmans sont-ils dits « abrahamiques » ?', 'mcq', '["Ils ont le même livre","Ils se rattachent tous à Abraham","Ils sont nés à Jérusalem le même siècle","Abraham a fondé les trois religions"]'::jsonb, 1, 'Les trois religions partagent Abraham, figure de l’Alliance.', 2),
    ('3ae05152-619a-5e3f-8a2e-a7192df4fba2'::uuid, 'histoire-geo', '6e', 'La Bible, récits et bases du judaïsme', 'Quand beaucoup de textes bibliques sont-ils mis par écrit ?', 'mcq', '["Au Sinaï","Sous Auguste","Pendant l’exil à Babylone","Avant Abraham"]'::jsonb, 2, 'C’est en exil, après 587 av. J.-C., que beaucoup de textes sont écrits.', 3),
    ('9cfade0c-9f1d-5345-b0ea-5ddbde455794'::uuid, 'histoire-geo', '6e', 'La Bible, récits et bases du judaïsme', 'Que confirme l’archéologie dans les récits bibliques ?', 'mcq', '["L’Exode tel qu’il est raconté","Le Déluge","La traversée de la mer Rouge","L’existence du royaume de Juda"]'::jsonb, 3, 'L’archéologie atteste le royaume de Juda et les destructions de Jérusalem, mais pas l’Exode tel qu’il est raconté.', 4),
    ('3f7c2965-3365-56b9-a60d-0f2362deb650'::uuid, 'histoire-geo', '6e', 'La naissance du judaïsme', 'Que célèbre Yom Kippour ?', 'mcq', '["La sortie d’Égypte","Le repos du septième jour","Le Grand Pardon","Le signe de l’Alliance"]'::jsonb, 2, 'Yom Kippour est le Grand Pardon ; Pessah célèbre la sortie d’Égypte.', 1),
    ('56a577fd-b686-5374-b6f5-d971125d874f'::uuid, 'histoire-geo', '6e', 'La naissance du judaïsme', 'Quel est le signe de l’Alliance dans le judaïsme ?', 'mcq', '["Le baptême","La circoncision","Le shabbat","Le sacrifice"]'::jsonb, 1, 'La circoncision est le signe de l’Alliance ; le baptême, lui, remplace la circoncision chez les chrétiens.', 2),
    ('d929addc-5d16-5c88-aeb5-cd987c425730'::uuid, 'histoire-geo', '6e', 'La naissance du judaïsme', 'Que subsiste-t-il du Temple de Jérusalem ?', 'mcq', '["Le Parthénon","Une ziggurat","Le Forum","Le Mur occidental"]'::jsonb, 3, 'Il n’en reste que le Mur occidental.', 3),
    ('5bd49437-6668-5003-92bd-5e3c26b42c6d'::uuid, 'histoire-geo', '6e', 'La naissance du judaïsme', 'Quelle est la capitale du royaume de Juda ?', 'mcq', '["Babylone","Alexandrie","Jérusalem","Rome"]'::jsonb, 2, 'Le royaume de Juda, au sud, a pour capitale Jérusalem ; Israël est au nord.', 4),
    ('9aa20669-a866-56e4-8d7f-e583334a9d57'::uuid, 'maths', '6e', 'Géométrie : éléments de base, propriétés des droites parallèles et perpendiculaires, médiatrices et bissectrices', 'Que désigne la notation AB, écrite sans crochets ni parenthèses ?', 'mcq', '["La droite passant par A et B","La demi-droite d’origine A","Le milieu du segment [AB]","La longueur du segment [AB]"]'::jsonb, 3, 'Crochets pour le segment, parenthèses pour la droite ; AB seul est la longueur, un nombre.', 1),
    ('6b45606c-5630-5c10-917b-0123ed66b553'::uuid, 'maths', '6e', 'Géométrie : éléments de base, propriétés des droites parallèles et perpendiculaires, médiatrices et bissectrices', 'Les droites (d1) et (d2) sont parallèles, et (d3) est perpendiculaire à (d1). Que peut-on dire de (d3) et (d2) ?', 'mcq', '["Elle est perpendiculaire à (d2)","Elle est parallèle à (d2)","Elle est confondue avec (d2)","On ne peut rien conclure"]'::jsonb, 0, 'Une perpendiculaire à l’une de deux parallèles est perpendiculaire à l’autre : c’est une propriété qui se démontre.', 2),
    ('d678312c-1308-5629-9823-1317569d00ed'::uuid, 'maths', '6e', 'Géométrie : éléments de base, propriétés des droites parallèles et perpendiculaires, médiatrices et bissectrices', 'Le point M est sur la médiatrice du segment [AB]. Que sait-on avec certitude ?', 'mcq', '["M est le milieu de [AB]","MA = MB","MA = AB","(MA) est perpendiculaire à (MB)"]'::jsonb, 1, 'Les points de la médiatrice sont à égale distance des deux extrémités ; M n’est le milieu que s’il est aussi sur le segment.', 3),
    ('18a4c046-e2f0-570e-919b-6dce10f1cfa9'::uuid, 'maths', '6e', 'Géométrie : éléments de base, propriétés des droites parallèles et perpendiculaires, médiatrices et bissectrices', 'Quel instrument sert à reporter une longueur sans la mesurer ?', 'mcq', '["La règle graduée","Le rapporteur","Le compas","L’équerre"]'::jsonb, 2, 'Le compas reporte une longueur d’un endroit à un autre et trace les cercles ; c’est aussi lui qui construit une médiatrice.', 4),
    ('458eda6f-4883-5ddf-bde8-3eac3ab269df'::uuid, 'maths', '6e', 'Travailler avec les angles', 'Comment appelle-t-on un angle qui mesure exactement 180° ?', 'mcq', '["Un angle droit","Un angle obtus","Un angle plat","Un angle aigu"]'::jsonb, 2, 'Un angle plat mesure 180° : ses deux côtés sont dans le prolongement l’un de l’autre.', 1),
    ('3b00b68f-dcd3-5d44-9efa-c31e26675587'::uuid, 'maths', '6e', 'Travailler avec les angles', 'Quel est le complémentaire d’un angle de 35° ?', 'mcq', '["145°","55°","65°","125°"]'::jsonb, 1, 'Deux angles complémentaires font 90° ensemble : 90 − 35 = 55. Le 145° est le supplémentaire (180 − 35).', 2),
    ('fb403f2f-a22e-5d9d-ba2b-89d4be48d18e'::uuid, 'maths', '6e', 'Travailler avec les angles', 'Quel est le supplémentaire d’un angle de 110° ?', 'mcq', '["80°","250°","20°","70°"]'::jsonb, 3, 'Deux angles supplémentaires font 180° ensemble : 180 − 110 = 70°.', 3),
    ('10cf598d-322b-5f53-9d5c-0a9bcafe6719'::uuid, 'maths', '6e', 'Travailler avec les angles', 'Tu mesures un angle visiblement aigu et tu lis 130° sur une graduation. Que fais-tu ?', 'mcq', '["Je lis l’autre graduation : 50°","Je garde 130°, c’est la mesure","Je retranche 90° à 130°","J’ajoute 50° à 130°"]'::jsonb, 0, 'Le rapporteur a deux graduations complémentaires à 180° (130 + 50). Un angle aigu mesure moins de 90°, donc c’est 50°.', 4),
    ('19cbb59c-f29b-5cf0-82ae-d6c66cb0e4d3'::uuid, 'maths', '6e', 'Construire des triangles et utiliser la somme des angles d’un triangle', 'Un triangle a deux angles de 100° et 30°. Combien mesure le troisième ?', 'mcq', '["50°","60°","80°","130°"]'::jsonb, 0, 'La somme vaut 180° : 180 − 100 − 30 = 50°.', 1),
    ('d6067a8c-915b-53f5-b538-60f7ecf92d3f'::uuid, 'maths', '6e', 'Construire des triangles et utiliser la somme des angles d’un triangle', 'Peut-on construire un triangle dont les côtés mesurent 5 cm, 6 cm et 10 cm ?', 'mcq', '["Non, car 5 + 6 = 11 est différent de 10","Non, car 10 est le plus grand côté","Oui, car 10 < 5 + 6 = 11","Oui, car les trois côtés sont différents"]'::jsonb, 2, 'Le plus grand côté (10) est plus petit que la somme des deux autres (11) : le triangle existe. On vérifie toujours avant de construire.', 2),
    ('f0f75f00-899e-54da-b662-3e127265ce6e'::uuid, 'maths', '6e', 'Construire des triangles et utiliser la somme des angles d’un triangle', 'Pour construire un triangle dont on connaît deux côtés et l’angle compris entre eux, on utilise…', 'mcq', '["la règle et le compas seulement","la règle et le rapporteur","l’équerre et le compas","le rapporteur seul"]'::jsonb, 1, 'On trace un côté, on reporte l’angle au rapporteur, puis on trace le second côté à la règle.', 3),
    ('3fe0594e-7eff-5281-a018-987547f137d4'::uuid, 'maths', '6e', 'Construire des triangles et utiliser la somme des angles d’un triangle', 'Un triangle rectangle a un angle aigu de 37°. Combien mesure l’autre angle aigu ?', 'mcq', '["143°","63°","37°","53°"]'::jsonb, 3, 'Les deux angles aigus d’un triangle rectangle sont complémentaires : 90 − 37 = 53°.', 4),
    ('4a86e638-952f-5bb1-9ce4-e3009227f5a9'::uuid, 'maths', '6e', 'Connaître les triangles isocèles, équilatéraux et rectangles', 'Un triangle isocèle a des angles à la base de 50°. Combien mesure l’angle au sommet principal ?', 'mcq', '["50°","100°","80°","130°"]'::jsonb, 2, 'Les angles à la base sont égaux : 50 + 50 = 100, et 180 − 100 = 80°.', 1),
    ('cc82ae03-4bc9-528a-908a-f399c6dbc8b9'::uuid, 'maths', '6e', 'Connaître les triangles isocèles, équilatéraux et rectangles', 'Dans un triangle rectangle, l’hypoténuse est…', 'mcq', '["toujours le côté le plus court","toujours le côté le plus long","l’un des côtés de l’angle droit","un côté de longueur moyenne"]'::jsonb, 1, 'L’hypoténuse, opposée à l’angle droit, est toujours le plus long côté du triangle rectangle.', 2),
    ('2367a6be-2021-58f1-9c82-3dab888b3045'::uuid, 'maths', '6e', 'Connaître les triangles isocèles, équilatéraux et rectangles', 'Un triangle équilatéral est…', 'mcq', '["un triangle jamais isocèle","un triangle forcément rectangle","isocèle seulement s’il est petit","un cas particulier de triangle isocèle"]'::jsonb, 3, 'Ayant trois côtés égaux, il en a au moins deux : tout équilatéral est isocèle, mais l’inverse est faux.', 3),
    ('0a231915-7ff1-5552-b2b6-85cda71a7750'::uuid, 'maths', '6e', 'Connaître les triangles isocèles, équilatéraux et rectangles', 'Sur une figure, deux côtés portent le même petit trait. Que sait-on ?', 'mcq', '["Ils ont la même longueur","Ils sont perpendiculaires","Ils sont parallèles","Ils mesurent chacun 1 cm"]'::jsonb, 0, 'Des traits identiques codent des longueurs égales. On se fie au codage, pas à la règle graduée.', 4),
    ('3454a4fb-0f60-5e7d-8de7-f8bcc84e4b4c'::uuid, 'maths', '6e', 'Connaître la symétrie axiale', 'Le point A est à 3 cm de l’axe (d). Quelle est la distance AA’ entre A et son symétrique A’ ?', 'mcq', '["3 cm","6 cm","9 cm","1,5 cm"]'::jsonb, 1, 'L’axe est la médiatrice de [AA’] : A’ est à 3 cm de l’autre côté, donc AA’ = 3 + 3 = 6 cm.', 1),
    ('5d4a595d-e0e8-5886-a85d-dd963e39e28c'::uuid, 'maths', '6e', 'Connaître la symétrie axiale', 'Combien d’axes de symétrie a un rectangle qui n’est pas un carré ?', 'mcq', '["4","1","2","Aucun"]'::jsonb, 2, 'Un rectangle a deux axes : les médiatrices de ses côtés. Ses diagonales n’en sont pas.', 2),
    ('522ed52e-368c-5c18-b9b6-be89625e73a3'::uuid, 'maths', '6e', 'Connaître la symétrie axiale', 'Un triangle isocèle qui n’est pas équilatéral a…', 'mcq', '["un seul axe de symétrie","deux axes de symétrie","trois axes de symétrie","aucun axe de symétrie"]'::jsonb, 0, 'Son axe est la médiatrice de la base. Seul le triangle équilatéral en possède trois.', 3),
    ('f3bf26d2-9ee0-5107-a3f1-60dbacdd46ce'::uuid, 'maths', '6e', 'Connaître la symétrie axiale', 'Les points A’ et B’ sont les symétriques de A et B, et AB = 5 cm. Combien mesure A’B’ ?', 'mcq', '["10 cm","2,5 cm","0 cm","5 cm"]'::jsonb, 3, 'La symétrie axiale conserve les longueurs : A’B’ = AB = 5 cm.', 4),
    ('7220e3c9-dbac-51ad-a7b5-acfb663f7350'::uuid, 'maths', '6e', 'Voir dans l’espace et calculer des volumes', 'Quel est le volume d’un cube de 4 cm de côté ?', 'mcq', '["16 cm³","64 cm³","12 cm³","48 cm³"]'::jsonb, 1, 'V = c × c × c = 4 × 4 × 4 = 64 cm³. Le 16 est l’aire d’une face.', 1),
    ('332f4812-f728-5de8-b4d6-ce84dbcd50d9'::uuid, 'maths', '6e', 'Voir dans l’espace et calculer des volumes', 'Quel est le volume d’un pavé droit de 5 cm sur 4 cm sur 3 cm ?', 'mcq', '["12 cm³","94 cm³","60 cm³","20 cm³"]'::jsonb, 2, 'V = L × l × h = 5 × 4 × 3 = 60 cm³.', 2),
    ('914f63a4-d45f-554e-a360-427797d8999f'::uuid, 'maths', '6e', 'Voir dans l’espace et calculer des volumes', 'Une bouteille contient 1,5 L. Quel est son volume en cm³ ?', 'mcq', '["150 cm³","15 cm³","15 000 cm³","1 500 cm³"]'::jsonb, 3, '1 L = 1 dm³ = 1 000 cm³, donc 1,5 L = 1 500 cm³.', 3),
    ('6e7caae2-73cc-5305-965a-07e65ee70d60'::uuid, 'maths', '6e', 'Voir dans l’espace et calculer des volumes', 'Combien de patrons différents un cube possède-t-il ?', 'mcq', '["11","6","12","8"]'::jsonb, 0, 'Le cube a onze patrons : six carrés ne suffisent pas, il faut qu’ils soient bien disposés pour se replier.', 4),
    ('e3d56a5a-193a-5dcf-9dab-68263d461968'::uuid, 'maths', '6e', 'Calculer des périmètres', 'Quel est le périmètre d’un rectangle de 12 cm de long et 8 cm de large ?', 'mcq', '["96 cm","20 cm","40 cm","32 cm"]'::jsonb, 2, 'P = 2 × (12 + 8) = 2 × 20 = 40 cm. Le 96 serait l’aire.', 1),
    ('65cd46da-41bb-5533-a7f5-3e43d02d32bf'::uuid, 'maths', '6e', 'Calculer des périmètres', 'Quel est le périmètre d’un cercle de rayon 5 cm (avec π ≈ 3,14) ?', 'mcq', '["31,4 cm","15,7 cm","78,5 cm","314 cm"]'::jsonb, 0, 'P = 2 × π × r = 2 × 3,14 × 5 = 31,4 cm. Le 78,5 serait l’aire du disque.', 2),
    ('505c3fac-2e5c-5b48-98b2-4a86f3ffa5c8'::uuid, 'maths', '6e', 'Calculer des périmètres', 'Un rectangle mesure 2 m sur 50 cm. Quel est son périmètre en centimètres ?', 'mcq', '["104 cm","500 cm","250 cm","5 cm"]'::jsonb, 1, 'On convertit d’abord : 2 m = 200 cm, puis P = 2 × (200 + 50) = 500 cm. Additionner 2 et 50 mélange les unités.', 3),
    ('0c6158dc-8c3d-5b02-a9bb-e5b901fccaa2'::uuid, 'maths', '6e', 'Calculer des périmètres', 'Pour le périmètre d’une figure composée, les segments intérieurs (traits de découpe)…', 'mcq', '["comptent une fois","comptent deux fois","comptent la moitié","ne comptent pas"]'::jsonb, 3, 'On n’additionne que les segments du contour : les traits intérieurs ne font pas partie du tour de la figure.', 4),
    ('31aca851-94c6-548d-8c5c-3f39f915396d'::uuid, 'maths', '6e', 'Calculer et convertir des aires', 'Quelle est l’aire d’un triangle de base 10 cm et de hauteur 6 cm ?', 'mcq', '["60 cm²","30 cm²","16 cm²","32 cm²"]'::jsonb, 1, 'A = (base × hauteur) ÷ 2 = (10 × 6) ÷ 2 = 30 cm². Oublier de diviser par 2 donne 60.', 1),
    ('19b50a24-0774-508a-a552-bbd5da9f3bb6'::uuid, 'maths', '6e', 'Calculer et convertir des aires', 'Quelle est l’aire d’un disque de rayon 3 cm (avec π ≈ 3,14) ?', 'mcq', '["28,26 cm²","18,84 cm²","56,52 cm²","9 cm²"]'::jsonb, 0, 'A = π × r × r = 3,14 × 3 × 3 = 28,26 cm². Le 18,84 est le périmètre du cercle (2 × π × r), à ne pas confondre.', 2),
    ('6fad5b9a-e666-5518-bdf7-fb8b526f7ad8'::uuid, 'maths', '6e', 'Calculer et convertir des aires', 'Combien de cm² dans 3 m² ?', 'mcq', '["300 cm²","3 000 cm²","30 000 cm²","300 000 cm²"]'::jsonb, 2, '1 m² = 10 000 cm², donc 3 m² = 30 000 cm².', 3),
    ('237c9c2a-fad3-5b0e-b183-0094d34e2cc2'::uuid, 'maths', '6e', 'Calculer et convertir des aires', 'Un terrain mesure 5 ares. Quelle est son aire en m² ?', 'mcq', '["50 m²","5 000 m²","50 000 m²","500 m²"]'::jsonb, 3, '1 are = 100 m², donc 5 ares = 500 m².', 4),
    ('bca062a4-6405-5d97-a758-212753095905'::uuid, 'maths', '6e', 'Calculer des horaires et des durées, convertir des durées', 'Que vaut 45 minutes exprimées en heures ?', 'mcq', '["0,45 h","0,75 h","4,5 h","0,6 h"]'::jsonb, 1, '45 ÷ 60 = 0,75 h. Le temps se compte en base 60 : 0,45 h ne fait pas 45 minutes.', 1),
    ('e46687bc-3015-527b-b0cc-ce3b0dc7510c'::uuid, 'maths', '6e', 'Calculer des horaires et des durées, convertir des durées', 'Combien de minutes font 3 h 20 min ?', 'mcq', '["320 min","180 min","200 min","230 min"]'::jsonb, 2, '3 h = 3 × 60 = 180 min, puis 180 + 20 = 200 min.', 2),
    ('e23cd094-0a5f-5f18-8c0c-bb23ea738ab4'::uuid, 'maths', '6e', 'Calculer des horaires et des durées, convertir des durées', 'Un train part à 9 h 40 et roule 2 h 35. À quelle heure arrive-t-il ?', 'mcq', '["12 h 15","11 h 75","12 h 05","12 h 75"]'::jsonb, 0, '9 h 40 + 2 h 35 = 11 h 75. Comme 75 min = 1 h 15, on obtient 12 h 15.', 3),
    ('7e7eba4a-8b38-5299-9b16-b4eea3287d31'::uuid, 'maths', '6e', 'Calculer des horaires et des durées, convertir des durées', 'Une voiture parcourt 120 km en 1 h 30 à vitesse constante. Quelle est sa vitesse ?', 'mcq', '["90 km/h","120 km/h","60 km/h","80 km/h"]'::jsonb, 3, '1 h 30 = 1,5 h, donc v = d ÷ t = 120 ÷ 1,5 = 80 km/h.', 4),
    ('4d9ba11f-f808-51a4-910d-e0da6bf5e09a'::uuid, 'maths', '6e', 'Initiation à la pensée informatique', 'Pour tracer un hexagone régulier avec une boucle, de quel angle tourne-t-on à chaque tour ?', 'mcq', '["90°","120°","60°","30°"]'::jsonb, 2, 'Pour un polygone à n côtés, on tourne de 360 ÷ n degrés : 360 ÷ 6 = 60°.', 1),
    ('df64b2a3-d95e-51f8-bb92-29d98d8b4efc'::uuid, 'maths', '6e', 'Initiation à la pensée informatique', 'Dans l’instruction « aller à (3 ; 5) », que représente le 3 ?', 'mcq', '["L’ordonnée","L’abscisse","Le nombre de pas","Le nombre de tours"]'::jsonb, 1, 'Dans un couple de coordonnées, l’abscisse (horizontale) vient toujours en premier : x = 3, puis l’ordonnée y = 5.', 2),
    ('a21f5f9e-af02-5daa-8a8e-6dab8406daf4'::uuid, 'maths', '6e', 'Initiation à la pensée informatique', 'Sans boucle, combien d’instructions faut-il écrire pour répéter 4 fois [avancer de 100 ; tourner de 90°] ?', 'mcq', '["4","6","12","8"]'::jsonb, 3, 'Chaque tour compte deux instructions et il y a 4 tours : 8 instructions. Avec une boucle, trois suffisent.', 3),
    ('26c8d725-c3d0-52c3-af32-7cae7850341f'::uuid, 'maths', '6e', 'Initiation à la pensée informatique', 'Dans « si le lutin touche le bord, alors rebondir », que représente « le lutin touche le bord » ?', 'mcq', '["La condition","L’instruction répétée","La variable","Le bug"]'::jsonb, 0, 'Dans une instruction « si … alors … », la partie testée est la condition : elle décide si l’action a lieu.', 4),
    ('34415fdc-bd8b-5d79-b88f-eeb46b56004f'::uuid, 'maths', '6e', 'Proportionnalité', '4 cahiers identiques coûtent 6 €. Combien coûtent 10 cahiers au même prix ?', 'mcq', '["10 €","24 €","15 €","60 €"]'::jsonb, 2, 'Un cahier coûte 6 ÷ 4 = 1,5 €, donc 10 cahiers coûtent 10 × 1,5 = 15 €.', 1),
    ('e936ba3c-e7f1-5f0e-b67b-63f1a3f3d9a3'::uuid, 'maths', '6e', 'Proportionnalité', 'Sur une carte à l’échelle 1/50 000, 4 cm représentent en réalité…', 'mcq', '["200 m","2 km","20 km","4 km"]'::jsonb, 1, '4 × 50 000 = 200 000 cm, soit 2 000 m, soit 2 km.', 2),
    ('6b8dc1a9-4813-59cb-8ff9-8a235f28a8f5'::uuid, 'maths', '6e', 'Proportionnalité', 'Dans le produit en croix 3/5 = x/20, que vaut x ?', 'mcq', '["60","15","8","12"]'::jsonb, 3, 'x = 3 × 20 ÷ 5 = 60 ÷ 5 = 12.', 3),
    ('266c1b28-8947-5be2-b5e6-c9a747270e78'::uuid, 'maths', '6e', 'Proportionnalité', 'Le tableau 2 → 7 ; 4 → 14 ; 6 → 20 est-il un tableau de proportionnalité ?', 'mcq', '["Non : 20 ÷ 6 ne donne pas 3,5","Oui : les nombres augmentent","Oui : 7 est impair","Non : il n’a que trois colonnes"]'::jsonb, 0, 'Les deux premières colonnes donnent 3,5, mais 20 ÷ 6 n’est pas égal à 3,5 : il faut que toutes les colonnes donnent le même quotient.', 4),
    ('1cb894db-973a-57e7-8ac7-2ebd2df5995c'::uuid, 'maths', '6e', 'Nombres entiers et décimaux : définition, repérage et comparaisons', 'Quel est le plus petit de ces nombres ?', 'mcq', '["3,09","3,1","3,012","3,2"]'::jsonb, 2, 'On compare les dixièmes : 3,012 et 3,09 ont 0 dixième, et 3,012 a 1 centième contre 9. 3,012 est le plus petit malgré ses trois décimales.', 1),
    ('0070cb1f-2c87-510e-a890-d1d32bf5eaf9'::uuid, 'maths', '6e', 'Nombres entiers et décimaux : définition, repérage et comparaisons', 'Dans 58,724, quel est le chiffre des centièmes ?', 'mcq', '["7","2","4","8"]'::jsonb, 1, 'Après la virgule : 7 dixièmes, 2 centièmes, 4 millièmes. Le 8 est le chiffre des unités.', 2),
    ('cc94f034-2c3f-58e5-b135-fda233ad9a2e'::uuid, 'maths', '6e', 'Nombres entiers et décimaux : définition, repérage et comparaisons', 'Que vaut 6,95 arrondi au dixième ?', 'mcq', '["6,9","6,0","7,1","7,0"]'::jsonb, 3, 'Le chiffre suivant est 5 : on arrondit au supérieur, ce qui donne 7,0 (soit 7).', 3),
    ('d47db48e-2ffa-52a6-ac30-35717ba33ff9'::uuid, 'maths', '6e', 'Nombres entiers et décimaux : définition, repérage et comparaisons', 'Quelle est l’écriture décomposée de 4,07 ?', 'mcq', '["4 + 7/100","4 + 7/10","4 + 7/1 000","47/100"]'::jsonb, 0, '4,07 c’est 4 unités, 0 dixième et 7 centièmes : 4 + 7/100. Le 47/100 vaut 0,47.', 4),
    ('181242bb-bc6e-5e68-bf38-e4540713e93a'::uuid, 'maths', '6e', 'Nombres décimaux : addition, soustraction et multiplication', 'Combien font 12,5 − 3,75 ?', 'mcq', '["9,25","8,75","8,25","9,75"]'::jsonb, 1, 'On aligne les virgules : 12,50 − 3,75 = 8,75.', 1),
    ('2836c07d-e247-510c-8f84-e9118525a3ad'::uuid, 'maths', '6e', 'Nombres décimaux : addition, soustraction et multiplication', 'Combien font 0,4 × 0,3 ?', 'mcq', '["1,2","0,7","0,12","0,012"]'::jsonb, 2, '4 × 3 = 12, et il y a 1 + 1 = 2 décimales : 0,12.', 2),
    ('73c78e36-353e-5716-adb2-870369662c08'::uuid, 'maths', '6e', 'Nombres décimaux : addition, soustraction et multiplication', 'Combien font 250 ÷ 1 000 ?', 'mcq', '["2,5","25","0,025","0,25"]'::jsonb, 3, 'Diviser par 1 000 déplace la virgule de trois rangs vers la gauche : 250 devient 0,25.', 3),
    ('1385495c-e2f6-5a1a-93c3-f984b121b780'::uuid, 'maths', '6e', 'Nombres décimaux : addition, soustraction et multiplication', 'Combien font 5 × (3 + 2) − 4 ?', 'mcq', '["21","13","5","41"]'::jsonb, 0, 'On commence par la parenthèse : 5 × 5 = 25, puis 25 − 4 = 21.', 4),
    ('fd2c5bd2-9fca-5852-83fd-868525302f24'::uuid, 'maths', '6e', 'Division euclidienne et divisibilité', 'Laquelle de ces écritures est la division euclidienne de 100 par 7 ?', 'mcq', '["100 = 7 × 13 + 9","100 = 7 × 14 + 2","100 = 7 × 15 − 5","100 = 7 × 12 + 16"]'::jsonb, 1, '7 × 14 = 98 et 100 − 98 = 2. Les autres écritures sont fausses ou ont un reste qui n’est pas plus petit que 7.', 1),
    ('f34256e8-cc23-529b-9e11-2d0b4d0b240b'::uuid, 'maths', '6e', 'Division euclidienne et divisibilité', 'Lequel de ces nombres est divisible par 4 ?', 'mcq', '["1 214","2 350","3 716","5 026"]'::jsonb, 2, 'On regarde les deux derniers chiffres : 16 est divisible par 4, alors que 14, 50 et 26 ne le sont pas.', 2),
    ('c00b7934-5993-5dcb-b382-5d55aa48b20f'::uuid, 'maths', '6e', 'Division euclidienne et divisibilité', 'Lequel de ces nombres est divisible à la fois par 2, par 5 et par 10 ?', 'mcq', '["370","375","372","365"]'::jsonb, 0, 'Un nombre qui se termine par 0 est divisible par 2, 5 et 10.', 3),
    ('b7f1cab3-c116-5c43-83cf-45bb4a9f29d3'::uuid, 'maths', '6e', 'Division euclidienne et divisibilité', 'Lequel de ces nombres est premier ?', 'mcq', '["21","27","39","29"]'::jsonb, 3, '21 = 3 × 7, 27 = 3 × 9 et 39 = 3 × 13 ont d’autres diviseurs. 29 n’a que 1 et lui-même.', 4),
    ('f0217deb-22dc-51a8-9dab-ccb564444f6a'::uuid, 'maths', '6e', 'Division décimale', 'Combien font 21 ÷ 4 ?', 'mcq', '["5,5","5,2","5,25","5,05"]'::jsonb, 2, '21 = 4 × 5 + 1 ; on abaisse un zéro : 10 ÷ 4 = 2 reste 2, puis 20 ÷ 4 = 5. Le quotient est 5,25.', 1),
    ('4caa98fe-2802-5790-855b-c39fd8d8a00d'::uuid, 'maths', '6e', 'Division décimale', 'Combien font 6,3 ÷ 0,9 ?', 'mcq', '["7","70","0,7","5,4"]'::jsonb, 0, 'On multiplie les deux nombres par 10 : 63 ÷ 9 = 7.', 2),
    ('8e993593-4d98-5cd4-bd92-c9c6c8d67939'::uuid, 'maths', '6e', 'Division décimale', 'Quelle est la valeur approchée par excès de 2 ÷ 3 au centième ?', 'mcq', '["0,66","0,67","0,7","0,65"]'::jsonb, 1, '2 ÷ 3 = 0,666… La valeur juste au-dessus au centième est 0,67 (par défaut, ce serait 0,66).', 3),
    ('f3358145-62b0-56c5-8d1a-f1d185e640ca'::uuid, 'maths', '6e', 'Division décimale', 'Combien font 0,7 ÷ 5 ?', 'mcq', '["1,4","0,014","0,35","0,14"]'::jsonb, 3, '7 ÷ 5 = 1,4, donc 0,7 ÷ 5 = 0,14. Vérification : 0,14 × 5 = 0,7.', 4),
    ('1b2f0aa7-fc7b-55f9-a343-9d5774c353d3'::uuid, 'maths', '6e', 'Fraction : sens - quotient', 'Dans la fraction 5/8, que dit le numérateur ?', 'mcq', '["On coupe en 5 parts","On prend 8 parts","On prend 5 parts","On coupe en 8 parts"]'::jsonb, 2, 'Le dénominateur (8) dit en combien de parts on coupe, le numérateur (5) combien on en prend.', 1),
    ('485e0658-9b9a-5ed4-908c-6ca4f988ff0e'::uuid, 'maths', '6e', 'Fraction : sens - quotient', 'Comment s’écrit le quotient 7 ÷ 4 sous forme de fraction ?', 'mcq', '["7/4","4/7","7/11","3/4"]'::jsonb, 0, 'Une fraction est un quotient : a/b = a ÷ b. Ici 7 ÷ 4 = 7/4 = 1,75.', 2),
    ('3623736a-02ed-5c2c-b6de-8e4e2afd532d'::uuid, 'maths', '6e', 'Fraction : sens - quotient', 'Combien font les 2/3 de 45 ?', 'mcq', '["15","30","90","22,5"]'::jsonb, 1, 'On divise par 3 puis on multiplie par 2 : 45 ÷ 3 × 2 = 15 × 2 = 30.', 3),
    ('c78018df-01b0-5318-8195-53003f0d0cfc'::uuid, 'maths', '6e', 'Fraction : sens - quotient', 'Quelle est la forme irréductible de 24/36 ?', 'mcq', '["6/9","12/18","3/4","2/3"]'::jsonb, 3, 'On divise en haut et en bas par 12 : 24/36 = 2/3. Les fractions 6/9 et 12/18 sont égales mais encore simplifiables.', 4),
    ('6b8b26cb-364a-5d2a-b5ec-05a704eca38c'::uuid, 'maths', '6e', 'Fraction : encadrer - comparer - ordonner', 'Comment ranger 1/2, 3/4 et 1/4 dans l’ordre croissant ?', 'mcq', '["1/4 ; 1/2 ; 3/4","3/4 ; 1/2 ; 1/4","1/2 ; 1/4 ; 3/4","1/4 ; 3/4 ; 1/2"]'::jsonb, 0, 'En quarts : 1/2 = 2/4. Avec le même dénominateur, on compare les numérateurs : 1 < 2 < 3.', 1),
    ('f887ed3d-1b03-52db-a31e-68ec1b009a69'::uuid, 'maths', '6e', 'Fraction : encadrer - comparer - ordonner', 'Entre quels entiers se situe 29/4 ?', 'mcq', '["Entre 6 et 7","Entre 7 et 8","Entre 8 et 9","Entre 29 et 30"]'::jsonb, 1, '29 ÷ 4 = 7,25, donc 7 < 29/4 < 8.', 2),
    ('0d4d0310-d6bf-59a9-a3dd-2542c9c450de'::uuid, 'maths', '6e', 'Fraction : encadrer - comparer - ordonner', 'Comment se comparent 7/9 et 9/7 ?', 'mcq', '["9/7 < 7/9","7/9 = 9/7","7/9 < 9/7","Impossible sans calcul"]'::jsonb, 2, '7/9 est inférieur à 1 (7 < 9) et 9/7 est supérieur à 1 (9 > 7) : on conclut sans aucun calcul.', 3),
    ('7e136533-ed75-51c2-92bb-b953e2a821d3'::uuid, 'maths', '6e', 'Fraction : encadrer - comparer - ordonner', 'Quelle fraction est égale à 50 % ?', 'mcq', '["1/5","1/4","1/50","1/2"]'::jsonb, 3, '50 % = 50/100 = 1/2 : la moitié.', 4),
    ('81ad009c-8446-5d59-966c-0d696309f454'::uuid, 'maths', '6e', 'Fractions et calculs', 'Combien font 3/5 + 4/5 ?', 'mcq', '["7/10","7/5","12/5","1/5"]'::jsonb, 1, 'Même dénominateur : on additionne les numérateurs et on garde le dénominateur. 3 + 4 = 7, donc 7/5.', 1),
    ('17e9dae7-fad7-57b6-8ba7-ad254b8ae37b'::uuid, 'maths', '6e', 'Fractions et calculs', 'Combien font 1/4 + 1/2 ?', 'mcq', '["2/6","1/6","3/4","2/8"]'::jsonb, 2, 'On met au même dénominateur : 1/2 = 2/4, puis 1/4 + 2/4 = 3/4.', 2),
    ('49229b6b-a72f-5c29-9669-ef4f8836e6eb'::uuid, 'maths', '6e', 'Fractions et calculs', 'Combien font 2/5 × 5/6 ?', 'mcq', '["1/3","7/11","10/11","2/3"]'::jsonb, 0, 'Numérateurs entre eux, dénominateurs entre eux : 10/30 = 1/3 après simplification.', 3),
    ('83b992d4-55b8-511e-a25f-52bd5bef7771'::uuid, 'maths', '6e', 'Fractions et calculs', 'Quel est le résultat de 4 × 3/8, écrit sous forme irréductible ?', 'mcq', '["12/8","12/32","3/8","3/2"]'::jsonb, 3, 'On multiplie le numérateur seul : 12/8, puis on simplifie par 4 : 3/2. Le résultat 12/8 n’est pas irréductible.', 4),
    ('216afe24-881e-57b2-8bdf-5928c9910c65'::uuid, 'maths', '6e', 'Pourcentages', 'Combien font 35 % de 200 ?', 'mcq', '["70","35","7","65"]'::jsonb, 0, '35 % = 25 % + 10 % : 200 ÷ 4 = 50 et 200 ÷ 10 = 20, donc 50 + 20 = 70.', 1),
    ('45825988-52b7-52a8-aeed-4f568169bd44'::uuid, 'maths', '6e', 'Pourcentages', 'Un article à 80 € est en réduction de 30 %. Quel est son nouveau prix ?', 'mcq', '["24 €","56 €","50 €","110 €"]'::jsonb, 1, 'On garde 70 % du prix : 80 × 0,7 = 56 €. Le 24 € est le montant de la réduction.', 2),
    ('e5c05752-4107-5ab0-8636-c1437f6d3355'::uuid, 'maths', '6e', 'Pourcentages', 'Un prix de 40 € augmente de 10 %. Quel est le nouveau prix ?', 'mcq', '["4 €","41 €","44 €","50 €"]'::jsonb, 2, '10 % de 40 = 4 €, donc 40 + 4 = 44 € (ou 40 × 1,1 = 44).', 3),
    ('81d4035d-c690-5136-be8e-77ae74fd7501'::uuid, 'maths', '6e', 'Pourcentages', 'Dans une classe de 20 élèves, 9 sont demi-pensionnaires. Quel pourcentage cela représente-t-il ?', 'mcq', '["9 %","20 %","55 %","45 %"]'::jsonb, 3, '9 ÷ 20 = 0,45, soit 45 %.', 4),
    ('73eaa494-11d2-5990-bd3e-508ba897bdf2'::uuid, 'maths', '6e', 'Résoudre des problèmes mettant en jeu des nombres inconnus', 'Comment trouve-t-on x dans x − 9 = 15 ?', 'mcq', '["En calculant 15 − 9","En calculant 15 + 9","En calculant 15 × 9","En calculant 9 − 15"]'::jsonb, 1, 'L’opération inverse de la soustraction est l’addition : x = 15 + 9 = 24.', 1),
    ('17a88615-7a47-5bb3-95a5-219e4cc81d8d'::uuid, 'maths', '6e', 'Résoudre des problèmes mettant en jeu des nombres inconnus', 'Comment trouve-t-on x dans x ÷ 5 = 8 ?', 'mcq', '["En calculant 8 + 5","En calculant 8 − 5","En calculant 8 × 5","En calculant 8 ÷ 5"]'::jsonb, 2, 'L’opération inverse de la division est la multiplication : x = 8 × 5 = 40. Vérification : 40 ÷ 5 = 8.', 2),
    ('3aa13396-8bc9-5387-a282-f995ec75e9be'::uuid, 'maths', '6e', 'Résoudre des problèmes mettant en jeu des nombres inconnus', 'Un livre coûte 3 fois moins cher qu’un autre qui coûte 24 €. Quel est son prix ?', 'mcq', '["72 €","21 €","27 €","8 €"]'::jsonb, 3, '« 3 fois moins » est une division, malgré le mot « fois » : 24 ÷ 3 = 8 €.', 3),
    ('fdea190b-5b5c-53bf-823c-e6e3225b326f'::uuid, 'maths', '6e', 'Résoudre des problèmes mettant en jeu des nombres inconnus', 'Léa a 35 € et achète 3 cahiers à 4 € pièce. Combien lui reste-t-il ?', 'mcq', '["23 €","31 €","8 €","32 €"]'::jsonb, 0, 'Étape 1 : 3 × 4 = 12 € dépensés. Étape 2 : 35 − 12 = 23 €. Un problème à deux étapes demande deux calculs.', 4),
    ('1f4769e9-c22b-525a-bd7e-f0a223fb4955'::uuid, 'maths', '6e', 'Statistiques', 'Sur 30 élèves, 6 viennent à vélo. Quelle est la fréquence des élèves à vélo ?', 'mcq', '["6 %","20 %","30 %","180 %"]'::jsonb, 1, 'Fréquence = effectif ÷ effectif total = 6 ÷ 30 = 0,2, soit 20 %.', 1),
    ('af15df78-9a4c-56c9-bb47-3ce4e293679e'::uuid, 'maths', '6e', 'Statistiques', 'Dans un diagramme circulaire, quel angle occupe une catégorie de 20 % ?', 'mcq', '["20°","36°","72°","144°"]'::jsonb, 2, 'Angle = fréquence × 360° = 0,2 × 360 = 72°.', 2),
    ('072c1d8d-357e-5a8b-942c-61ac4105d1fc'::uuid, 'maths', '6e', 'Statistiques', 'Quelle est la moyenne des notes 8, 12, 14, 10 et 16 ?', 'mcq', '["10","14","60","12"]'::jsonb, 3, 'La somme vaut 60 et il y a 5 notes : 60 ÷ 5 = 12.', 3),
    ('78825261-6f47-59b0-af06-55fb3a93f6c5'::uuid, 'maths', '6e', 'Statistiques', 'Quel graphique convient le mieux pour montrer une évolution dans le temps ?', 'mcq', '["Le graphique cartésien","Le diagramme circulaire","Le diagramme en barres","Le tableau de données"]'::jsonb, 0, 'Le graphique cartésien relie des valeurs au fil du temps ; le diagramme circulaire montre des parts d’un tout.', 4),
    ('ed05d92b-e035-5fb4-afc3-1c671980ce85'::uuid, 'maths', '6e', 'Probabilités', 'Une urne contient 3 boules rouges et 5 boules bleues. Quelle est la probabilité de tirer une boule rouge ?', 'mcq', '["3/5","3/8","5/8","1/3"]'::jsonb, 1, 'Il y a 3 cas favorables sur 3 + 5 = 8 cas possibles : 3/8.', 1),
    ('95ba3a9b-1dbb-5d7f-aea0-0445ca9f9861'::uuid, 'maths', '6e', 'Probabilités', 'Un événement A a pour probabilité 0,3. Quelle est la probabilité de son contraire ?', 'mcq', '["0,3","1,3","0,7","0,03"]'::jsonb, 2, 'P(A) + P(contraire) = 1, donc 1 − 0,3 = 0,7.', 2),
    ('d09414f2-f410-500b-a9d7-bc0791636a03'::uuid, 'maths', '6e', 'Probabilités', 'Avec un dé à 6 faces, quelle est la probabilité d’obtenir un nombre strictement supérieur à 4 ?', 'mcq', '["1/6","2/3","1/2","1/3"]'::jsonb, 3, 'Les issues favorables sont 5 et 6 : 2 cas sur 6, soit 2/6 = 1/3.', 3),
    ('538710f5-f05b-5d2f-8e2c-20fdbabc419e'::uuid, 'maths', '6e', 'Probabilités', 'Quand on répète une expérience aléatoire un très grand nombre de fois, la fréquence observée…', 'mcq', '["se rapproche de la probabilité","s’éloigne de la probabilité","devient égale à 1","devient égale à 0"]'::jsonb, 0, 'Sur peu d’essais la fréquence peut s’écarter de la probabilité ; plus on répète, plus elle s’en rapproche.', 4),
    ('7057f0d2-d725-545b-85db-908bb9620b13'::uuid, 'musique', '6e', 'Les paramètres du son', 'Dans quelle unité mesure-t-on la fréquence d’un son ?', 'mcq', '["Le décibel","Le hertz","Le mètre","La seconde"]'::jsonb, 1, 'La fréquence se mesure en hertz (Hz) : plus elle est élevée, plus le son est aigu.', 1),
    ('c3b3dfbf-31fd-5b57-bc9e-3b620b5ad53d'::uuid, 'musique', '6e', 'Les paramètres du son', 'Une blanche dure quelle fraction d’une ronde ?', 'mcq', '["Le quart","Le double","Le tiers","La moitié"]'::jsonb, 3, 'Chaque figure de note vaut la moitié de la précédente : ronde, blanche, noire, croche.', 2),
    ('c53a96cd-9cbf-5069-9d13-4aa0add9e91c'::uuid, 'musique', '6e', 'Les paramètres du son', 'Que signifie la nuance « piano » ?', 'mcq', '["Doux","Fort","Très fort","Moyennement fort"]'::jsonb, 0, 'Piano indique une intensité douce ; forte indique un son fort.', 3),
    ('069fcb24-f481-5329-bb95-57ed04a53455'::uuid, 'musique', '6e', 'Les paramètres du son', 'D’où vient le timbre d’un instrument ?', 'mcq', '["De la durée des notes","De la fréquence jouée","Des harmoniques qu’il produit","Du volume choisi"]'::jsonb, 2, 'Le timbre vient des harmoniques produites par l’instrument : c’est ce qui distingue une flûte d’un violon sur la même note.', 4),
    ('fbed1d6d-f17a-5dec-8b96-54274e11a31e'::uuid, 'musique', '6e', 'La voix et les familles d’instruments', 'Lequel de ces instruments est une percussion déterminée ?', 'mcq', '["La caisse claire","Les cymbales","Le xylophone","Le triangle"]'::jsonb, 2, 'Le xylophone produit des hauteurs précises ; caisse claire, cymbales et triangle n’ont pas de hauteur définie.', 1),
    ('9d973526-5d09-59cc-9dc6-3970c707754a'::uuid, 'musique', '6e', 'La voix et les familles d’instruments', 'Quelle est la voix d’homme la plus grave ?', 'mcq', '["Le ténor","Le baryton","L’alto","La basse"]'::jsonb, 3, 'Les voix d’hommes, de la plus aiguë à la plus grave, sont le ténor, le baryton et la basse.', 2),
    ('8a605d4a-037e-5df6-b38e-de3abefe21f4'::uuid, 'musique', '6e', 'La voix et les familles d’instruments', 'Lequel de ces instruments appartient à la famille des cuivres ?', 'mcq', '["Le trombone","Le hautbois","La clarinette","Le basson"]'::jsonb, 0, 'Chez les cuivres (trompette, cor, trombone, tuba), le son naît de la vibration des lèvres.', 3),
    ('8ba2c3fd-1abe-5bf3-bf79-85fe77ebf49e'::uuid, 'musique', '6e', 'La voix et les familles d’instruments', 'La guitare est un instrument à cordes frottées.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La guitare est à cordes pincées, comme la harpe ; les cordes frottées utilisent un archet.', 4),
    ('e74b149e-0376-5c41-99ec-51f762b43f84'::uuid, 'musique', '6e', 'Rythme, pulsation et tempo', 'Quelle indication de tempo signifie « très rapide » ?', 'mcq', '["Largo","Adagio","Andante","Presto"]'::jsonb, 3, 'Presto est l’indication de tempo la plus rapide ; largo est la plus lente.', 1),
    ('f24f9130-8788-5689-ad25-3c8da1cab378'::uuid, 'musique', '6e', 'Rythme, pulsation et tempo', 'À combien de temps la marche est-elle le plus souvent mesurée ?', 'mcq', '["3 temps","2 temps","4 temps","6 temps"]'::jsonb, 1, 'La mesure à 2 temps correspond à la marche ; à 3 temps, c’est la valse.', 2),
    ('143510e5-d773-5579-b3db-1e01b8a213a2'::uuid, 'musique', '6e', 'Rythme, pulsation et tempo', 'Comment appelle-t-on l’organisation des durées posée par-dessus la pulsation ?', 'mcq', '["Le rythme","Le tempo","La mesure","La nuance"]'::jsonb, 0, 'Le rythme dessine une figure de notes longues et courtes sur la pulsation, qui est le battement régulier.', 3),
    ('d846dfd0-e5ab-5abc-b022-1025652ddc1f'::uuid, 'musique', '6e', 'Rythme, pulsation et tempo', 'Que signifie l’indication « adagio » ?', 'mcq', '["Vif","Très rapide","Lent","Très lent"]'::jsonb, 2, 'Adagio désigne un tempo lent, plus rapide que largo et plus lent qu’andante.', 4),
    ('720375fe-ae97-5910-9e0f-2c4585518e70'::uuid, 'physique-chimie', '6e', 'La matière', 'Comment s’appelle le passage direct de l’état solide à l’état gazeux ?', 'mcq', '["La fusion","La vaporisation","La sublimation","La liquéfaction"]'::jsonb, 2, 'La sublimation est le passage direct du solide au gaz, sans passer par l’état liquide.', 1),
    ('ab24fd6c-d48e-5f4d-94e2-6ea8a387f414'::uuid, 'physique-chimie', '6e', 'La matière', 'Comment s’appelle le passage de l’état liquide à l’état solide ?', 'mcq', '["La solidification","La fusion","La vaporisation","La sublimation"]'::jsonb, 0, 'Liquide vers solide : c’est la solidification, l’inverse de la fusion.', 2),
    ('a05678c6-4101-5f58-b14d-20263a3c936f'::uuid, 'physique-chimie', '6e', 'La matière', 'Comment est la surface libre d’un liquide au repos dans un verre ?', 'mcq', '["Bombée","Inclinée","Ondulée","Horizontale"]'::jsonb, 3, 'Un liquide prend la forme de son récipient, mais sa surface libre reste horizontale.', 3),
    ('ede18288-42d2-5448-bf19-0f874990e39f'::uuid, 'physique-chimie', '6e', 'La matière', 'La glace, l’eau liquide et la vapeur d’eau sont trois substances différentes.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Un changement d’état ne change pas la matière : glace, eau liquide et vapeur sont toutes de l’eau.', 4),
    ('2d1a8f4a-6cc5-5666-8bd8-9f358ee07276'::uuid, 'physique-chimie', '6e', 'Les propriétés de la matière', 'Un ballon de baudruche gonflé est comparé au même ballon dégonflé. Que constate-t-on ?', 'mcq', '["Il est plus lourd","Il est plus léger","Il a la même masse","Il n’a plus de masse"]'::jsonb, 0, 'L’air a une masse : le ballon gonflé est plus lourd que le ballon dégonflé.', 1),
    ('733a9e1f-b004-5c72-9454-9053c29ae8f5'::uuid, 'physique-chimie', '6e', 'Les propriétés de la matière', 'Combien de grammes y a-t-il dans 1 kg ?', 'mcq', '["100 g","1 000 g","10 g","10 000 g"]'::jsonb, 1, 'Un kilogramme vaut 1 000 grammes, et un gramme 1 000 milligrammes.', 2),
    ('4196804a-59d5-5f6c-9f53-83db9a9c67a3'::uuid, 'physique-chimie', '6e', 'Les propriétés de la matière', 'Comparée à l’eau, l’alcool fond à une température…', 'mcq', '["Plus haute","Identique","Bien plus basse","Impossible à mesurer"]'::jsonb, 2, 'Chaque substance a ses températures de changement d’état : l’eau fond à 0 °C, l’alcool bien plus bas.', 3),
    ('8bcd7a34-dc8d-5793-96cf-9b634dd677a3'::uuid, 'physique-chimie', '6e', 'Les propriétés de la matière', 'Que mesure la masse d’un objet ?', 'mcq', '["La place qu’il occupe","L’attraction de la Terre","Sa température","La quantité de matière"]'::jsonb, 3, 'La masse désigne la quantité de matière ; le volume est la place occupée.', 4),
    ('893b7b50-5adf-51f0-91a3-37e1c708abc0'::uuid, 'physique-chimie', '6e', 'Les mélanges', 'Comment récupère-t-on le sel d’une eau salée ?', 'mcq', '["En faisant évaporer l’eau","En filtrant le mélange","En décantant","En ajoutant de l’eau"]'::jsonb, 0, 'On chauffe pour faire partir le solvant : le sel dissous reste, comme dans les marais salants.', 1),
    ('6fd5ebae-4b53-521a-ad8f-49ff8a302bc8'::uuid, 'physique-chimie', '6e', 'Les mélanges', 'Quelle technique laisse reposer un mélange pour que le plus lourd tombe au fond ?', 'mcq', '["La filtration","La décantation","L’évaporation","La dissolution"]'::jsonb, 1, 'La décantation sépare deux couches ; on transvase ensuite doucement le liquide du dessus.', 2),
    ('00587e26-d449-5a56-9557-697e17b1f4d6'::uuid, 'physique-chimie', '6e', 'Les mélanges', 'Comment appelle-t-on le liquide qui a traversé un filtre ?', 'mcq', '["Le soluté","Le solvant","Le dépôt","Le filtrat"]'::jsonb, 3, 'Le liquide qui passe à travers le filtre est le filtrat ; le filtre retient les particules solides.', 3),
    ('40b7ca0f-a0f9-5cef-a2cc-609e4fa68e50'::uuid, 'physique-chimie', '6e', 'Les mélanges', 'L’air est un mélange homogène de gaz.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'On ne distingue pas ses constituants : diazote, dioxygène et autres gaz forment un mélange homogène.', 4),
    ('fd367877-89f3-535a-8fc0-7636975c40f4'::uuid, 'physique-chimie', '6e', 'Les différentes formes d’énergie', 'De quoi dépend l’énergie cinétique d’un objet en mouvement ?', 'mcq', '["De sa masse et surtout de sa vitesse","De sa hauteur seulement","De sa température","De sa couleur"]'::jsonb, 0, 'Elle augmente avec la masse et beaucoup avec la vitesse.', 1),
    ('1a3bab29-413c-5c1f-9c2d-5e1d4113e8d1'::uuid, 'physique-chimie', '6e', 'Les différentes formes d’énergie', 'Laquelle de ces sources d’énergie est non renouvelable ?', 'mcq', '["La géothermie","L’uranium","La biomasse","L’énergie de l’eau"]'::jsonb, 1, 'Les réserves d’uranium s’épuisent, comme celles du charbon, du pétrole et du gaz naturel.', 2),
    ('f1557ba4-824b-5bc9-9ca9-d1336967245f'::uuid, 'physique-chimie', '6e', 'Les différentes formes d’énergie', 'Quelle unité figure sur les factures d’électricité ?', 'mcq', '["Le joule","Le newton","Le kilowattheure","Le degré Celsius"]'::jsonb, 2, 'Pour l’électricité domestique, on utilise le kilowattheure (kWh), plus pratique que le joule.', 3),
    ('84756e95-7722-5f03-aa3f-51b3c57b5736'::uuid, 'physique-chimie', '6e', 'Les différentes formes d’énergie', 'Dans la chaîne pile → ampoule → lumière et chaleur, quelle énergie est stockée dans la pile ?', 'mcq', '["L’énergie nucléaire","L’énergie lumineuse","L’énergie cinétique","L’énergie chimique"]'::jsonb, 3, 'Une pile stocke de l’énergie chimique qu’elle convertit en énergie électrique.', 4),
    ('106beb6b-cf6e-519b-b9ea-663dc72d2865'::uuid, 'physique-chimie', '6e', 'Les conversions d’énergie', 'Quelle conversion réalise un moteur électrique ?', 'mcq', '["Cinétique → électrique","Électrique → cinétique","Chimique → lumineuse","Lumineuse → électrique"]'::jsonb, 1, 'Un moteur électrique convertit l’énergie électrique en énergie cinétique.', 1),
    ('66ed2f90-4d1c-5e52-bc18-7cb0e3b5e437'::uuid, 'physique-chimie', '6e', 'Les conversions d’énergie', 'Quelle suite de conversions se produit dans un barrage ?', 'mcq', '["Chimique, puis lumineuse","Cinétique, puis de position","De position, puis cinétique, puis électrique","Électrique, puis cinétique"]'::jsonb, 2, 'L’eau retenue en hauteur (énergie de position) se met en mouvement, puis entraîne un générateur qui produit de l’électricité.', 2),
    ('3e6d7688-691b-535b-b12c-021daf58e48c'::uuid, 'physique-chimie', '6e', 'Les conversions d’énergie', 'Quelle lampe a remplacé l’ampoule à filament pour gaspiller moins d’énergie ?', 'mcq', '["La LED","La bougie","La lampe à pétrole","La lampe à huile"]'::jsonb, 0, 'L’ampoule à filament gaspillait 95 % de l’énergie en chaleur ; la LED a un meilleur rendement.', 3),
    ('9445ad89-a81f-5eb6-a7b4-90757e95b940'::uuid, 'physique-chimie', '6e', 'Les conversions d’énergie', 'Que signifie un rendement élevé pour un appareil ?', 'mcq', '["Il consomme beaucoup","Il coûte cher","Il chauffe fortement","Il gaspille peu d’énergie"]'::jsonb, 3, 'Le rendement compare l’énergie utile à l’énergie consommée : plus il est élevé, moins on gaspille.', 4),
    ('ca0ed4cc-8082-50a3-9f60-5018b0f950d4'::uuid, 'physique-chimie', '6e', 'L’énergie, une production diverse et une consommation à réduire', 'Quel est le rôle de la turbine dans une centrale électrique ?', 'mcq', '["Elle stocke l’électricité","Elle entraîne l’alternateur","Elle refroidit la vapeur","Elle isole le bâtiment"]'::jsonb, 1, 'La turbine, mise en rotation, entraîne l’alternateur, qui produit l’électricité.', 1),
    ('3cd19663-3209-53a5-86fe-76aa87a62632'::uuid, 'physique-chimie', '6e', 'L’énergie, une production diverse et une consommation à réduire', 'Quelle réaction chauffe l’eau dans une centrale nucléaire ?', 'mcq', '["La fission de l’uranium","La combustion du charbon","La fusion de la glace","La combustion du gaz"]'::jsonb, 0, 'La fission des noyaux d’uranium dégage de la chaleur qui produit la vapeur faisant tourner la turbine.', 2),
    ('bc0a26c5-0107-56e1-8d0f-a16a2fafbe59'::uuid, 'physique-chimie', '6e', 'L’énergie, une production diverse et une consommation à réduire', 'À quoi sert l’étiquette énergie d’un appareil ?', 'mcq', '["À connaître son prix de vente","À savoir sa date de fabrication","À mesurer sa masse","À comparer sa consommation avant achat"]'::jsonb, 3, 'Lire l’étiquette énergie permet de choisir l’appareil qui consomme le moins.', 3),
    ('7a73516b-6a22-5065-ba6a-1f7adf51fee5'::uuid, 'physique-chimie', '6e', 'L’énergie, une production diverse et une consommation à réduire', 'Une centrale nucléaire rejette presque pas de CO₂, mais produit des déchets radioactifs.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est son avantage sur le thermique à flamme, mais ses déchets doivent être stockés très longtemps.', 4),
    ('754b1394-9888-51c2-a02b-22fd9c3fd5d7'::uuid, 'physique-chimie', '6e', 'Les signaux', 'Pourquoi voit-on la Lune ?', 'mcq', '["Elle produit sa propre lumière","Elle réfléchit la chaleur","Elle renvoie la lumière du Soleil","Elle est plus proche que le Soleil"]'::jsonb, 2, 'La Lune est une source diffusante : elle renvoie la lumière reçue, elle n’en produit pas.', 1),
    ('133b4d9f-5e81-5abe-bfc5-457cb5957cc5'::uuid, 'physique-chimie', '6e', 'Les signaux', 'Où se forme l’ombre portée d’un objet ?', 'mcq', '["Sur le sol ou un écran","Sur la face non éclairée","Dans l’œil de l’observateur","À l’intérieur de l’objet"]'::jsonb, 0, 'L’ombre portée se forme sur le sol ou un écran ; l’ombre propre est sur la face non éclairée.', 2),
    ('12cf7f1a-082a-5bfe-84b9-a1046513fd7d'::uuid, 'physique-chimie', '6e', 'Les signaux', 'Quel phénomène explique la formation des ombres ?', 'mcq', '["La vitesse de la lumière","La propagation rectiligne de la lumière","La vibration de l’objet","La couleur de la source"]'::jsonb, 1, 'La lumière se propage en ligne droite : l’objet arrête ses rayons et laisse une zone sombre derrière lui.', 3),
    ('dd6129d3-1cb0-5c0c-bb25-009b43dc133e'::uuid, 'physique-chimie', '6e', 'Les signaux', 'Dans quels milieux le son peut-il se propager ?', 'mcq', '["Seulement dans l’air libre","Dans le vide seulement","Dans l’air, sans l’eau ni les solides","Dans l’air, l’eau et les solides"]'::jsonb, 3, 'Le son se propage dans l’air, l’eau et les solides, mais jamais dans le vide.', 4),
    ('02def9e2-c1e5-570f-bb43-b7d438f52ba5'::uuid, 'physique-chimie', '6e', 'Transmettre l’information', 'Dans une chaîne de transmission, quel est le rôle de l’émetteur ?', 'mcq', '["Décoder l’information","Coder l’information","Stocker l’information","Transporter le signal"]'::jsonb, 1, 'L’émetteur code l’information, le canal la transporte, le récepteur la décode.', 1),
    ('bc1a8c2a-f1ab-5f02-95e8-2cf4c1d7940d'::uuid, 'physique-chimie', '6e', 'Transmettre l’information', 'Par où voyagent les ondes radio et le wifi ?', 'mcq', '["Dans un fil de verre","Dans un câble électrique","Dans l’air, sans fil","Uniquement sous terre"]'::jsonb, 2, 'Les ondes se propagent dans l’air et même dans le vide, sans fil.', 2),
    ('e830794d-e823-52d1-af2d-879929b2791c'::uuid, 'physique-chimie', '6e', 'Transmettre l’information', 'Lequel de ces moyens de transmission est le plus ancien ?', 'mcq', '["Le télégraphe","Le téléphone","La radio","Les signaux de fumée"]'::jsonb, 3, 'Les signaux de fumée précèdent les tambours, les pigeons voyageurs, le télégraphe puis le téléphone.', 3),
    ('c0041356-b907-5298-8b38-d128fd2ca61d'::uuid, 'physique-chimie', '6e', 'Transmettre l’information', 'Pour un réseau, une photo et un message ne diffèrent que par le nombre de 0 et de 1.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Tout est converti en 0 et en 1 : la différence tient au nombre de 0 et de 1 à transmettre.', 4),
    ('e4679305-6f1f-550a-b85d-e724784df80d'::uuid, 'physique-chimie', '6e', 'La trajectoire et la vitesse moyenne', 'Un train roule 120 km à 60 km/h. Combien de temps dure le trajet ?', 'mcq', '["2 h","0,5 h","180 h","7 200 h"]'::jsonb, 0, 't = d ÷ v = 120 ÷ 60 = 2 h.', 1),
    ('25cba1d3-2a15-569e-8ae4-18287c2c00a8'::uuid, 'physique-chimie', '6e', 'La trajectoire et la vitesse moyenne', 'Un passager est assis dans un train. Par rapport à quoi est-il immobile ?', 'mcq', '["Au quai","Au train","Aux poteaux","Au paysage"]'::jsonb, 1, 'Le passager est immobile par rapport au train, mais en mouvement par rapport au quai : il faut préciser le référentiel.', 2),
    ('29b6efbf-7ad5-5bed-a6a4-afe8238c3aac'::uuid, 'physique-chimie', '6e', 'La trajectoire et la vitesse moyenne', 'Un cycliste roule à 20 km/h pendant 3 h. Quelle distance parcourt-il ?', 'mcq', '["6,7 km","23 km","60 km","17 km"]'::jsonb, 2, 'd = v × t = 20 × 3 = 60 km.', 3),
    ('bfc0c55a-6181-5068-9870-a2812738cee4'::uuid, 'physique-chimie', '6e', 'La trajectoire et la vitesse moyenne', 'Combien font 72 km/h en m/s ?', 'mcq', '["72 m/s","7,2 m/s","259,2 m/s","20 m/s"]'::jsonb, 3, 'Pour passer de km/h à m/s, on divise par 3,6 : 72 ÷ 3,6 = 20 m/s.', 4),
    ('996328c9-a80f-5c59-accf-7e385f2de6b6'::uuid, 'physique-chimie', '6e', 'Les variations de vitesse', 'Une balle lancée vers le haut a un mouvement…', 'mcq', '["uniforme","accéléré","circulaire uniforme","ralenti"]'::jsonb, 3, 'Sa vitesse diminue pendant la montée : son mouvement est ralenti.', 1),
    ('2f30e301-bec1-5926-b97b-32c3f58ccae2'::uuid, 'physique-chimie', '6e', 'Les variations de vitesse', 'Lequel de ces mouvements est uniforme ?', 'mcq', '["Une voiture qui démarre","Un escalator en marche","Une bille sur une pente","Un vélo qui freine"]'::jsonb, 1, 'Un escalator garde une vitesse qui ne change pas : son mouvement est uniforme.', 2),
    ('2f1fb8db-210e-5e6c-b505-83b0fb776337'::uuid, 'physique-chimie', '6e', 'Les variations de vitesse', 'Sur une chronophotographie, les écarts entre les positions se resserrent. Que dit-on du mouvement ?', 'mcq', '["Il est ralenti","Il est uniforme","Il est accéléré","Il est circulaire"]'::jsonb, 0, 'Comme la durée entre deux images est constante, des écarts qui diminuent signifient que la vitesse diminue.', 3),
    ('20e0f3b4-2677-582e-947a-2c3c6594d1d1'::uuid, 'physique-chimie', '6e', 'Les variations de vitesse', 'Quel mouvement décrit une voiture qui démarre tout droit ?', 'mcq', '["Circulaire uniforme","Rectiligne uniforme","Rectiligne accéléré","Circulaire ralenti"]'::jsonb, 2, 'La trajectoire est droite (rectiligne) et la vitesse augmente : le mouvement est rectiligne accéléré.', 4),
    ('3ad01d8a-8ee3-5681-b52b-12c98f1e9a83'::uuid, 'svt', '6e', 'Le développement et la reproduction des êtres vivants', 'Lequel de ces exemples est une reproduction asexuée ?', 'mcq', '["La pollinisation d’une fleur","Le bouturage d’une plante","La ponte d’œufs fécondés","La naissance d’un chaton"]'::jsonb, 1, 'Le bouturage ne demande qu’un seul individu et donne une copie identique à la plante d’origine.', 1),
    ('3720e401-89e4-599f-939d-36b492282d26'::uuid, 'svt', '6e', 'Le développement et la reproduction des êtres vivants', 'Quel groupe d’animaux pratique la fécondation interne ?', 'mcq', '["Les poissons","Les grenouilles","Les oiseaux","Les crapauds"]'::jsonb, 2, 'Chez les oiseaux, la fécondation a lieu dans le corps de la femelle ; poissons et grenouilles libèrent leurs cellules dans l’eau.', 2),
    ('d7d87990-f5eb-5edb-b933-0c4c2ee61673'::uuid, 'svt', '6e', 'Le développement et la reproduction des êtres vivants', 'À quoi sert la dispersion des graines ?', 'mcq', '["À éloigner les jeunes plantes de la plante mère","À produire le pollen","À former le fruit","À féconder l’ovule"]'::jsonb, 0, 'Vent, animaux ou eau emportent les graines loin de la plante mère, ce qui évite la concurrence.', 3),
    ('26693561-4523-51f5-bf8d-c79d3fbcc40c'::uuid, 'svt', '6e', 'Le développement et la reproduction des êtres vivants', 'Le vent peut assurer la pollinisation de certaines plantes.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La pollinisation est assurée par le vent ou par des insectes pollinisateurs.', 4),
    ('71a5bed3-ae93-5073-bde2-eb51d3df6e6a'::uuid, 'svt', '6e', 'Le développement et la reproduction des êtres humains', 'Quel organe assure les échanges entre la mère et le fœtus ?', 'mcq', '["Le placenta","La trompe","L’ovaire","Le col de l’utérus"]'::jsonb, 0, 'Le placenta assure les échanges avec la mère ; le cordon ombilical transporte dioxygène, nutriments et déchets.', 1),
    ('4adecd3d-78b7-54ce-8889-226c7105ab0a'::uuid, 'svt', '6e', 'Le développement et la reproduction des êtres humains', 'Que devient l’embryon vers la fin du deuxième mois ?', 'mcq', '["Une cellule-œuf","Un ovule","Une larve","Un fœtus"]'::jsonb, 3, 'Après la fécondation et la nidation, l’embryon devient un fœtus vers la fin du 2e mois.', 2),
    ('b7833003-0c56-5fa3-9b51-6fe24001372b'::uuid, 'svt', '6e', 'Le développement et la reproduction des êtres humains', 'Que se passe-t-il quand l’ovule libéré n’est pas fécondé ?', 'mcq', '["Il devient un embryon","La nidation a lieu","La paroi de l’utérus est évacuée","Un fœtus se forme"]'::jsonb, 2, 'La paroi de l’utérus est évacuée : ce sont les règles, environ une fois par mois.', 3),
    ('ea2e2d72-2b23-52e4-9afa-94a023eb54ce'::uuid, 'svt', '6e', 'Le développement et la reproduction des êtres humains', 'Lequel de ces changements apparaît chez le garçon à la puberté ?', 'mcq', '["Le bassin s’élargit","La voix mue","Les seins se développent","Les règles arrivent"]'::jsonb, 1, 'La mue de la voix, la pilosité et le développement musculaire sont des caractères sexuels secondaires du garçon.', 4),
    ('6b9fd24b-2af9-59aa-ae18-8af0e5494d1b'::uuid, 'svt', '6e', 'Les aliments, une source d’éléments vitaux pour l’organisme', 'Lequel de ces aliments est riche en glucides ?', 'mcq', '["L’huile","Le poisson","Les pâtes","Le beurre"]'::jsonb, 2, 'Pain, pâtes, riz et fruits apportent des glucides, le carburant principal de l’organisme.', 1),
    ('0650c993-a8fc-547f-aada-f7349714bc50'::uuid, 'svt', '6e', 'Les aliments, une source d’éléments vitaux pour l’organisme', 'À quoi servent surtout les lipides ?', 'mcq', '["Une réserve d’énergie","Des matériaux de construction","Faire fonctionner l’intestin","Transporter le dioxygène"]'::jsonb, 0, 'Les lipides forment une réserve d’énergie et entrent dans la constitution des membranes.', 2),
    ('7c9a71e8-c209-56d4-9da3-bb46e1043e7e'::uuid, 'svt', '6e', 'Les aliments, une source d’éléments vitaux pour l’organisme', 'Quelle est la seule boisson indispensable ?', 'mcq', '["Le jus de fruit","Le lait","La boisson gazeuse","L’eau"]'::jsonb, 3, 'L’eau représente environ 60 % de la masse du corps : c’est la seule boisson indispensable.', 3),
    ('74cda823-da74-55f4-b833-70f7a8f249a4'::uuid, 'svt', '6e', 'Les aliments, une source d’éléments vitaux pour l’organisme', 'Une alimentation équilibrée doit l’être parfaitement à chaque repas.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Équilibré ne veut pas dire parfait à chaque repas : l’essentiel est de varier sur la semaine.', 4),
    ('da6fc147-2a85-5dae-b755-ac94448cbf81'::uuid, 'svt', '6e', 'Les besoins vitaux de nos organes', 'Quel déchet les reins évacuent-ils dans l’urine ?', 'mcq', '["Le dioxyde de carbone","L’urée","Le glucose","Le dioxygène"]'::jsonb, 1, 'Les reins filtrent le sang et fabriquent l’urine, qui évacue l’urée.', 1),
    ('16bb2f62-d48d-5673-893d-25224257acf2'::uuid, 'svt', '6e', 'Les besoins vitaux de nos organes', 'Quel trajet suit le dioxyde de carbone au niveau des poumons ?', 'mcq', '["De l’air vers le sang","Il reste dans le sang","Du sang vers les alvéoles, puis l’air","Des reins vers l’air"]'::jsonb, 2, 'Il fait le trajet inverse du dioxygène : il quitte le sang, passe dans les alvéoles, puis est rejeté avec l’air expiré.', 2),
    ('b1a4a6d6-1792-5d5f-b84e-04562b167d4e'::uuid, 'svt', '6e', 'Les besoins vitaux de nos organes', 'Que produit la respiration cellulaire en plus de l’énergie ?', 'mcq', '["De l’urée et du glucose","Du dioxygène et des fibres","De l’urée seulement","Du dioxyde de carbone et de l’eau"]'::jsonb, 3, 'Nutriments + dioxygène donnent de l’énergie, du dioxyde de carbone et de l’eau.', 3),
    ('1533e276-9e99-527b-b4ac-1da74b61a432'::uuid, 'svt', '6e', 'Les besoins vitaux de nos organes', 'Quel est le rôle du cœur ?', 'mcq', '["Faire circuler le sang sans arrêt","Filtrer le sang","Digérer les aliments","Stocker le dioxygène"]'::jsonb, 0, 'Le cœur est la pompe qui fait circuler le sang dans les vaisseaux.', 4),
    ('4b94a9f6-e8e4-54fd-85c1-38bd6e494b91'::uuid, 'svt', '6e', 'Nourrir les hommes : la culture et l’élevage', 'Comment s’appelle la fabrication de matière par une plante verte à la lumière ?', 'mcq', '["La respiration cellulaire","La digestion","La photosynthèse","La germination"]'::jsonb, 2, 'Avec la lumière, l’eau, le dioxyde de carbone et les sels minéraux, la plante fabrique sa propre matière : c’est la photosynthèse.', 1),
    ('adb3d1ca-1c02-51b0-ab53-3f96c8a8a130'::uuid, 'svt', '6e', 'Nourrir les hommes : la culture et l’élevage', 'Par quelles parties la plante absorbe-t-elle l’eau et les sels minéraux ?', 'mcq', '["Les racines","Les feuilles","Les fleurs","Les fruits"]'::jsonb, 0, 'L’eau et les sels minéraux viennent du sol et sont absorbés par les racines.', 2),
    ('98252057-5a93-5167-9d43-4d3717fb72a9'::uuid, 'svt', '6e', 'Nourrir les hommes : la culture et l’élevage', 'Quel est un inconvénient fréquent de l’agriculture biologique ?', 'mcq', '["Elle pollue davantage l’eau","Elle utilise beaucoup de pesticides","Elle réduit le nombre de plantes","Des rendements souvent inférieurs"]'::jsonb, 3, 'Elle se passe largement d’engrais et de pesticides, mais ses rendements sont souvent plus faibles.', 3),
    ('2f1e848a-8e76-52db-8624-4b4c18582a17'::uuid, 'svt', '6e', 'Nourrir les hommes : la culture et l’élevage', 'Lequel de ces produits est un engrais organique ?', 'mcq', '["Le sable","Le fumier","Le sel","L’eau de pluie"]'::jsonb, 1, 'Les engrais sont organiques (comme le fumier) ou minéraux ; ils restituent au sol les sels minéraux prélevés.', 4),
    ('53e07cb1-71f7-5b62-ac3d-ae31b01138a6'::uuid, 'svt', '6e', 'La production et la conservation des aliments', 'Que signifie la DDM sur un emballage ?', 'mcq', '["Un danger pour la santé après cette date","Une baisse de qualité possible, sans danger","La date de fabrication","Une date à ne jamais dépasser"]'::jsonb, 1, 'La DDM (« à consommer de préférence avant ») annonce une baisse de qualité, pas un danger, contrairement à la DLC.', 1),
    ('91c46dbe-2d76-597b-915d-a18ef68f9989'::uuid, 'svt', '6e', 'La production et la conservation des aliments', 'Que retire le séchage aux micro-organismes ?', 'mcq', '["La chaleur","Les nutriments","L’eau","Le dioxygène"]'::jsonb, 2, 'Le séchage retire l’eau dont les micro-organismes ont besoin pour se multiplier.', 2),
    ('bf8eb121-5423-587d-a6e1-751595a91f60'::uuid, 'svt', '6e', 'La production et la conservation des aliments', 'À quelle température se situe le congélateur ?', 'mcq', '["4 °C","0 °C","−5 °C","−18 °C"]'::jsonb, 3, 'À −18 °C, la multiplication des micro-organismes est presque arrêtée, mais ils ne sont pas tués.', 3),
    ('a565f64c-707f-508e-8b55-5e512a287a13'::uuid, 'svt', '6e', 'La production et la conservation des aliments', 'Quel geste simple évite la plupart des intoxications alimentaires ?', 'mcq', '["Se laver les mains","Recongeler les restes","Laisser les plats dehors","Mélanger le cru et le cuit"]'::jsonb, 0, 'Se laver les mains, respecter la chaîne du froid et séparer le cru du cuit sont les gestes d’hygiène de base.', 4),
    ('c83b684f-7c73-5109-b92c-c313f37f86c2'::uuid, 'svt', '6e', 'La cellule, unité de définition de l’être vivant', 'Où se déroulent les réactions dans une cellule ?', 'mcq', '["Dans le cytoplasme","Dans la membrane","Dans la paroi","Dans le microscope"]'::jsonb, 0, 'Le cytoplasme est le milieu gélatineux de la cellule où se déroulent les réactions.', 1),
    ('5f2e28db-2120-552e-aac9-46c4aff85ffc'::uuid, 'svt', '6e', 'La cellule, unité de définition de l’être vivant', 'Quel est le rôle de la membrane d’une cellule ?', 'mcq', '["Contenir l’information génétique","Délimiter la cellule et contrôler les échanges","Réaliser la photosynthèse","Donner une forme rigide"]'::jsonb, 1, 'La membrane délimite la cellule et contrôle ce qui entre et sort.', 2),
    ('761fcfbb-e87c-59bf-83c2-e2c417fbe638'::uuid, 'svt', '6e', 'La cellule, unité de définition de l’être vivant', 'Combien de cellules compte environ un être humain ?', 'mcq', '["30 millions","30 milliards","30 000 milliards","300 000"]'::jsonb, 2, 'L’être humain est pluricellulaire : environ 30 000 milliards de cellules, organisées en tissus et en organes.', 3),
    ('937f0394-960b-5475-8d90-53683fd48800'::uuid, 'svt', '6e', 'La cellule, unité de définition de l’être vivant', 'Lequel de ces êtres vivants est unicellulaire ?', 'mcq', '["Le chêne","La fourmi","L’humain","La levure"]'::jsonb, 3, 'La levure, comme la bactérie et la paramécie, est formée d’une seule cellule.', 4),
    ('d31c6f66-98cb-5664-94b2-9afcd3d8288e'::uuid, 'svt', '6e', 'La classification des êtres vivants', 'Combien de pattes possède une araignée ?', 'mcq', '["Six","Huit","Dix","Quatre"]'::jsonb, 1, 'Les araignées sont des arachnides : 8 pattes, contre 6 pour les insectes.', 1),
    ('5a07a89b-4f66-5139-a8f0-c1c1a9edab8e'::uuid, 'svt', '6e', 'La classification des êtres vivants', 'Lequel de ces animaux est un mollusque ?', 'mcq', '["Le crabe","La fourmi","L’escargot","Le lézard"]'::jsonb, 2, 'Les mollusques ont un corps mou, souvent protégé par une coquille : escargot, moule, poulpe.', 2),
    ('e45e6973-0e2a-5820-a97f-05d9bc6fa04c'::uuid, 'svt', '6e', 'La classification des êtres vivants', 'Quel est le nom scientifique de l’espèce humaine ?', 'mcq', '["Homo sapiens","Canis lupus","Homo vertebratus","Sapiens homo"]'::jsonb, 0, 'Le nom scientifique s’écrit en latin, en deux mots : Homo sapiens.', 3),
    ('4edea646-d5b1-57b2-8bb7-bc7a88c6ba56'::uuid, 'svt', '6e', 'La classification des êtres vivants', 'Un primate possède tous les attributs de quel groupe plus large ?', 'mcq', '["Les insectes","Les arthropodes","Les mollusques","Les mammifères"]'::jsonb, 3, 'Les groupes sont emboîtés : un primate est un mammifère, donc il en a tous les attributs (poils, mamelles).', 4),
    ('f235b7ed-6762-5a2c-a4f5-dfa890612c73'::uuid, 'svt', '6e', 'L’évolution des espèces', 'Que prouvent les fossiles ?', 'mcq', '["Que les espèces ne changent pas","Que tous les animaux sont éteints","Que des espèces différentes des actuelles ont vécu","Que la vie est apparue hier"]'::jsonb, 2, 'Les fossiles montrent que d’autres espèces ont vécu et permettent de les dater.', 1),
    ('d3e8a7f3-1baa-55bc-b0b2-ab28edd63484'::uuid, 'svt', '6e', 'L’évolution des espèces', 'Combien d’extinctions de masse ont éliminé une grande part du vivant ?', 'mcq', '["Dix","Cinq","Une seule","Deux"]'::jsonb, 1, 'Cinq extinctions de masse ont eu lieu, dont celle qui a fait disparaître les dinosaures non-aviens.', 2),
    ('be025d2e-e33b-5723-ac27-7230da0c64ed'::uuid, 'svt', '6e', 'L’évolution des espèces', 'Laquelle de ces actions menace la biodiversité ?', 'mcq', '["La destruction des milieux","La photosynthèse","La reproduction sexuée","La fossilisation"]'::jsonb, 0, 'Destruction des milieux, pollution, surexploitation et réchauffement font reculer le vivant.', 3),
    ('a303272d-ed03-561a-a4b3-5e2d234d21c7'::uuid, 'svt', '6e', 'L’évolution des espèces', 'Pourquoi les mammifères se sont-ils diversifiés après l’extinction de 66 millions d’années ?', 'mcq', '["Ils sont apparus à ce moment-là","Ils ont mangé tous les fossiles","Le climat est resté identique","Une place s’est libérée"]'::jsonb, 3, 'Les dinosaures non-aviens ayant disparu, les mammifères se sont diversifiés dans la place libérée.', 4),
    ('4de72549-24a1-5d95-bc30-0fb37381a1ae'::uuid, 'technologie', '6e', 'Le besoin et la fonction d’usage', 'Comment s’écrit une fonction d’usage ?', 'mcq', '["Par un nom suivi d’un prix","Par un verbe à l’infinitif suivi d’un complément","Par une phrase décrivant la matière","Par une liste de dimensions"]'::jsonb, 1, 'Une fonction d’usage s’écrit avec un verbe à l’infinitif : « Protéger de la pluie », « Se déplacer ».', 1),
    ('7a0268c7-b2bd-5476-a353-ae560cf7df30'::uuid, 'technologie', '6e', 'Le besoin et la fonction d’usage', 'Quelle est la fonction d’usage d’une lampe ?', 'mcq', '["Consommer peu d’énergie","Avoir un joli pied","Éclairer un espace","Se brancher au secteur"]'::jsonb, 2, 'La fonction d’usage répond à « à quoi ça sert ? » : une lampe sert à éclairer un espace.', 2),
    ('86ef88c2-6d62-5934-8abd-acf7d3d03694'::uuid, 'technologie', '6e', 'Le besoin et la fonction d’usage', 'Que dit le cahier des charges d’un objet ?', 'mcq', '["Comment le fabriquer étape par étape","Quelle marque choisir","Combien de temps il a fallu","Ce que l’objet doit faire, sans dire comment"]'::jsonb, 3, 'Le cahier des charges est un contrat : il liste les contraintes, il ne dit jamais comment les respecter.', 3),
    ('8cc3b8c9-8f2d-5d67-86cc-785894c6c0dc'::uuid, 'technologie', '6e', 'Le besoin et la fonction d’usage', 'Deux sacs à dos rendent le même service. On choisit celui de sa couleur préférée. Quelle fonction joue ?', 'mcq', '["La fonction d’estime","La fonction d’usage","La fonction technique","La contrainte de poids"]'::jsonb, 0, 'La fonction d’estime explique pourquoi on achète celui-là : couleur, forme, marque ou prix.', 4),
    ('b05e9038-ff96-5e8c-8084-94811b862297'::uuid, 'technologie', '6e', 'Les fonctions techniques et les solutions', 'Laquelle de ces solutions techniques permet de freiner ?', 'mcq', '["Le guidon","La selle","La chaîne","Le frein à disque"]'::jsonb, 3, 'Patins, frein à disque ou rétropédalage sont des solutions possibles pour la fonction technique « freiner ».', 1),
    ('d2e7dbd6-3fa3-538b-a2ac-5d32da41c352'::uuid, 'technologie', '6e', 'Les fonctions techniques et les solutions', 'Quelle fonction technique le cadre et la selle assurent-ils sur un vélo ?', 'mcq', '["Soutenir l’utilisateur","Diriger","Freiner","Transmettre le mouvement"]'::jsonb, 0, 'Le cadre et la selle soutiennent l’utilisateur.', 2),
    ('471d13e8-26fa-55c6-acb5-53059482167e'::uuid, 'technologie', '6e', 'Les fonctions techniques et les solutions', 'Quels organes assurent la fonction technique « diriger » d’un vélo ?', 'mcq', '["Le pédalier et la chaîne","Les leviers et les patins","Le guidon et la fourche","Le cadre et la selle"]'::jsonb, 2, 'Le guidon et la fourche permettent de diriger le vélo.', 3),
    ('f43d46bd-9ef2-55e0-8de8-4446f581edf6'::uuid, 'technologie', '6e', 'Les fonctions techniques et les solutions', 'Un même composant peut servir plusieurs fonctions.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Un ressort, une vis ou un engrenage peuvent intervenir dans plusieurs fonctions d’un même objet.', 4),
    ('7cfc63d0-74d8-55a3-9c95-b02e6309d79a'::uuid, 'technologie', '6e', 'L’évolution des objets techniques', 'Comment appelle-t-on un objet suivi à travers le temps ?', 'mcq', '["Une famille","Une lignée","Une gamme","Un prototype"]'::jsonb, 1, 'Une lignée suit un objet à travers le temps ; une famille regroupe des objets de même fonction à une même époque.', 1),
    ('accdf798-7a4e-522a-897c-e899fc19398f'::uuid, 'technologie', '6e', 'L’évolution des objets techniques', 'Dans la lignée de l’éclairage, quel objet précède la lampe à incandescence ?', 'mcq', '["La bougie","La LED","Le bec de gaz","La lampe fluocompacte"]'::jsonb, 2, 'La lignée est : feu, bougie, lampe à huile, bec de gaz, incandescence, fluocompacte, LED.', 2),
    ('8d9d82fa-d1ad-5168-9928-1211b22be177'::uuid, 'technologie', '6e', 'L’évolution des objets techniques', 'Lois de sécurité, normes et préoccupations environnementales : quel moteur d’évolution est en jeu ?', 'mcq', '["Le progrès technique","L’économie","Le besoin","La société"]'::jsonb, 3, 'La société fait évoluer les objets par ses lois, ses normes et ses préoccupations environnementales.', 3),
    ('2c7d0f4d-b54d-59cb-9754-fcb16cd9da2f'::uuid, 'technologie', '6e', 'L’évolution des objets techniques', 'Quand la LED remplace la bougie, qu’est-ce qui change ?', 'mcq', '["La solution technique","Le besoin de lumière","La fonction d’usage","Le nom de l’objet"]'::jsonb, 0, 'On a toujours besoin de lumière : la fonction d’usage reste, seule la solution technique change.', 4),
    ('33aff3b2-6f5f-59a7-8940-548e454580d0'::uuid, 'technologie', '6e', 'Les familles de matériaux', 'À quelle famille appartiennent le bois, le papier et le cuir ?', 'mcq', '["Les métaux","Les céramiques","Les matériaux organiques","Les plastiques"]'::jsonb, 2, 'Bois, papier et cuir sont des matériaux organiques, renouvelables.', 1),
    ('fc41bac3-c2f8-5978-8cfc-a98275991234'::uuid, 'technologie', '6e', 'Les familles de matériaux', 'Quelle propriété indique qu’un matériau est léger ou lourd à volume égal ?', 'mcq', '["La masse volumique","La dureté","L’élasticité","La conductivité"]'::jsonb, 0, 'La masse volumique compare la masse de matériaux pour un même volume.', 2),
    ('14182930-7d89-5c8e-88d3-f6b4c29c9528'::uuid, 'technologie', '6e', 'Les familles de matériaux', 'Quelle production initiale consomme énormément d’électricité tout en donnant un métal très recyclable ?', 'mcq', '["Celle du verre","Celle de l’aluminium","Celle du bois","Celle du papier"]'::jsonb, 1, 'Recyclable ne veut pas dire bon marché à produire : l’aluminium neuf demande énormément d’électricité.', 3),
    ('8454239f-9858-53c4-afa9-3b238161f2e2'::uuid, 'technologie', '6e', 'Les familles de matériaux', 'Lequel de ces matériaux est un composite ?', 'mcq', '["Le cuivre","Le verre","Le papier","Le béton armé"]'::jsonb, 3, 'Le béton armé associe béton et acier pour cumuler leurs qualités ; les composites sont difficiles à recycler.', 4),
    ('b757bc37-d3f4-557c-a429-003951de4b42'::uuid, 'technologie', '6e', 'L’impact environnemental des objets', 'Quel est le levier d’action juste après « ne pas produire l’objet » ?', 'mcq', '["Le recycler","L’incinérer","Allonger sa durée de vie","Le jeter"]'::jsonb, 2, 'Après ne pas produire, on allonge la durée de vie (entretenir, réparer, revendre) ; recycler n’arrive qu’en quatrième.', 1),
    ('e534ba37-c920-5d1a-9303-0d7c9c73fd79'::uuid, 'technologie', '6e', 'L’impact environnemental des objets', 'En quelle année l’indice de réparabilité est-il devenu obligatoire en France ?', 'mcq', '["2005","2021","2015","1990"]'::jsonb, 1, 'Depuis 2021, une note de réparabilité doit être affichée sur certains produits.', 2),
    ('10288bc7-861e-59cb-b038-4ec8a584fa35'::uuid, 'technologie', '6e', 'L’impact environnemental des objets', 'Quel geste réduit le plus l’impact d’un smartphone ?', 'mcq', '["Le garder deux ans de plus","Le recharger la nuit","L’éteindre souvent","Changer sa coque"]'::jsonb, 0, 'Son impact est surtout dans la fabrication : retarder son remplacement pèse plus que sa recharge.', 3),
    ('68c4c7c9-aa7f-573d-8336-c480143a2c52'::uuid, 'technologie', '6e', 'L’impact environnemental des objets', 'Quel assemblage favorise l’écoconception ?', 'mcq', '["La colle","Le rivet","La soudure","Les vis"]'::jsonb, 3, 'Un assemblage démontable, comme les vis, permet de réparer et de recycler.', 4),
    ('d96887ce-3040-54d2-a101-0fc5465859d8'::uuid, 'technologie', '6e', 'La chaîne d’information et la chaîne d’énergie', 'Quel capteur ou actionneur convertit l’énergie électrique en lumière ?', 'mcq', '["Le capteur de présence","La lampe","Le relais","La pile"]'::jsonb, 1, 'La lampe est un actionneur : elle convertit l’énergie électrique en lumière.', 1),
    ('8c49ed5c-e7f7-5217-8764-ec273af1b107'::uuid, 'technologie', '6e', 'La chaîne d’information et la chaîne d’énergie', 'Quel est le rôle d’un relais dans la chaîne d’énergie ?', 'mcq', '["Acquérir une mesure","Convertir l’énergie","Traiter l’information","Distribuer l’énergie"]'::jsonb, 3, 'Un interrupteur ou un relais distribue : il laisse passer l’énergie ou non.', 2),
    ('a9dcc62e-dda3-5e6e-a039-58449287f53c'::uuid, 'technologie', '6e', 'La chaîne d’information et la chaîne d’énergie', 'Le capteur de présence n’a rien détecté et la lampe reste éteinte. Quelle chaîne est concernée ?', 'mcq', '["La chaîne d’information","La chaîne d’énergie","Les deux","Aucune"]'::jsonb, 0, 'Le capteur fait partie de la chaîne d’information ; l’alimentation coupée serait un problème d’énergie.', 3),
    ('e6d6e85f-3bde-59bb-8ab8-91a073a6d9ac'::uuid, 'technologie', '6e', 'La chaîne d’information et la chaîne d’énergie', 'Lequel de ces éléments alimente la chaîne d’énergie ?', 'mcq', '["Le capteur","La carte programmable","La batterie","Le haut-parleur"]'::jsonb, 2, 'Pile, batterie, secteur ou panneau solaire fournissent l’énergie.', 4),
    ('72122f74-6fc1-50be-b5f9-8ef8e327ed7a'::uuid, 'technologie', '6e', 'Programmer un objet technique', 'Que signifie « téléverser » un programme ?', 'mcq', '["L’effacer","Le dessiner","L’envoyer dans la carte","Le corriger"]'::jsonb, 2, 'Le programme s’écrit sur ordinateur puis se téléverse dans la carte programmable.', 1),
    ('77356375-31ba-5368-a6da-dbb14f5726e8'::uuid, 'technologie', '6e', 'Programmer un objet technique', 'Que représente le losange dans un organigramme ?', 'mcq', '["Une action","Une décision","Une répétition","Une variable"]'::jsonb, 1, 'Rectangle pour une action, losange pour une décision, flèche pour l’ordre d’exécution.', 2),
    ('b0679c80-07d6-55a7-bac5-b6470de42fe5'::uuid, 'technologie', '6e', 'Programmer un objet technique', 'Quand un programme donne un résultat surprenant, où est le plus souvent le problème ?', 'mcq', '["Dans la carte","Dans le câble","Dans la pile","Dans l’intention, restée floue"]'::jsonb, 3, 'La machine exécute exactement ce qui est écrit : c’est presque toujours l’intention qui était floue.', 3),
    ('8bdeb208-eb33-57f0-97f9-09c3cf734971'::uuid, 'technologie', '6e', 'Programmer un objet technique', 'Un bug est une étape normale de la programmation.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Tester, isoler l’instruction fautive, corriger puis retester fait partie du travail.', 4),
    ('24c3253a-23e3-5d94-a3f1-caa9660517bf'::uuid, 'technologie', '6e', 'L’information et sa circulation', 'Quel est l’ordre de grandeur du poids d’une photo prise avec un téléphone ?', 'mcq', '["Quelques Mo","Quelques To","Quelques bits","Quelques Go"]'::jsonb, 0, 'Une photo pèse quelques mégaoctets (Mo) ; un film pèse quelques gigaoctets (Go).', 1),
    ('dc38c825-ca74-579a-b98e-d0f12f719f07'::uuid, 'technologie', '6e', 'L’information et sa circulation', 'Comment appelle-t-on Internet ?', 'mcq', '["Un cloud unique","Le réseau des réseaux","Un câble mondial","Une adresse IP"]'::jsonb, 1, 'Un réseau relie des machines ; Internet est le réseau des réseaux.', 2),
    ('756b9680-9601-557a-825b-248545da7417'::uuid, 'technologie', '6e', 'L’information et sa circulation', 'Lequel de ces gestes protège l’information ?', 'mcq', '["Le même mot de passe partout","Ne jamais faire de mises à jour","Un mot de passe solide","Tout publier en ligne"]'::jsonb, 2, 'Un mot de passe solide, des mises à jour et de la prudence sur ce qu’on publie renforcent la sécurité.', 3),
    ('77c2793c-9d7a-5772-b37b-eb88a0b062a9'::uuid, 'technologie', '6e', 'L’information et sa circulation', 'Quel support transmet l’information sans fil, dans l’air ?', 'mcq', '["La fibre optique","Le câble électrique","Le fil de verre","Les ondes wifi"]'::jsonb, 3, 'Wifi, Bluetooth et téléphonie sont des ondes qui voyagent sans fil.', 4),
    ('4f90f780-139c-5412-8f91-9eae326a094d'::uuid, 'technologie', '6e', 'Croquis, schémas et plans', 'Que signifie l’échelle 10:1 ?', 'mcq', '["Le dessin est 10 fois plus petit","Le dessin est à taille réelle","Le dessin est 10 fois plus grand","L’objet mesure 10 mm"]'::jsonb, 2, 'Une échelle 10:1 agrandit dix fois le dessin, utile pour une petite pièce.', 1),
    ('f2bef8bc-6521-54e9-b1f8-5f83a8ee016a'::uuid, 'technologie', '6e', 'Croquis, schémas et plans', 'Sur un plan à l’échelle, qu’indique une cote ?', 'mcq', '["La dimension réelle de la pièce","La longueur du trait sur le papier","Le prix de la pièce","L’échelle du dessin"]'::jsonb, 0, 'La cote donne la dimension réelle, en millimètres, quelle que soit l’échelle ; on lit la cote, on ne mesure pas.', 2),
    ('2026868e-1d83-54bf-8be1-5698cbcd39b8'::uuid, 'technologie', '6e', 'Croquis, schémas et plans', 'Quel dessin dit « voilà comment le faire » ?', 'mcq', '["Le croquis","Le plan","Le schéma","La perspective"]'::jsonb, 1, 'Le plan est à l’échelle et coté : il sert à fabriquer l’objet.', 3),
    ('dc7a2499-4d8c-5cdd-abdf-0ce811c4b8f7'::uuid, 'technologie', '6e', 'Croquis, schémas et plans', 'Vers quelle machine peut-on envoyer directement un fichier de CAO ?', 'mcq', '["Une photocopieuse","Un four","Un scanner","Une imprimante 3D"]'::jsonb, 3, 'Le fichier de conception assistée par ordinateur peut partir vers une imprimante 3D ou une découpeuse.', 4),
    ('f1ff5404-0be8-55bd-bbd2-a34b8b7a6b8f'::uuid, 'technologie', '6e', 'Fabriquer un objet', 'Lequel de ces outils sert à découper une pièce ?', 'mcq', '["Le pied à coulisse","La découpeuse laser","Le pinceau","Le gabarit"]'::jsonb, 1, 'Scie, cisaille et découpeuse laser servent à découper.', 1),
    ('e28f0d55-e971-5b73-983e-aad0c68a84e4'::uuid, 'technologie', '6e', 'Fabriquer un objet', 'Que fait-on d’une pièce hors tolérance ?', 'mcq', '["On l’accepte","On la peint","On la vend","On la refuse"]'::jsonb, 3, 'La tolérance est l’écart acceptable autour de la cote : hors tolérance, la pièce est refusée.', 2),
    ('c0bb568a-942a-50e7-a650-d78cfa8ae930'::uuid, 'technologie', '6e', 'Fabriquer un objet', 'Lequel de ces assemblages est permanent ?', 'mcq', '["La soudure","La vis","Le boulon","Le clip"]'::jsonb, 0, 'Colle, soudure et rivet sont permanents : plus solides, mais difficiles à réparer.', 3),
    ('86d8dcc7-a4fb-5851-84aa-beb992783150'::uuid, 'technologie', '6e', 'Fabriquer un objet', 'À quoi servent les outillages d’une fabrication en série ?', 'mcq', '["À réduire le prix de la colle","À tester une idée","À rendre chaque pièce identique","À décorer les pièces"]'::jsonb, 2, 'Après le prototype, des outillages rendent chaque pièce de la série identique.', 4)
  ) AS v(id, slug, level, chapter, question, kind, options, correct_index, explanation, rang)
  JOIN public.subjects s ON s.slug = v.slug
  JOIN public.chapters c ON c.subject_id = s.id AND c.level = v.level AND c.title = v.chapter
  JOIN LATERAL (
    SELECT qz.id FROM public.lessons l
      JOIN public.quizzes qz ON qz.lesson_id = l.id
     WHERE l.chapter_id = c.id
     ORDER BY l.position, qz.id
     LIMIT 1
  ) qz ON true
ON CONFLICT (id) DO NOTHING;

